/* 令和5年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r05.committeeSessions.push(...[{"id":"r05-20230306-3","meetingId":"r05-c-budget","date":"2023年3月6日","dateIso":"2023-03-06","committee":"予算特別委員会","time":"午前１０時００分～午後 ６時０５分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を183件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"湯澤副委員長","kind":"質問","question":"第４項、款別審査の質疑等につきましてです。なお、質問時間は、会派におかれましては、１人当たりの質問時間は、答弁時間も含めて、１０分、１５分、２０分のいずれかとし、無所属の委員は、答弁時間も含めて、１日につき１０分となります。終了時刻のお知らせにつきましては、残り時間が少なくなった時点で振鈴を２回鳴らしますので、質問の途中でありましても、直ちに取りやめていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"渡辺委員","kind":"質問・要望","question":"よろしくお願いします。私は、８ページの歳入全般、そして８７ページ、給食施設整備費の２点を伺います。この辺りの傾向が大体このような形で例年と変わりないものなのか、あるいは、この年度に特別な事案があったかどうかの確認をしたいです。給食施設整備費２,０００万円の予算減額で、どちらの学校、あるいは内容が、どのようなものなのか教えてください。","respondent":"黒田財政課長、勝亦学務課長","answer":"令和４年度補正予算の歳入の概況ですが、まず区民税ですが、こちらは、当初予算編成時は、令和３年度の最終補正予算額を若干下回った、人口が少し減っていたという状況がありまして、そういった形で当初予算を編成しておったのですが。給食室の改修工事等につきましては、８校ほどの工事を行いまして、その中で、給排気設備改修、それから冷媒配管工事といったものの、主なものとしては荏原第一中学校の給排気工事、小山小学校の冷媒配管工事。","id":"exchange-002"},{"speaker":"渡辺委員","kind":"質問・要望","question":"こちらの要望も、私たちも受け止めまして、やはりお願いベースにもなりますが、ぜひとも対象のところで枠内にしていただきたいという要望を受けています。その中で、やはりスピード感というキーワードとともに、できれば年度当初、あるいはそこに近い形で、特別支援学校への給食費無償化もぜひお含みいただきたいというのが、私たち自民党の改めての要望になりますので、この辺のお考えもお知らせください。","respondent":"提坂税務課長、勝亦学務課長","answer":"特別徴収につきましては、納税義務者数が、当初見込んだ数よりも８００人弱ぐらい増えたということと、あと、給与所得者に係る課税標準額が７００万円を超える高所得者が、前年よりも１,２００人ほど増になった。とはいいながら、様々、区立学校との交流等もあります。現状把握等に努めているところではありますが、支援の実施につきましては前向きに検討していきたいと考えています。","id":"exchange-003"},{"speaker":"渡辺委員","kind":"質問","question":"初めに区民税のところ、大変に数字が大きいというのが感想です。高所得の方が１,２００名、あるいはそれぞれの数字も大きいのですが、この令和４年度に限らず、傾向として、では来年度はどうなのだろう、あるいは中長期で見てどうなのだろう。給食費は、この案件でいろいろ調べていく中で、まず今、前向きに検討ということで、ぜひともこれはもうお願いしたい。その辺を教えてください。","respondent":"提坂税務課長、勝亦学務課長","answer":"ここ二、三年の傾向と申しますと、やはり新型コロナウイルス感染症をかなり重く見なければいけない部分があるのですけれども、かなり影響を受けて、税収が減になるのではないかと見込んでいた部分はあったのですが。物価上昇が継続していますので、来年度お願いしております無償化の単価につきましては、小学校１食に１５円、中学校１食２０円を上乗せした単価で無償化を進めて、１食をつくっていきたいと考えています。","id":"exchange-004"},{"speaker":"渡辺委員","kind":"質問・要望","question":"まさに給食費のところはそこを伺いたくて、補正で対応しました、翌年度冒頭にどういう含みで予算が編成されるのか知りたかったところ、今のところ十分踏まえられていると思われますので、またこの物価は本当に想像を超える上げ幅や変化がありますので、この辺の柔軟さというものが非常に大事かなと思われます。引き続きのご対応をお願いしたいと思います。そういう意味で、政策的な趣旨の確認です。","respondent":"佐藤企画調整課長","answer":"品川区といたしましても、少子化対策、また子育て支援、また委員ご指摘のとおり、そういった政策が品川区全体のまちづくりや活性化につながるというところで、非常に重要な政策だと考えております。","id":"exchange-005"},{"speaker":"新妻委員","kind":"質問","question":"私からは、７５ページ、私立幼稚園経費、私立幼稚園保護者補助金について、８３ページ、公園・児童遊園維持管理費から、公園内の多言語化についてお伺いいたします。初めに、私立幼稚園保護者補助金について、内容をお知らせください。","respondent":"中元保育支援課長","answer":"こちらは、私立幼稚園に対し、区が、子どもが通園している保護者の経済的負担を軽減するため、保護者の方の所得に応じて保育料の一部を補助させていただいている事業です。","id":"exchange-006"},{"speaker":"新妻委員","kind":"質問","question":"分かりました。先月、２月２８日の文教委員会で、私立幼稚園の新制度への移行についての報告がありました。区内で初めて、新制度へ１園が移行とのことです。この新制度につきまして簡潔にご説明いただき、次に、幼稚園に通う保護者の方々にとって、この私立幼稚園保護者補助金に関しては何か影響があるのか、お伺いいたします。","respondent":"中元保育支援課長","answer":"新制度についてのお尋ねです。こちらは、平成２７年度に開始されました、子ども・子育て関連３法に基づく子ども・子育て支援新制度のことを略して、新制度と総称しているものです。","id":"exchange-007"},{"speaker":"新妻委員","kind":"確認","question":"ご説明ありがとうございました。特に保護者に関しては影響がないということを確認させていただきました。次に、新制度に移行した場合、私立幼稚園と在園保護者それぞれについて、どのように、何か変わることがあるのか、主な変更点を伺います。これまでの幼児教育に影響があるのか、伺います。","respondent":"中元保育支援課長","answer":"ですので、新制度への移行は、施設が利用者の方に提供している教育・保育の内容に何ら変更を加えるものではございません。従来から各私立幼稚園で行われている保育・教育の内容が、園の方針や理念に変更がない限り、引き続き実施されることとなります。","id":"exchange-008"},{"speaker":"新妻委員","kind":"質問","question":"分かりました。今後ですけれども、この新制度を、区として私立幼稚園に対して新制度移行を推進されていくのか、区のお考えをお伺いします。","respondent":"中元保育支援課長","answer":"私立幼稚園には各園のこれまでのそれぞれ成り立ちもございまして、区としましては、私立幼稚園の自主性を尊重しつつ、ご希望があれば、区が可能な範囲で手続をサポートするということで、進めてまいりたいと考えています。","id":"exchange-009"},{"speaker":"新妻委員","kind":"質問","question":"分かりました。平成２７年度にこの制度ができてから、今回初めて１園が移行ということで、かなり園の準備といいますか、そういう負担があったのかなと思います。新制度移行に向けては、園側の様々な事務的な準備が必要であります。具体的なスケジュールと、園側の事務負担や、その負担に対して区がどのような支援をしていただけるのか、お伺いいたします。","respondent":"中元保育支援課長","answer":"今年度は７月に私立幼稚園園長会におきまして、新制度の説明会を実施いたしました。","id":"exchange-010"},{"speaker":"新妻委員","kind":"提案","question":"関連いたしまして、次に、幼児保育・教育の視点で、保育園ではなく３年保育の私立幼稚園にお子さんを預けたいと考えられる保護者がいらっしゃいます。将来的な展望として、保育園での空き定員を活用し、特に春・夏・冬の長期休暇の際の一時預かりの拡充を進めて、幼稚園と保育園の一時預かりをつなげていく仕組みづくりを、ぜひ提案しますが、見解を伺います。","respondent":"中元保育支援課長","answer":"将来的には、こちらの一時保育を、制度を整えまして、長期休業中に私立幼稚園の皆様にも拡充していければと考えているところです。","id":"exchange-011"},{"speaker":"新妻委員","kind":"提案","question":"ぜひ、よろしくお願いいたします。その際、子育て支援に関してのポータルサイトを作成してほしいというお声を頂きました。保護者からは、国や東京都、区、それぞれの使える補助金や助成金が分かるようにしてほしい。いろいろ様々ハードルがあるかと思いますけれども、ぜひ品川区でも、子ども・子育て支援に関する全てがまとまったポータルサイトの作成を提案いたしますが、見解を伺います。","respondent":"廣田子ども育成課長","answer":"令和４年度、本年度から検討を開始しまして、令和５年度にはリニューアルを考えておりますので、これから工夫していきたいと思います。","id":"exchange-012"},{"speaker":"新妻委員","kind":"質問・要望","question":"ぜひ工夫していただきながら、今できることを早急に進めていただきたいと思います。公園に関しましてお伺いしたかったのですが、時間がなくなってしまいました。改めてお伺いしますが、区内の公園・児童遊園における注意事項等の多言語化についてお伺いしたいと思います。改めてお伺いいたしますので、ご答弁は結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"安藤委員","kind":"質問","question":"８３ページ、地域交通検討経費、コミュニティバスについて伺います。新年度は当初から１時間３本での運行になるわけですけれども、伺いますけれども、来年度からは大井ルートの運行経費は年間で幾らぐらいになる見通しなのか、伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"来年度のコミュニティバスの運行経費補助の金額ですが、６,１００万円程度です。","id":"exchange-014"},{"speaker":"安藤委員","kind":"質問","question":"区は評価基準を定めていますけれども、年間の運行経費に対する収入の割合が５０％以上。試行運行３年目で、この基準を満たさない場合、廃止を含む見直しをする判断を行うとしています。さらに、１年目、２年目も評価を行おうとしていますけれども、１年目の今年もそろそろ終わろうとしているのですが、区のつくった評価基準を満たしそうなのか、見通しを伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"３月末から試行運行を開始しまして、１月末までの状況ですが、現在のところ、シルバーパスの分、シルバーパスは基本的には無料でご乗車いただくわけですが、その分を補填した形で、現在の収支率が５８.６％というような状況です。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問","question":"見通しはありそうですね。ただ、もともと運行前から廃止の基準をつくるということ自体がおかしいと思います。伺いますけれども、他自治体を参考にしたというのであれば、他自治体の状況、特に２３区の状況を伺いたいなと。収支率を設定している区は、２３区中、何区あるのか。５０％以上に設定しているという区は何区あるのか、伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"調査をかけた時点での数字ですが、コミュニティバス運行区のうち６区が判断基準を設定しています。そのうち、５０％以上の区が５区というような状況です。","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問・要望","question":"非常に少ないですよね。私も渋谷区に問い合わせましたけれども、担当者の方に「収支率というのは設定しているのですか」と聞いたら、「え、収支率ですか」というリアクションだったのです。収支率５０％で、廃止を含め見直しとの考え方は、地域公共交通会議でもぜひ議論していただいて廃止してもらって、利用者を増やす努力こそ行っていただきたいと思いますけれども、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"現在、試行運行ですので、その状況を適宜、地域公共交通会議でもお示ししながら、様々な取組について検討していきたいです。","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問・要望","question":"大崎はどうなのかということで、困ったことに、この間、大井町駅に行くバスが不便になりまして、昨年１１月からの、渋谷から大井町まで出ていた東急バスの品川・高輪系統新設および渋谷４１・４２系統のダイヤ改正なのですけれども、伺いたいのですが、この改正により、渋谷から山手通りを通って大崎を経由して大井町に行く。この運行本数はどうなったのか、伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"運行本数等の詳細な部分については把握してございませんが、基本的には利用実態に合わせて、今後も継続してダイヤ等については適宜見直しを行っていくと聞いているところです。","id":"exchange-018"},{"speaker":"安藤委員","kind":"質問","question":"把握してもらいたいのですけれども、半減したのです。住民の方からも、障害をお持ちの方なのですけれども、不便になって困っているという声も頂きました。大崎ルートですけれども、目黒駅と五反田駅からは大井町駅への直接バスのルートがない。この大崎ルートは、先ほどの紹介した区の考え方に照らしても、一日も早く運行を始めるべきだと思うのですけれども、いかがでしょうか。区の考えを伺います。","respondent":"鈴木都市計画課長","answer":"残りの候補案、今お尋ねの大崎ルートにつきましては、基本的には現在、試行運行を開始している大井ルートの状況を見ながら、適時適切に判断していくです。","id":"exchange-019"},{"speaker":"安藤委員","kind":"質問","question":"大井ルートと大崎ルートは、ルートが違いますよね。当然、需要も乗客も違います。別ルートなのですよね。だから、別ルートの大崎ルートは、大崎ルートで試行運行してみないと、結局は分かりません。大井ルートは参考程度にはなると思います。大崎ルートの試行運行は、なぜ大井ルートの試行を待たないと行わないのか、合理的な説明があれば伺います。","respondent":"鈴木都市計画課長","answer":"そうした意味では、それを一定、一年、二年、その推移・経過を見守って、しっかり、残りの２ルートの実施の方向性についても検討していきたいです。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問・要望","question":"全く納得のいく説明ではないと思います。コミュニティバスによる移動の権利保障は、全ての区の施策の土台にもなりますし、高齢者の外出も促しますし、大崎ルートの一日も早い早期運行と、料金は１００円に下げ、便利で使いやすいコミュニティバスの実現を求めて質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"松永委員","kind":"質問","question":"私からは、４５ページの防災・安全交付金について、そして５９ページのふるさと納税寄附金について、７７ページの新型コロナワクチンの集団接種会場運営委託について、最後に時間がありましたら、８５ページの高層マンション対策リーフレット作成等経費についてお伺いします。この主な内容と、事業についての補助金がどういった補助金なのか、お知らせください。","respondent":"平原防災課長","answer":"こちらの防災普及教育費ですけれども、災害時に必要となりますハザードマップの作成経費に対しましての国費補助でございまして、今年度、防災地図を見直した中にハザードマップ全てを入れさせていただいたところの国庫補助です。","id":"exchange-022"},{"speaker":"松永委員","kind":"質問","question":"災害についてですが、いつ起こるか分かりません。そこで、災害時について、どのように、またどこに避難すればいいのかということで、マップはつくられたと思うのですが、これは命を守るためにはとても重要なことであります。そこで区では、今回、ハザードマップを更新されたということですが、区民に対してどのように周知を行っていかれるのでしょうか。伺います。","respondent":"平原防災課長","answer":"今回、平成３０年度に作成いたしました品川区防災地図を全面リニューアルさせていただいたところでございまして、そちらを区内全戸配布、これは２月の中旬ぐらいから開始させていただいたところです。","id":"exchange-023"},{"speaker":"松永委員","kind":"質問","question":"しっかりと周知していただければと思います。お隣に富士山等がありますけれども、今後ぜひ、こうした災害も含めて取り組んでいただければと思いますが、その点についてもしご意見がありましたら、お伺いいたします。こちらの掲載には、ペットと一緒に避難ができる施設という掲載が表示されていなかったように感じますが、ぜひそれも今後どのようにされていくのか、併せて伺います。","respondent":"平原防災課長","answer":"ペットについてですけれども、こちらにつきましても様々な課題等ありますので、検討させていただきまして、この防災地図とは別の形になりますが、しっかりとこちらも周知させていただきたいと考えています。","id":"exchange-024"},{"speaker":"松永委員","kind":"質問","question":"とても見やすくなったハザードマップだと思います。最後に、様々な工夫をされたですが、今後、この防災地図を実際に使っていただくための取組を、区ではこの防災地図の配布により、どのような効果を期待されているのでしょうか。伺います。","respondent":"平原防災課長","answer":"あるいは先ほどお話しさせていただきましたが、風水害と地震とで避難の考え方も異なりますので、そういったところをはっきりと見やすくしたといったところが、まず１つ、工夫させていただいたところです。併せて今回、動画を作成させていただきました。","id":"exchange-025"},{"speaker":"松永委員","kind":"質問","question":"防災ハンドブックとあります。このハザードマップもあると思うのですけれども。今までは、区役所や地域センターに行けば、もしなくした場合に取りに行って、無料で配布されていたと思いますが、これについても、もしなくした場合、その場でもらえるのでしょうか。地域センターに行ったり区役所に行ったり防災センターに行ったりしたら頂けるのか、それについて伺いたいと思います。","respondent":"平原防災課長","answer":"防災ハンドブック、防災地図につきましては、区民の方々にお持ちいただきたいものと考えています。基本は全戸配布という形で一度しますけれども、その後、転入された方、あるいは紛失された方につきましては、しっかりご対応させていただきたいと考えています。","id":"exchange-026"},{"speaker":"松永委員","kind":"質問","question":"そういったところの取組もしっかりとやっていただければ、今後よろしくお願いいたします。６７ページの歴史館運営費の１億２,９１０万円のマイナス理由について伺いたいと思います。品川区の伝統文化の発信拠点である歴史館のリニューアル工事の今現在の進捗状況がもし分かれば教えてください。","respondent":"山崎文化スポーツ振興部長","answer":"今回の１億円余の減額補正につきましては、ただいま大規模改修工事中で、電気設備工事の契約の相手方から、いわゆる前払い金、予算を持っていたのですけれども、そこの請求がなく、当初の支払い計画が変更になったということで。","id":"exchange-027"},{"speaker":"松永委員","kind":"質問・要望","question":"リニューアルということで、もう大体決まっているということでありますが、やはり区民の皆様方に立ち寄っていただきたいということで、ぜひペットや駐輪場を若干増やしたり、そういったところも一時的に預けられる場所も必要かなと思うのですけれども、その点について伺いたいと思います。","respondent":"山崎文化スポーツ振興部長","answer":"活発な交流や連携を育む拠点づくりとしまして、委員がおっしゃった動線の確保や一定の駐輪場等々のことも含めまして、そういった考慮も入れながら、リニューアルを進めているところです。","id":"exchange-028"},{"speaker":"松永委員","kind":"質問・要望","question":"ぜひよろしくお願いいたします。続けて今度は８５ページの、高層マンション対策リーフレット作成等経費が、約２１０万円マイナスになっていると伺っております。区として高層マンションについて、どれくらいの高さ、いわゆる階数が当てはまるのか、また何棟ぐらいが対象になっているのか、ざっくりでいいので教えてください。","respondent":"平原防災課長","answer":"そういったところもありまして、現在把握できているところでは、区内で８６３棟を対象とさせていただいているところですが、新年度事業については、東京都の被害想定の見直しなども含めまして、対象マンションの再検討も含めて、現在、検討しています。","id":"exchange-029"},{"speaker":"松永委員","kind":"質問・要望","question":"ぜひ対策を取っていただければと思います。そこで、マンション防災対策について少し伺いたいと思うのですが、現在、町会・自治会などを対象に、様々な方法で防災対策関連の講習会が実施されるとお聞きしております。そこで、今後、講習会対象を、人口増著しい高層マンションの管理組合に拡大することなども考えているのでしょうか。ぜひ拡大していただきたいと思うのですが、いかがでしょうか。","respondent":"平原防災課長","answer":"こちらは着実に件数が積み上がっているところですが、今後とも引き続き、先ほどのお話にありましたとおり、マンション対策の進捗と併せまして、また検討してまいりたいと考えています。","id":"exchange-030","title":"町会・自治会支援"},{"speaker":"江野下委員","kind":"質問","question":"私からは、６３ページ、国際交流推進事業についてお伺いします。そこでお伺いします。展示について、区民の方やジュネーヴ市、またスイスの方から反響はありましたでしょうか。これまでの国際交流の節目でもある友好憲章締結３０周年記念事業は、２年後にはなってしまいますが、事業の継続、また新しい別の形での開催はお考えでしょうか。ご見解をお伺いいたします。","respondent":"古巻総務課長","answer":"経緯につきましては、今ご説明があったとおりでございまして、実は令和３年度が３０周年に当たったわけですけれども、１年コロナで繰延べして、結局今年もコロナ禍の影響で実施できなかったということで、やむなくパネル展示ということでございましたけれども。","id":"exchange-031"},{"speaker":"江野下委員","kind":"提案","question":"再開、あとプラスして何か、期待しております。そこで、ご提案です。品川区とジュネーヴ市とも、スポーツを通じた交流をしていくのはいかがでしょうか。世界のトップアスリートが走る大会、その選手たちを品川区シティマラソンに招待したり、国際大会でもあるジュネーヴ市の大会に、品川区シティマラソンで上位の選手を品川区民から派遣したりと、マラソンを通じた国際交流はいかがでしょうか。","respondent":"古巻総務課長","answer":"品川区のマラソンにつきましては、まだこれから様々な検討が進んでいく状況と認識しておりますので、ご提案の趣旨も踏まえまして、どんな工夫ができるのかということは考えていきたいと思います。","id":"exchange-032"},{"speaker":"江野下委員","kind":"提案","question":"先日、荏原平塚学園では、国際理解を学ぶ授業として、避難民協会のお力添えでウクライナの方に来校していただき、日本に来るまでの様子や日本文化についての話を伺いました。そこでご提案です。ジュネーヴ市、ポートランド市、オークランド市をメインに、品川区にお住まいの外国人の方々の国々の郷土料理等を一堂に会した、地域に住む外国人との交流事業を開催してはいかがでしょうか。","respondent":"古巻総務課長","answer":"ご提案のことにつきましても、いろいろ検討といいましょうか、進めさせていただきたいと思いますけれども、様々なイベントがこれからまた再開してくると思います。その中で、どんな国際交流ができるのかということをしっかり考えていきたいと思います。","id":"exchange-033"},{"speaker":"江野下委員","kind":"質問","question":"新時代の品川区にふさわしい、新しい国際交流を希望して、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"田中委員","kind":"質問","question":"４３ページ、マイナンバー、６１ページ、羽田空港周辺振興協議会、８３ページ、コミュニティバス試行運行実施経費、７７ページ、新型コロナウイルス感染症対策について伺います。マイナンバーカードについて伺います。この状況を共有するために改めて伺いますが、例えばどのような状況になると加害者側に閲覧されてしまうのかなどの説明と、関係する部署はどこなのか、お知らせください。","respondent":"吉野戸籍住民課長","answer":"１点目なのですけれども、こちらに関しましては、今もＤＶ対応はさせていただいているのですけれども、マイナポータル上に出てしまう要因としましては、加害者がマイナンバーカードを保持している場合、それから加害者が医療機関に勤務している場合には。","id":"exchange-035"},{"speaker":"田中委員","kind":"質問・要望","question":"それぞれの部署で行った対応についても伺ったので、併せて伺いたいと思います。今のところ、加害者側に閲覧されてしまった事例がなかったということは、よかったと思うのですが、ぜひこれからも、こういったリスクもあるということは伝えていっていただきたいと思います。この続きについては総務費で伺いますが、それぞれの部署で行った対応についてはお答えいただきたいと思います。","respondent":"吉野戸籍住民課長","answer":"委員のご指摘によりまして、各課でホームページで周知しているところです。それから、私どもの戸籍住民課では、窓口でも案内通知をお渡ししているというような形になっています。","id":"exchange-036"},{"speaker":"田中委員","kind":"提案","question":"ＤＶで相談が上がってくる人権の窓口ではどうなっているのかというところだけ、再度、伺いたいと思います。そもそもこの協議会はどういう団体なのでしょうか。そして、この協議会からの助成について、２０２０年３月２３日の予算特別委員会で、都市環境部長は、しながわ花海道の助成は、区から国への提案により実現したこと。求めているのであれば、その方法、どんな書式で求めているかなどを伺います。","respondent":"吉野戸籍住民課長、鈴木都市計画課長","answer":"申し訳ありませんでした。人権啓発課なのですけれども、こちらも連携させていただいて、至急、ホームページにアップさせていただきたいと思いますので、よろしくお願いします。活用先につきましては、先ほど委員からもご紹介いただきました立会川・勝島地区、平成３１年にビジョンを作成し、これから人道橋を含めた様々なまちづくりを進めていくための助成を国から受けて、こうした整備を進めていくわけですが。","id":"exchange-037"},{"speaker":"田中委員","kind":"質問・要望","question":"協議会の目的は分かりました。その要領について、私は資料提供をこれまで求めてきたのですけれども、なかなかないということだったので、要領があるということで、これを提供していただけますでしょうか。伺いたいと思います。文書で行ったのかどうかなども伺いたいと思います。文書で要望したのであれば、それをきちんと示してほしい、公開してほしいと思いますが、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"募集の要項につきましては、基本的にはこちらは任意の協議会が所有する要項ということで、委員からの事前のお問合せについては、電話でお聞きいただいた内容については、その要項に沿って丁寧に説明させていただいたです。","id":"exchange-038"},{"speaker":"田中委員","kind":"質問・要望","question":"そうしたら、近隣の方たち、地域の方たちへの防音対策というのも、ぜひするべきだと思います。機構と協議会が別団体なのかどうかということも、答弁漏れでしたので、お知らせください。要領について、任意団体だからというのはおかしいです。これまで、約３,０００万円の補助金を品川区は受けているのであれば、きちんとこの要領について公開していただきたいと思いますが、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"要領の公開については、先ほども答弁申し上げたとおり、任意の団体の協議会の中での要領ですので、必要に応じて電話等で、前回も回答させていただきましたが、そうした形でお伝えしたいです。","id":"exchange-039"},{"speaker":"田中委員","kind":"質問・要望","question":"どのような補助があるのかということなども、この要領に書かれていると思うのです。きちんと、地域の方たちが求めている騒音対策の補助もあるのではないか……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"須貝委員","kind":"質問","question":"私は、新区長になりましたので、６８ページの監査委員費について質問します。そして、次に６４ページ、人事管理費についてもお聞きしたいと思います。監査委員費についてですが、監査委員の勤務状況を、まず教えてください。１か月何回、監査委員協議会を開催し、その１回当たりの会議は何時間ぐらいあるのでしょうか。教えてください。そして、１か月の報酬は幾らになるのですか。教えてください。","respondent":"高山監査委員事務局長","answer":"それと、監査委員の報酬につきましては、識見の監査委員につきましては３０万９,０００円、それから、非常勤の、同じく議会選出の監査委員につきましては１８万２,０００円という月額の報酬が設定されております。","id":"exchange-041"},{"speaker":"須貝委員","kind":"意見","question":"今、お話が出ました。日給でいうと８万円、また状況によっては１０万円ぐらいになると私は思うのです。他の自治体などでは、給与制というのをやめて、そして、１回の会議に出席するごとに１日当たり３万円の日当制にしています。これを採用しているのですが、品川区もこういうことをいつまでもやらないで、改善するべきだと私は思うのですが、ご見解をお聞かせください。","respondent":"高山監査委員事務局長","answer":"こちらは、区長や区議会議員の給料、報酬、期末手当等の額については、特別職報酬等審査議議の審議を経まして、議会の議決を経て設定されているものですので、私ども事務局の立場から、報酬の設定に関しての見解を申し述べることは控えします。","id":"exchange-042"},{"speaker":"須貝委員","kind":"質問","question":"品川区特別職報酬等審議会で、これを決めているわけですよね。そして、このような高額な報酬というのは許されるのでしょうか。それが実態ではないですか。それを、いつまでも品川区がこういうやり方をしていいのでしょうか。１回当たり２時間、それが月に３回。それで１８万円。２０万円もらっていいのですか。こんなことをいつまでも続けては、私はいけないと思うのですが、再度ご見解をお聞かせください。","respondent":"古巻総務課長","answer":"監査委員ですけれども、監査委員の委員会に出席している時間だけではなくて、そのほかの時間につきましても、様々、職務に対して調べ物をしたり、いろいろ調査をしたりということで、時間を使っているということもありますので、現時点では。","id":"exchange-043"},{"speaker":"須貝委員","kind":"質問","question":"このほかに、私は選挙管理委員会も月２回程度だと思うのですが、これも同じような金額が出ています。だけど、もうそろそろこれは変えていくべきではないですか。今、新人や若手職員で退職する方が増えていると私は聞いていますが、品川区では実態はどうなのでしょうか。民間企業でも同じような話を私は聞いていますが、これの主な退職理由は何で、どういうふうにお聞きになっているのでしょうか。","respondent":"崎村人事課長","answer":"今、委員からお話がありましたように、近年、早期退職の人数というのは年々増えておりまして、今年度も、今年度末で、また年度途中で退職された方も含めましてですけれども、約８０名の方が早期退職という形になります。","id":"exchange-044"},{"speaker":"須貝委員","kind":"質問","question":"ここで少し、職員の採用についてお聞きします。採用に当たっては、全員、品川区で募集して、品川区で面接して、品川区で採用を決定しているのでしょうか。採用は１年に１回ですか。これについてもお聞かせください。","respondent":"崎村人事課長","answer":"職員の採用につきましては、一部、例えば保育士や看護師など、採用選考が任命権者に委任されているものについては区で実施していますが、大多数、事務職や土木技術、保健師等々については、特別区人事委員会が採用選考を実施いたしまして、その選考の結果。","id":"exchange-045"},{"speaker":"須貝委員","kind":"質問","question":"これから長くいてもらうなら、やはり品川区できちんと公募して、品川区できちんと面接して、そして品川区にマッチングする人を採用していかないと、８０人のうち７５％が若手だというのが、問題があるのではないですか。このままいったら、品川区を誰が支えるのですか。それとも、あくまで、例えば８０人採用するのは、いや、取りあえず８０人みんな入れないといけないということになってしまうのですか。","respondent":"崎村人事課長","answer":"ただ、採用選考を区独自で実施するということになりますと、人事委員会というものを独自で設置して、そこで採用選考を行うということになります。","id":"exchange-046"},{"speaker":"須貝委員","kind":"質問・要望","question":"というのは、どういうことですか。できるだけ我が社にとってマッチングする、そして、すごく品川区にとって、この人はふさわしいという人を採用していくということを考えないといけないのではないでしょうか。すぐ辞めてしまう。そのために、人事委員会というのが目の前にあって、それが弊害となっているなら、変えていかなくてはいけないのではないですか。もう、そういう時代になったのではないでしょうか。","respondent":"崎村人事課長","answer":"そういった中で、では品川区でどういうことをやっているのか、品川区が目指す区政とはどういうものかというのを、しっかりと人事課としてもＰＲしながら、採用については特別区人事委員会が行っておりますけれども。","id":"exchange-047"},{"speaker":"須貝委員","kind":"質問・要望","question":"何十年前かの法律で人事委員会制度ができたと思うのですが、やはり時代とともに変わっている。人も変わっているので、私は考えていただきたいと思います。やはり民間でいいものは何とか取り入れて、今の制度がすぐ改善できないなら、品川区は品川区独自で、何かしっかりした採用方法を考えていただきたいと私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"せらく委員","kind":"質問・要望","question":"私からは、５５ページのデジタル利活用支援員配置支援事業補助金、８５ページの防災関係組織経費について、時間があれば８３ページの都市防災まちづくり事業費について質問させていただきたいと思います。授業や家庭学習でも活用されていると思います。このＩＣＴ支援員について、現在の体制、支援員の人数、学校数と併せて教えてください。","respondent":"勝亦学務課長","answer":"ＩＣＴ支援員に関するお問合せです。現在、事業者と契約をしておりまして、２５人の体制で４６校の学校を受け持っているという状況です。","id":"exchange-049"},{"speaker":"せらく委員","kind":"質問・要望","question":"帰宅してから夕飯の準備や宿題のチェックなど大忙しですので。紙の節約にもなるのではないかと思います。配布するプリントのデジタル化は、以前もほかの委員が発言されていましたが、支援員に助言をもらいながら、まだ対応していない学校でのプリント配布のオンライン化を全校で実施していただきたいと思いますが、そういった学校において、オンライン化の進め方をどのように考えていらっしゃるか、伺います。","respondent":"勝亦学務課長","answer":"そういった中で、利便性の向上、それから保護者の方のご意見を伺いながら、こういった利便性の向上を図っていきたいと考えています。","id":"exchange-050"},{"speaker":"せらく委員","kind":"質問・要望","question":"ぜひ進めていただきたいと考えていますが、まだ対応し切れていない学校というのは、学校側がやろうとしないといいますか、やり方が分からないということもあるかと思いますので、ＩＣＴ支援員の力を借りてぜひ進めていただければと思います。こちらはどちらなのか、伺います。","respondent":"平原防災課長","answer":"マンション防災の件ですけれども、今回、補正予算で提出させていただいたものにつきましては、令和４年度に増刷を考えていたものを、事業を取りやめた内容のものです。","id":"exchange-051"},{"speaker":"せらく委員","kind":"質問","question":"２１０万円余という費用で増刷ということですが、今回はリーフレットの形ですので、一般的に１枚の用紙を折ったものかと思っています。そこには、パンフレットのリンクと、内容のご紹介としてイラストを交えて、抜粋した５つの項目の要約が書かれていました。地域の皆さんの防災への関心を高める効果もあると思いますが、区ではどのようにお考えですか。","respondent":"平原防災課長","answer":"防災士の資格が存在していることは承知していますけれども、品川区におきましては、より地域に具体的な防災の内容を考えていただくものといたしまして、平成２８年度から、しながわ防災学校という取組を進めしています。","id":"exchange-052"},{"speaker":"せらく委員","kind":"質問・要望","question":"品川区では防災学校が無料で受講できるということで、こちらはどのような方が受講しているか教えていただきたいです。防災学校の修了後は認定証などを発行して、災害発生時において、防災士を取得している方と同等の避難誘導や助言ができるものとしていますか。伺います。","respondent":"平原防災課長","answer":"３点ご質問を頂きました。対象の方ですけれども、幾つかコース分けがされておりまして、１つ目に、まず一般向けのコースということで、これはどちらかというと親子の方が中心となるようなものですが、一般的に防災の知識をつけていただくものになります。","id":"exchange-053"},{"speaker":"せらく委員","kind":"質問","question":"最後に、時間がないので１問だけ、都市防災まちづくり事業費について伺いたいと思います。８３ページの都市防災まちづくり事業費ですが、こちらの費用が全体的にマイナス補正となっております。この建て替えなどがうまく進んでいない状況かと思いますが、詳しくお伺いします。","respondent":"大石木密整備推進課長","answer":"今ご質問いただきました補正なのですけれども、一番多いのは不燃化特区支援事業におきまして、助成金が当初の予定より少なくなってしまったということがあります。こちらの理由といたしましては、申し訳ございません……。","id":"exchange-054"},{"speaker":"松澤委員","kind":"質問","question":"私からは、補正予算書７３ページ、子どもの未来応援事業、６８３万円から、しあわせ食卓事業についてお聞きいたします。５９ページには、ふるさと納税寄附金６１４万１,０００円と記載がありました。これは多分、クラウドファンディングによるものだと思いますが、９２ページ、委託料繰越で、３２９万２,０００円とあります。これはどういう意味で繰り越していくのか、ご説明をお願いします。","respondent":"飛田子育て応援課長","answer":"そのため、適量を継続的に配布することがより効果的と考え、１回の配送に必要な予算を確保した上で、余剰分を令和５年度に繰越しし、必要な時期に再度配布する予定としております。","id":"exchange-055"},{"speaker":"松澤委員","kind":"確認","question":"適量を継続的にということが分かりました。この事業は、令和元年度、食の支援から子どもたちに元気な未来を届けたい、頂いたご寄附を何倍も価値のあるものにつなげる、そういった思いで始まっています。食の配送から各支援につなげ、最終的には自立を目的とする事業であるのか、確認させてください。","respondent":"飛田子育て応援課長","answer":"そのため、配布食材一式の入った段ボールの中に、各種支援事業のお知らせやアンケートを同封しております。アンケートの回答欄には、相談を希望する欄にチェックが入っている人には、こちらから電話をして相談に乗る、アウトリーチ型のつなぐ支援事業を実施しています。","id":"exchange-056"},{"speaker":"松澤委員","kind":"質問","question":"どうしてこういう寄附をされたのですかというお話の中で、会社の社員がガバメントクラウドファンディングをやっていて、個人でやっているものを、ではこれは会社でぜひやってみようと、そういったことがきっかけだそうです。現在でも企業への周知というのは取り組んでいますが、さらに活発に、企業や全国に対して、食の支援事業を周知していくべきかと考えますが、ご所見を伺いたいのが１点。","respondent":"飛田子育て応援課長","answer":"その箱詰めにつきましては、支援企業もしくは区が委託している配送業者が行っており、またそこで個人情報の取扱いの問題等もありますので、現時点では、なかなか世帯の状況に応じた対応は難しいのかなと考えております。","id":"exchange-057"},{"speaker":"松澤委員","kind":"質問・要望","question":"そしてアンケートという部分で、支援につなげるのも大切な事業だということが分かったので、例えば食の配送に伴いまして、支援につながったケースというのですか、そういった実績があったら教えていただきたいのと、事業開始から４年が過ぎたので、福祉分野とやっていると思いますけれども、福祉分野との連携、例えばプロジェクトチームをつくったりしてみて、効果の検証。","respondent":"飛田子育て応援課長","answer":"ですので、そういうケースもあると、それ以上に効果はあるのかなと感じております。検証につきまして、現在、第２期品川区子ども・若者計画の策定をしておりまして、そこの中でも、他の分野でも連携を深めていければと考えております。","id":"exchange-058"},{"speaker":"松澤委員","kind":"質問","question":"２８件、数字が分かりました。そのことは十分分かっていますけれども、例えば寄附金の使い方、要は予算や、支援の縦割りにしないというのですか、子育て応援課でも２つ、独り親の事業などもありますけれども、例えばふるさと納税の寄附金を大きく流用させて、要は支援をまた横につなげるといいますか、そういった考え方でいくべきではないかと思いますけれども、ご見解をお聞かせください。","respondent":"飛田子育て応援課長","answer":"こちらの目的なのですが、子どもの食の支援、また独り親家庭の食の支援となっているため、この寄附の目的を尊重しつつ、他の部署でも行っている支援、またそういうところも充実を図っていければと考えております。","id":"exchange-059"},{"speaker":"せお委員","kind":"質問","question":"私からは、６９ページ、障害者福祉施設等整備費、７１ページ、障害児支援事業についてお伺いします。障害児支援事業ですが、初めに令和３年度当初予算を見てみると７億５,５００万円余で、令和３年度の補正額も見てみると２億６,７００万円余です。一方で、今お示ししたように毎年大きな額の補正額が出てきていますが、その理由をお伺いしたいです。補正が出る理由を教えてください。","respondent":"松山障害者支援課長","answer":"増加率を見込み、毎年、当初予算を計上していますが、給付費が当初予算を上回る伸びを示しております。その理由としましては、区内外に事業所が増えたことが１つあります。さらに、発達障害につきまして、年々認知度が上がっております。","id":"exchange-060"},{"speaker":"せお委員","kind":"質問・要望","question":"ですから、医療的ケア児は今ある事業所にお願いしていて、医療的ケアが必要な方のプラン作成を今までやったことがない事業所というところにとっては、少し負担が大きくなります。そこで、医療的ケアが必要な方の相談支援、主に計画相談の現状を教えてください。この現状をお聞かせいただきたいのと、あと、今後この医療的ケア児の基本相談、計画相談ともにどのように行っていくのか、計画を教えてください。","respondent":"松山障害者支援課長","answer":"７名のうち、例えばインクルーシブひろばベルにお２人、あと地域拠点相談支援センターに３人、それからピッコロと区に１人ずつということで、７名おります。現状としましては、今後、３月１０日に医療的ケア児コーディネーター連絡会を開催する予定でおります。","id":"exchange-061"},{"speaker":"せお委員","kind":"質問","question":"６９ページ、障害者福祉施設等整備費の障害者グループホーム整備等助成は、２,５００万円減額となっています。こちらは、区内でグループホーム整備を行う民間事業者への助成金だと理解していますが、減額になっている理由は、グループホーム整備を行う事業者が想定より少なかったという理解でよろしいのかということと、あとその理由が何か考えられますでしょうか。教えてください。","respondent":"川崎障害者施策推進課長","answer":"こうした社会情勢もあるので、なかなかすぐに整備費補助には結びつかないという、難しい局面があるというのは事実です。","id":"exchange-062"},{"speaker":"せお委員","kind":"質問・要望","question":"本当に難しいと思っていて、事業者誘致は予算だけの問題ではないとも思っています。できることから一歩ずつ、品川区のことなどを知っていただくというのも重要かなと思っています。他区よりも多い補助金、結構多額の補助金を設定していて、強い意気込みを感じていますので、ぜひ周知強化をお願いしたいところですが、時間もなくなったので、そこのところは要望で終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-063"},{"speaker":"あくつ委員","kind":"確認","question":"私からは、６３ページ、国際交流推進事業、６７ページ、運動施設費、７７ページ、健康センター事業費の３件の予算案に関連いたしまして、ウクライナ避難民への支援について、確認と質問をします。以前、区内の避難者の状況を一般質問で確認いたしましたところ、プライバシー保護、避難者の安全確保などの観点から、避難者数は公表しないとの方針でした。","respondent":"古巻総務課長","answer":"昨年ご答弁させていただいた７名に加えて２名です。２件、支出しております。","id":"exchange-064"},{"speaker":"あくつ委員","kind":"質問・要望","question":"いらっしゃる、いらっしゃらないにかかわらず、少なくとも９名の方が、今、受入れをされていらっしゃるということを確認させていただきました。そのご相談を基に、昨年１０月の第３回定例会の一般質問と決算特別委員会で、区としての支援メニューの拡充というものを強く強く求めたところです。この答弁を基に、しつこく決算特別委員会でも各所管にも確認しました。それから４か月が経過しております。","respondent":"古巻総務課長","answer":"国の動きとしましては、最近、在留資格を更新して１年延長できるような通知をしているというところもありますし、また加えて生活支援につきましても、当初半年が、さらに半年延びて、プラスでさらに１年延長するというようなアナウンスが出たところです。","id":"exchange-065"},{"speaker":"あくつ委員","kind":"質問","question":"何で１０万円を支給したのかというところを考えたときに、やはり緊急性があるから、そういうことをやられたのだと思うのですけれども、そこでいつから、何月何日から開始されるのですかとも聞こうと思ったのですが、なるべく早くということだったのですが、では、今日は補正予算の審議ということですが、健康センター等の事務等の使用料というのは、減免措置を考えられたときに、一瞬、款が飛びますけれども。","respondent":"古巻総務課長","answer":"減免ですけれども、予算措置という意味では、厳密に言うと何らか予算が要る場合もあるかと思いますけれども、基本的には、歳入が若干減るかなということはありますけれども、先ほども少しお話が出ましたとおり。","id":"exchange-066"},{"speaker":"あくつ委員","kind":"質問・要望","question":"免許証ぐらいの大きさで、写真つきの大きさなのですけれども、これは、地方公共団体で支援を受けたり、行政手続を行ったりする場面で見せることや、金融機関の口座をつくるときに在留カード等の本人確認書類と一緒に担当の人に見せるということを想定しているそうです。国が想定しているような、本証明書を活用するような、品川区独自の支援制度が既にあるのか、教えてください。","respondent":"古巻総務課長","answer":"具体的な支援というよりは、サポート的な意味で、ウクライナ避難民であることが、それで客観的に確認できますので、そういった意味では、手続の際の迅速化や、サポートのより寄り添った対応ということを実現できているのかなと思っていますし、今後。","id":"exchange-067"},{"speaker":"あくつ委員","kind":"提案","question":"それもご提案しようと思ったのですが、ご利用されるということだったので、ぜひ活用していただきたいということです。我が国の避難民の受入れがスタートして約１年がたって、各自治体では、継続的に支援をしていく中で、やはりニーズが変わってきているということを、いろいろな表明がされてきています。","respondent":"古巻総務課長","answer":"基本的には日本語の対応というようなところも、なかなかやはり言葉が、日本語がよく分からないという方が多いのかなと思いますので、日本語へのニーズに関しましては、国際友好協会の日本語教室は、当初から無償で受入れをしていますし、また各種の手続につきましても。","id":"exchange-068"},{"speaker":"あくつ委員","kind":"質問・要望","question":"最後に伺いますが、ウクライナ避難民に対しまして品川区民として胸を張れるような、しかるべき立場の品川区の理事者が先頭に立ってウクライナへの連帯を示して積極的な支援を行っていただく姿勢を強く強く求めたいと思いますが、別に区長や部長に答弁を求めているわけではないです、そうではなくて、しっかりとそういう姿勢を強く示していただきたいと思いますが、最後にお考えを伺って終わりたいと思います。","respondent":"古巻総務課長","answer":"ウクライナ避難民に対してしっかり支援をしていっているのだ、支援をさせていただいているということにつきましては、今後も、まさに今、長期化してきている中で、区民に対してしっかりアピールをするということは必要かと思いますので。","id":"exchange-069"},{"speaker":"おくの委員","kind":"質問","question":"４３ページの社会保障・税番号制度システム整備費補助金に関わって、マイナンバーカードの取得についてお伺いします。岡山県備前市は、保育料や給食費などを無償とする対象を、新年度から、家族全員がマイナンバーカードを取得した世帯に限定するという報道がされております。市議会でも討論したようです。品川区では、マイナンバーカードの取得は任意でしょうか。伺います。","respondent":"吉野戸籍住民課長","answer":"品川区も任意になります。","id":"exchange-070"},{"speaker":"おくの委員","kind":"質問・要望","question":"紙の健康保険証が廃止されると聞いたと。病院の診療を受ける、受けられない。ですから、マイナンバーカードがないと病院の診療が受けられない。そこで改めて伺いますが、品川区では、これからも紙の保険証で、従来どおり病院の診療を受けられると。受けられないというようなことはないと考えておられるのでしょうか。これは、もちろんそういうことを考えてはいけないと思うのですけれども、いかがでしょうか。","respondent":"宮澤情報推進課長","answer":"委員ご指摘のとおり、国から、令和６年秋をめどに紙の健康保険証を廃止するという方針を発表されているのは、認識しています。しかしながら、マイナンバーカードにつきましては、区民の申請に基づいて交付されるものというところでございまして、この点は変更がございません。","id":"exchange-071"},{"speaker":"おくの委員","kind":"質問","question":"そうしますと、国からこれから指示されるということですけれども、私がお伺いしているのは、品川区では、国の指示がどうであれ、今までどおり紙の保険証が使えるのかということをお伺いしたのですけれども、その点はいかがでしょうか。","respondent":"宮澤情報推進課長","answer":"今の段階では、資格確認証の発行等というところが考えられますけれども、詳細につきましては、今後、国から示されるものに沿って対応していくです。","id":"exchange-072"},{"speaker":"おくの委員","kind":"質問・要望","question":"新聞なども、事実上の義務化だと書いています。そういうふうにしていただきたいのですけれども、「国の言うとおりにしていきます」ということでは、品川区では任意だということが守られないということになると思うのですけれども、ぜひとも、どういう展開であろうが、品川区では任意だということを守っていただきたいのですけれども、いかがお考えでしょうか。","respondent":"宮澤情報推進課長","answer":"繰り返しの答弁にもなりますが、現在も国の発表では、マイナンバーカードの申請は、申請に基づいて交付されるものということで、この点は変更なく、これまでどおり保険診療は受けられると発表されているところです。","id":"exchange-073"},{"speaker":"おくの委員","kind":"質問・要望","question":"ぜひとも、今報じられているような、事実上の義務化だというようなことにはならない、マイナンバーカードが手元になくても、従来どおり行政サービスが受けられるし、それから医療サービスももちろん受けられるという体制を続けていっていただきたいと思います。強く要望しておきます。その点、いかがお考えでしょうかということと、その対策はどういうふうにお取りでしょうか。ご説明いただきたいと思います。","respondent":"宮澤情報推進課長","answer":"区の内部としましても、マイナンバーのネットワーク層を分離したり、アクセス権のある職員につきまして２要素認証、職員証と手のひらの生体認証で、なりすまし防止等の対策を立てているところです。","id":"exchange-074"},{"speaker":"おくの委員","kind":"質問・要望","question":"情報漏えいの危険性は十分には払拭されていないと思います。マイナンバー制度の中止を求めて質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-075"},{"speaker":"小芝委員","kind":"質問","question":"私からは、７７ページの予防接種費に関連しまして、新型コロナウイルスのワクチン接種と接種をめぐる人権、また副反応についてお伺いいたします。２０２０年２月から新型コロナウイルスの脅威が世界に蔓延して、３年が経過しました。お聞きしますが、品川区のワクチン接種状況、初回と３回目の接種率、６５歳以上の方々と２０代の方々の接種率について教えてもらえますでしょうか。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"初回接種からお答えいたします。６５歳以上の初回接種が終わった方は９８％です。２０代の方は、初回接種が終わった方は７２.８％です。３回目、６５歳以上の方の接種率は９２.３％、２０代の方は５３.３％という形になっております。この数字は、２月２８日現在のものです。","id":"exchange-076"},{"speaker":"小芝委員","kind":"質問","question":"今、２０代の方は３回目の接種率が５３.３％というお話を伺いました。インターネットを中心に、ワクチンについて様々な情報を取得する２０代の方々のワクチン接種に対する考えというのが、この３回目の接種率に如実に表れているかなと考えます。この点、区はどのように分析をされているのか。さらに今後、この接種率の向上に向けて取り組むのかどうか、お答え願います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"３回目接種が終わった方につきましては、旅行支援や、あと入国の際の検疫の状態でＰＣＲ検査等々が免除されることもありますので、その辺りもホームページでうたいながら接種を進めている状況です。","id":"exchange-077"},{"speaker":"小芝委員","kind":"質問","question":"それで、接種することのベネフィットと副反応のリスクを知ることで、おのおのが接種を判断すべきと、厚生労働省も述べておるわけですが、品川区のホームページでも、１、２回目接種のトップページには、接種は任意ですと、明確に記載されています。当初からこの文言がホームページにアップされていたのかどうか分かりかねますが、この１文はとても大きいと考えます。その辺りを教えていただければと思います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"接種券を郵送する際の同封物の中にも、ワクチンについての説明については、当初ですが、ファイザー社のもの、モデルナ社のもの、中に説明書を同封してご説明に代えさせていただきました。","id":"exchange-078"},{"speaker":"小芝委員","kind":"質問","question":"接種しないことで、それが実は人権の侵害にもつながる。東京都でもホームページなどで、接種の強制や、接種しないことで不利益な扱いを受けることがないよう呼びかけてはおりますが、現状、品川区に、こういった人権侵害にもつながるようなケースの報告というのはなされておるのかどうか教えてください。報告を受けた場合の対応について教えていただければと思います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"委員がご指摘のようなハラスメント的なものにつきましては、我々の耳には入ってきておりません。","id":"exchange-079"},{"speaker":"小芝委員","kind":"質問","question":"今、課長の答弁のとおり、品川区ではそういった報告は受けていないということで、聞いて安心いたしました。続きまして、ワクチン接種の副反応について伺います。令和３年２月から始まりましたコロナワクチンの接種。地域の方からは、ネットによる予約がなかなか分からず、相談されたこともありました。副反応のアンケートをいつ頃からアップし始めたのか、いきさつについて教えていただければと思います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"港区とは、おととし、港区のスポーツセンターなど、合同接種という形で、協力して接種を南部で進めていこうという関係柄にもなりまして、その一環で、港区が始められたアンケートに品川区も乗って、より情報を集めていこうという流れの中での。","id":"exchange-080"},{"speaker":"小芝委員","kind":"質問・要望","question":"品川区も区民の命を預かるわけですので、今後も、こういったアンケート等を取り上げていただきまして、検証・対策をしていただきたいと考えます。ただし、接種との因果関係が、情報不足によりまして判別できないのが、そのうちの１,７４０件と報告されているわけです。この報告を受けた方の症状について、分かる範囲で教えていただければと思います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"ほとんどが男性と聞いております。次に多いのが、ＳＩＲＶＡ症候群と申しまして、肩の関節障害と言われるものです。こちらが５件と報告が上がっておりまして、こちらは全て女性と聞いております。","id":"exchange-081"},{"speaker":"小芝委員","kind":"質問・要望","question":"副反応の説明を頂きましたけれども、今後も時間が経過した後に、例えば５年後や、あと１０年後にこの副反応が発生することもあり得るかもしれません。品川区も、万が一に備えまして、この接種記録を保存する期間を延長することを検討するべきではないかと考えますが、区の考えを教えていただきたいと思います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"もう一つ、コロナワクチンには予診票というものがございまして、こちらは紙ベースのものです。こちらも、紙ベースのものを全て電子化して保存する作業に現在当たっております。こうしたことによって、保存期限を区切ることなく接種記録を保存することが可能と考えております。","id":"exchange-082"},{"speaker":"小芝委員","kind":"意見","question":"保存期間を延長するという仕組みを改良することによって、保存できるという話を受けました。万が一に起こり得る健康被害から区民を守ることに寄与するものと考えますので、今後もお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-083"},{"speaker":"横山委員","kind":"質問","question":"私からは、６４ページの人事管理費、７９ページ、商店街活性化事業費についてお伺いいたします。１点目に、人事管理費についてお伺いいたします。は人事管理費についての補正の内容をご説明ください。","respondent":"崎村人事課長","answer":"人事管理費全体というところでのお尋ねですが、人事管理費については、文字どおりになるのですけれども、区の人事関係に関する予算を計上させていただいておりまして、例えば職員の採用や退職、また勤怠管理や、給与・手当の支給、また健康管理、福利厚生。","id":"exchange-084"},{"speaker":"横山委員","kind":"確認","question":"確認させていただきました。ありがとうございました。適切にお休みが取れず、絶えず疲労を抱えながらの勤務では、チャレンジを続けることもできません。これから働きやすい職場環境を、今までも努力していただいておりますけれども、どのように実現していくのかというのを、改めてお伺いできればと思います。特に休暇の概念について、再度ご説明をお願いいたします。","respondent":"崎村人事課長","answer":"委員のお話のとおり、働きやすい職場環境、また職員がいい仕事をしていく上で、心身ともにリフレッシュを図り、仕事と生活の調和が取れた状態というのを維持することが重要であると考えておりますので、そういった意味でも、年次有給休暇というのは、特に理由がなくとも。","id":"exchange-085"},{"speaker":"横山委員","kind":"確認","question":"そこでお伺いいたしますが、何か予定等がないとお休みを取ることなどできないと考えていらっしゃる職員がどのくらい減っているのかというところを、ご実感で構いませんので教えていただけたらと思います。１０日以上の年休取得率など、休暇取得の現状について教えてください。休暇取得をしやすくするためにどのような働きかけを行っているのでしょうか。","respondent":"崎村人事課長","answer":"なかなかこちらで、例えば何か予定がないと休みが取れないと考えている職員が減ったというのを、定量的にお示しすることは難しいのですけれども、１０日以上の年休取得率というところで言いますと、昨年度が、１０日以上取得した率が７０.１％になっておりまして。","id":"exchange-086"},{"speaker":"横山委員","kind":"質問・要望","question":"様々確認させていただきました。来年度等、これからに向けて、ぜひ人事委員会の勧告等もあるかと思いますし、様々努力を続けていただきたいと思いますので、改めまして、リフレッシュ休暇やチャレンジ休暇を取っていただきたいと要望いたしまして、また年休の取得の促進をよろしくお願いいたします。２点目に、商店街活性化事業費についてお伺いいたします。","respondent":"遠藤商業・ものづくり課長","answer":"そういう部分も含めまして、区ではいわゆるエリアサポーター事業というものを令和２年度から実施させていただいているところです。","id":"exchange-087"},{"speaker":"横山委員","kind":"質問・要望","question":"まちづくりの支援については、都市開発課が中心となって、商業・ものづくり課や地域活動課などと連携して進めていただきたいと思いますが、今後、小山のまち全体を捉えながら、商店街の活性化と商店街を含めたまち全体の活性化を要望いたしますが、それぞれ区のお考えをお聞かせください。","respondent":"多並都市開発課長","answer":"この中で、やはり商店街の活性化と連携の方法というのは非常に重要な部分であり、これにつきましては、現在も開発連絡会、また、賑わい軸の検討会など、区で場を設定しながら、皆さんでお話合いをしていただいているところですので、区としても、今後その活性化につながるよう。","id":"exchange-088"},{"speaker":"こんの委員","kind":"質問","question":"私からは、５点まとめて、まず一括で、減額補正されている項目をお聞きしたいと思います。１つが、４９ページの高齢者見守り相談窓口設置事業、７,３０３万円。７１ページ、高齢者福祉施設支援事業、養護老人ホーム、３,０００万円。それから７５ページ、生活困窮者自立支援事業、住居確保給付金が８,９００万円。この理由をまず、お伺いしたいと思います。","respondent":"寺嶋福祉計画課長、櫻木生活福祉課長、菅野高齢者福祉課長、栗原河川下水道課長、勝亦学務課長","answer":"初めに４９ページの２３節、高齢者見守り相談窓口設置事業補助金の減額につきましては、まず、これは内容が、支え愛・ほっとステーションの人件費。こちらは、住居確保給付金、令和４年度の見込額として４８０世帯を見込んでいたところですが、決算見込みとしては２６４世帯という形になりまして。当初の見込みが８５人というところだったのですが、実際は７０人程度の措置者数にとどまるため、今回２００万円掛ける１５人ということで。","id":"exchange-089"},{"speaker":"こんの委員","kind":"質問・要望","question":"それで、１つずつお伺いしたいと思いますけれども、まず見守り相談窓口の支え愛・ほっとステーションは、今、減額の理由をお聞きしましたけれども、支え愛・ほっとステーションの業務の現状を確認させていただきたいと思います。これはもっと体制を拡充していくことが必要ではないかと考えるわけですけれども、その点、いかがでしょうか。そこを確認させてください。その２つをお願いします。","respondent":"寺嶋福祉計画課長、菅野高齢者福祉課長","answer":"人数ということですが、もちろん多いにこしたことはないとは思うのですけれども、短期間の内に１３地区展開をする中で、やはり委託先の社会福祉協議会も人材確保に大変苦労したところでありまして、今、各地区２名ずつ。私からは、養護老人ホームの入居に至るまでの経緯等についてご説明します。","id":"exchange-090"},{"speaker":"こんの委員","kind":"質問・要望","question":"支え愛・ほっとステーションは、確かに現状で対応してくださっている方向性としては、その状況に応じて考えを持ってくださっているということが確認できましたので、どうかこれからも引き続き、一人暮らしの高齢者の方に、いわゆる来るのを待つということではなく、どういった状況であるかという前のめりの姿勢で、どうか対応を引き続きしていただきたい。","respondent":"櫻木生活福祉課長","answer":"年齢別ということでございまして、こちらは通算のデータにはなるのですが、令和２年から令和５年１月までの通算で、２０代につきましては２４６世帯、２２％、３０代が２９６世帯で２６％、４０代が２５３世帯で２２％、５０代が２００世帯で１７％。","id":"exchange-091"},{"speaker":"こんの委員","kind":"質問","question":"年齢別の状況をお伺いしたところ、今、課長もおっしゃってくださったように、若い世代の２０代から４０代の方の利用が多いという結果。こちらは本当に、若い世代の方が今、困窮している、若者の生活が困窮しているという社会の問題があります。それが本当に如実にこの数字に出ているのだというのを見て取ることができます。","respondent":"櫻木生活福祉課長","answer":"今後のまた若者向けの困窮についてですが、暮らし・しごと応援センターでも様々、日々ご相談を受けていますので、そのような相談状況を見ながら考えていきたいと考えています。","id":"exchange-092"},{"speaker":"こんの委員","kind":"質問・要望","question":"若者の貧困という問題は、これから、ますますという言い方はあまりしたくないですが、でも本当に増えている現状もありますので、区としては、若い人への対策をどうか考えていっていただきたい。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-093"},{"speaker":"西村委員","kind":"質問","question":"５７ページ、児童福祉指定寄附金、５９ページ、ふるさと納税寄附金より、子どもの未来応援事業から子ども食堂について伺ってまいります。子ども食堂については、現在、区内の数が３５か所にわたっていると伺っております。コロナ禍が３年もの間続き、現在どのような課題があるのか、アフターコロナはどのように子ども食堂の運営が変わっていくとお考えか、区の見解をお聞かせください。","respondent":"飛田子育て応援課長","answer":"ですので、そういうところでもまたどのようにやっていくか、また情報交換等して模索していきたいと考えております。","id":"exchange-094"},{"speaker":"西村委員","kind":"質問","question":"今、子ども食堂の中でフードパントリーを実施している食堂は幾つあるでしょうか。食事を提供している子ども食堂の数と、週１回、月１回など、１か月の実施回数を伺います。区は新規立ち上げ時に上限５０万円を補助していますが、今年度利用した事業者がいるのかを併せて伺います。","respondent":"飛田子育て応援課長","answer":"現在、品川区には３５か所ということで、子ども食堂を実際やっておりますが、休止中のところ５か所を除いた３０か所において、子ども食堂あるいはフードパントリーもしくは両方を実施しているというふうになっております。","id":"exchange-095"},{"speaker":"西村委員","kind":"意見","question":"なかなかコロナ禍で食事を提供するということのハードルが高かったと思うのですけれども、先ほどおっしゃられた、居場所としてどれほど機能していたのかというのは、子ども食堂側も不安だったのではないかと思っています。しかしながら、食の支援や母親支援として、フードパントリーがその間をつないで埋めてくださっていたのではないかと思っています。商品券を配布するに至った経緯をお聞かせください。","respondent":"飛田子育て応援課長","answer":"今回、商品券につきましては、子ども食堂に対する支援として、令和３年度より子ども食堂推進事業補助金というものを、開催実績に基づいて交付しておりました。","id":"exchange-096"},{"speaker":"西村委員","kind":"質問・要望","question":"地域のコミュニティづくりにも貢献できる取組ですので、ぜひとも様々なシーンで、この商品券の活用をご検討いただきたいと思っています。子ども食堂ネットワークでもご努力いただいているのですが、どうしても食品ですと、フードパントリーは現状、レトルトカレーやアルファ化米などが多く、偏りが見られるという声が届いております。改めて、品川区の子ども食堂の目的を伺います。それとも両方か。","respondent":"飛田子育て応援課長","answer":"ですので、そういう考え方は受け止めながら、まずは子ども食堂ネットワーク、また協議会の情報交換とかそういうところも通じまして、また新たに子ども食堂をやりたいとか、また続けたいとか、増えるような支援体制を、また今後も検討していければいいかなと考えております。","id":"exchange-097"},{"speaker":"西村委員","kind":"提案","question":"子ども食堂は、冒頭申し上げましたとおり、もともとは基本は孤食を防ぐことにあると私は思っております。そこで、再度ご提案をします。子ども食堂が全ての子どもたちの居場所なのであれば、地域、学校、子ども食堂の連携を強化する支援をしていただきたいと思います。区は子どもたちに広く周知していきたいと考えているのか、子どもが知る機会はほかにあるのか、伺います。","respondent":"飛田子育て応援課長","answer":"そういうところも踏まえまして、いろいろなところで情報提供をしながら、また周知をしていければと考えております。","id":"exchange-098"},{"speaker":"西村委員","kind":"意見","question":"子ども食堂に可能性を感じておりまして、複数の目的を兼ね備えた解決手段の一つになり得ると思っています。区は、子ども食堂ネットワークを早々に立ち上げ、安全安心な居場所づくりのために伴走型の支援を行ってきてくださいましたが、今後、様々な形態の子ども食堂が増えている今、区が子ども食堂をどういう場にしていきたいのかを改めて示すことが重要だと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-099"},{"speaker":"のだて委員","kind":"質問・要望","question":"私からは、補正全体に関わって物価高騰対策、また、８３ページの不燃化特区支援事業、８５ページの住宅・建築物耐震化支援事業について伺います。物価高騰がずっと続いています。同時に電気代やガス代などが大きく上がっています。既に世界では１００を超える国と地域が、いわゆる消費税の減税に踏み出していますけれども、消費税を５％に引き下げた場合、どんな効果があると区は考えているのか、伺います。","respondent":"黒田財政課長","answer":"物価高騰対策支援ですが、令和４年度の第４号補正予算におきまして、物価高騰対策というところで、様々、国の交付金等も活用しながら施策を実施したところです。消費税５％の影響はですが、国税に関わることですので、区でそういったところの見解は持っていないところです。","id":"exchange-100"},{"speaker":"のだて委員","kind":"質問・要望","question":"国税に関することだということなのですけれども、これは別に、今まで国に意見を求めるべきだということで言ってきました中で、同様のご答弁でしたけれども、実際、引き下がった場合の区への効果や影響というものを聞いているので、区としても、ぜひそうした見解があるのではないかと思いますが、いかがでしょうか。","respondent":"黒田財政課長","answer":"いわゆる消費税の中には、国税である部分と地方税である部分がありまして、地方税である部分は、地方消費税交付金として都道府県と市町村に配分されるということですから、当然、税率が変われば、そういったところに影響があるということは考えられると考えています。","id":"exchange-101"},{"speaker":"のだて委員","kind":"質問","question":"区の税収についての見解がありましたけれども、区民への影響という点での見解はありませんでした。消費税の５％への引下げが区民の暮らしを支えることになると考えないのか、伺います。","respondent":"黒田財政課長","answer":"消費税は、そもそも国税で課税されている中で、いわゆる社会保障の財源とされているというところで、そういった趣旨で都道府県や区市町村にも交付されているというような状況ですので、そういう意味では、そこの財源が減ってくれば。","id":"exchange-102"},{"speaker":"のだて委員","kind":"質問・要望","question":"区の事業のことしか言わないですけれども、私はやはり区民の暮らしをしっかり見ていただいて、消費税減税が全ての事業者・区民の暮らしを支えることになるということを見ていただいて、区が区民の暮らしを助ける立場にあるならば、国に引下げを求めることを強く要望しておきたいと思います。本会議で、生活保護需給者と、年収２００万円以下の生活困窮者に、光熱費補助を行うことを求めました。伺います。","respondent":"櫻木生活福祉課長、飛田子育て応援課長","answer":"国でも今、経済対策という形で、また様々議論されているような状況かと認識しておりますので、そこを中心としてまいりたいと思います。住民税均等割のみの世帯を対象にした給付金についても同様です。現在、ひとり親家庭につきましては、国の状況など、今、様々な思案もされておりますので、そちらを見ながら考えていきたいと思います。","id":"exchange-103"},{"speaker":"のだて委員","kind":"質問・要望","question":"どちらも国の状況を見てということなのですけれども、国の状況が出る前に、今既に区民の生活は大変な状況ですので、ぜひ区として独自に行っていただきたいと思います。本会議の答弁では、現時点ではということでおっしゃっておりましたけれども、そうなると、どのような状況になれば実施するという考えなのか、伺います。","respondent":"櫻木生活福祉課長","answer":"どのような状況かですが、基本的に国等の検討状況を踏まえて、実施するべきものは実施していくです。","id":"exchange-104"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ低所得世帯やひとり親世帯への区独自の給付金を行っていただきたいと、強く求めておきたいと思います。中小企業への直接支援も必要です。コロナに加え、原油価格や物価高騰の影響が本当に多くの業種に広がっています。国の検討内容に、中小企業への直接支援はあるのか。区内企業の８割を占める中小企業へ、区として独自に直接支援をすることが必要だと思いますが、いかがでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"区としても、これまで運送事業者等燃料費高騰対策支援金など、そのほか融資制度などを設けて、中小企業の支援に当たってきたところですので、今後も国の動向等を注視しながら、引き続き支援を進めたいと思っておるところです。","id":"exchange-105"},{"speaker":"のだて委員","kind":"質問・要望","question":"区独自としてぜひやっていただきたいということで求めておりますので、ぜひ区民や営業を支援するという立場で実施していただきたいと思います。最後に、耐震化・不燃化についてです。今回、減額がかなり行われています。様々事情はあると思いますが、こうした予算を、ぜひ住宅耐震化促進に向けて実施していっていただきたいと思います。今回の課題は何か、伺います。","respondent":"長尾建築課長","answer":"建物の所有者で合意形成した後、資金面であったり、合意形成をつくったのだけれども計画の変更があったりと、なかなか思うように進んでいないところもありますので、そういったところについては、話をよくお伺いしながら、都と連携して促進してまいりたいと考えております。","id":"exchange-106"},{"speaker":"木村委員","kind":"質問","question":"私からは、４５ページにあります防災普及教育費についてお伺いいたします。５００万円とあり、この事業に対して補助金が出されているということですけれども、どのようなところにこの費用は使われているのでしょうか。お聞かせください。","respondent":"平原防災課長","answer":"防災普及教育費ですけれども、区が作成いたしますハザードマップの作成経費につきまして補助を頂くもので、今年度、防災地図を作ったうち、ハザードマップに係る部分を国費補助いただいたものです。","id":"exchange-107"},{"speaker":"木村委員","kind":"質問","question":"ということは、これも災害時に使われるということですよね。区では今回のハザードマップを更新したとのことですけれども、区民に対してどのように周知していくのでしょうか。それもお聞かせください。そして、ハザードマップの意味も、６５歳以上の方、高齢者の皆さんは、どれぐらいこれを理解しているのでしょうか。それが分かればお聞かせください。","respondent":"平原防災課長","answer":"高齢者等への今後の進め方ですが、現在はまず配布させていただいている段階ですので、今後様々な機会、例えばですけれども、今週末３月１１日に開催の防災フェアといったところでも、防災地図のブースを設けさせていただきまして。","id":"exchange-108"},{"speaker":"木村委員","kind":"意見","question":"品川区の防災地図に全てのハザードマップを掲載したとのことですけれども、防災地図は、手に取り、内容を見て、備えておいていただく必要があると思います。区では防災地図を作成するに当たって、どのような工夫を行ったのか。あれば、何かお聞かせください。そして、もしできれば、高齢者の皆さんに本当に分かるように、そういうものが工夫できたのであれば、それもお聞かせください。","respondent":"平原防災課長","answer":"あるいは、ご自身の住所地といったところから、どこが避難所なのか、避難場所なのか。あるいは、災害から避難するときの考え方、情報学習面といいますけれども、そういったものを充実させていただいたところです。","id":"exchange-109"},{"speaker":"木村委員","kind":"質問","question":"人の命は大事でありますから、よろしくお願いいたします。そして、８３ページの下段にあります戸越公園駅周辺地区再開発事業からの質問を致しますけれども、令和４年度補正予算の都市開発費、戸越五丁目１９番地区です。再開発事業補助金が、約８億７,８００万円の減額がされています。減額の理由と現在の状況についてお聞かせください。","respondent":"中道まちづくり立体化担当課長","answer":"現在の状況ですが、建物の躯体工事を進めております。令和４年度は５階の床まで完成する予定です。今後のスケジュールといたしまして、事業認可当初、予定していた、令和６年５月の建物完成に向けて工事を進めております。","id":"exchange-110"},{"speaker":"木村委員","kind":"質問・要望","question":"コロナ禍の影響もありますが、当初のスケジュールで、建物が完成予定であるということが分かりました。２月９日、１１日に、東急大井町線の連続立体交差計画および関連する道路計画と戸越公園駅交通広場計画の都市計画素案の説明会が開催されました。これらの事業について、どのような事業なのか、お聞かせいただきたいと思います。完成までにどの程度の期間が必要としているのかもお聞かせください。","respondent":"中道まちづくり立体化担当課長","answer":"委員よりご質問いただきました説明会の内容および計画スケジュールについてお答えします。","id":"exchange-111"},{"speaker":"木村委員","kind":"質問・要望","question":"安全に、区民のためにもよい工事をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-112"},{"speaker":"芹澤委員","kind":"質問・要望","question":"それから何か支援があれば、なおさらいいよねというぐらいだったと思うのですが、やはりコロナ３年の抑圧された生活の中で、ストレスをどうしても発散していきたいとか、先人たち、先輩たちがやってきた経験を自分たちが継承できていないというような、自己肯定感というものもあって、それを高められるようなイベントをしてほしいというようなお声も、これから出てきているのではないかと思うのですが。","respondent":"川島地域活動課長","answer":"そのほか、お子さんが集まるイベントの重要性ということも再認識されましたので、こういった観点から、地域の活性化、にぎわい創出の部分を進めていければと思ってあります。","id":"exchange-113"},{"speaker":"芹澤委員","kind":"提案","question":"当時、この手形に関しては、カラフルな絵の具、ペイントをつけたのですが、例えばコロナのやはり象徴といえば青でしたから、全部、青に統一して、改めて最後に医療従事者に感謝を申し上げるというようなところで、区民全員でギネスブックにチャレンジするというのは、１つご提案なのですが、いかがでしょうか。","respondent":"山崎文化スポーツ振興部長","answer":"委員にご引用いただきましたイベントにつきましては、東京２０２０オリンピック・パラリンピック大会の、しながわ文化プログラムの一環として、スクエア荏原で２０１８年に実施したところです。","id":"exchange-114"},{"speaker":"芹澤委員","kind":"提案","question":"当時は残念ながら２,０００名ぐらいのご参加だったかと思います。委員会の議事録を見ても、周知不足があったのではないかというような１つ指摘があって、これはまた私からの提案でありますが、これから森澤区長の政策の中で、区民アンケートというものがあります。","respondent":"山崎文化スポーツ振興部長","answer":"先ほど、アンケートなり、イベントの多様な参画を担う手法につきましては、様々、区全体の中で検討させていただき、実施してまいりたいと考えるところです。","id":"exchange-115"},{"speaker":"芹澤委員","kind":"質問","question":"せっかく全区民に送るものですから、別にこのイベントをしてくれというものではないですけれども、ぜひ活用いただいて、様々イベントなどにお誘いいただくというのと、あと、やはり濱野区政のときに挑戦してなし得なかったものでありますので、まさに継承と発展ということで、新たなイベントとしてぜひ挑戦いただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-116"},{"speaker":"たけうち委員","kind":"質問・要望","question":"８５ページの、先ほども一部出ました住宅・建築物耐震化支援事業、それから、がけ・擁壁安全化支援事業で、先ほどもありましたけれども、両方とも非常に大幅減額になっております。木造住宅の耐震化は非常に喫緊な課題ですけれども、その辺りの実績がどうだったのか。もう少し詳しく教えていただきたいと思います。","respondent":"長尾建築課長","answer":"耐震化支援事業につきましては、木造の住宅の除却につきましては、２月末時点ですけれども、およそ１００件ほどが申請されているというような状況となっております。","id":"exchange-117"},{"speaker":"たけうち委員","kind":"意見","question":"木造住宅の耐震化の助成の実績も、後でお願いします。それでも、かなり大幅な減額ということで、引き続き、しっかりとお願いしたいと思います。それで、住宅耐震化については、戸別訪問もやられていたかと思うのですけれども、その辺の状況と、また新年度についても戸別訪問が予定されておりますけれども、その違いや、また、どのような感じでやっていくのか、その辺をお知らせください。","respondent":"長尾建築課長","answer":"来年度につきましては、同様の内容で、場所を変えまして、旗の台五丁目、また中延四丁目・六丁目の３町丁目を回る予定としております。","id":"exchange-118"},{"speaker":"たけうち委員","kind":"質問","question":"分かりました。訪問のときに、いわゆる旧耐震など、古い木造住宅を粗々ピックアップして回るのか。それとも、その地域の中で木造の住宅だったら、そこを、あまり築年数関係なく回るのか。どんな感じでやっていらっしゃるのですか。","respondent":"長尾建築課長","answer":"戸別訪問の訪問対象の住宅につきましては、あらかじめ東京都で持っている、建物の現況調査のデータなどを活用しまして、昭和５６年５月以前に建てられた旧耐震基準の木造の住宅を対象として訪問したところです。","id":"exchange-119","title":"町会・自治会支援"},{"speaker":"たけうち委員","kind":"質問・要望","question":"実際に危険な品川区でも、２０００年以前の新耐震基準の建物だと、２,０００棟ぐらいが大変厳しい中で、それをやっていくと８割ぐらいが改善されて、非常に効果があると言われておりますので、ぜひここについての、東京都の今、細かい状況は出てきていませんけれども、予算がつくのは間違いないと考えていますので、その辺をしっかり注視していただいて、まずこれを実施していただきたいのとともに。","respondent":"長尾建築課長","answer":"区としましても、そういった東京都の支援策というところは、しっかりと取り入れながら、今後の２０００年までに建築された新耐震の木造住宅に対しての耐震改修の支援というところは検討していきたいと考えております。","id":"exchange-120"},{"speaker":"たけうち委員","kind":"質問・要望","question":"やはり、年間２件というのは非常に、今までも積み重ねてきた中での結果だとは思うのですけれども、やはり戸別訪問を５５０件やって、また今これだけ、地震がいつ起きるか分からないと言われている中で、助成、改修が２件しかないというのは非常に残念な結果になっているかなと思っていますので、ちょうど今、トルコで大地震が起きて、本当に大きな被害が出ておりますけれども。","respondent":"長尾建築課長","answer":"現時点では、耐震改修につきましては、なかなか利用実績としては伸びておりませんけれども、引き続き、東京都の新しい支援事業の内容を含めまして、区内の耐震化を進めて、より被害を軽減していけるように尽力していきたいと考えております。","id":"exchange-121"},{"speaker":"高橋（し）委員","kind":"意見","question":"６２ページの財政管理費、６４ページの新庁舎整備費から、特に新庁舎整備基本計画についてお尋ねします。今年の１月に、品川区新庁舎整備基本計画が策定されました。これから基本設計、実施設計を経て、令和９年度の竣工を目指すことになっています。このような経過において、改めて前年度の最終補正で積立てが分かっていれば、どうして当初予算に３０億円計上しなかったのかお尋ねします。","respondent":"黒田財政課長","answer":"そういった中では、全体フレームを出す中で、当初予算にどのぐらい庁舎の基金積立てができるかといったところで、令和４年度については５億円の予算を計上させていただいたです。","id":"exchange-122"},{"speaker":"高橋（し）委員","kind":"質問","question":"５億円ではないわけです。つまり、補正などの状況から、令和４年当初でも、そういうことを考えれば、今ご説明がありましたけれども、令和４年度当初で、それぐらい積み上げることが可能だったのではないでしょうか。見込みを持って庁舎整備基金を積み立てようとした、令和３年度、そして令和４年度の状況は少し疑問があるのですが、それについていかがでしょうか。","respondent":"黒田財政課長","answer":"そういった中で、補正予算で今回、２５億円計上したということでございまして、その部分を令和４年度の当初予算の段階から見込めないのかというご質問かと思いますが、ここにつきましては、確実に財源を見込めるものについて予算化しているというものです。","id":"exchange-123"},{"speaker":"高橋（し）委員","kind":"質問","question":"ということは、財源が出てきたので、令和５年度の予算は３０億円だということですね。ご説明は今のことで理解しました。そうすると、公共施設整備基金積立金の補正が約２０億円計上されています。こちらの基金の将来的な充当計画があれば教えてください。","respondent":"黒田財政課長","answer":"基金全体のところで言いますと、財源調整に使います財政調整基金や、公共施設の改築や改修などに使う公共施設整備基金というところで、ある程度、各年度の工事の計画に基づいて、一般財源で対応したり、基金を繰り入れたりというところで対応しておりますので。","id":"exchange-124"},{"speaker":"高橋（し）委員","kind":"質問","question":"したがって、今お話があったように財政的に余裕が出てきているのであれば、公共施設整備基金より、庁舎整備基金の積立てを優先させ、つまりもっと増額をするべきではないかと思うのですが、いかがでしょうか。","respondent":"黒田財政課長","answer":"ご指摘のあった公共施設整備基金につきましては、こちらは様々な公共施設の老朽化の改築等に対応しておりますので、今後のそういった整備を考えると、こちらの基金も一定程度、積立てが必要だと考えておりまして、令和４年度でも当初予算で繰入れを計画しておりますので。","id":"exchange-125"},{"speaker":"高橋（し）委員","kind":"質問","question":"庁舎整備計画事業と住居表示に関する条例との関係についてお伺いします。予定地について、旧ＪＲ用地が予定されていますが、私の後ろですね、区民の一部の方から、現行の区役所の住所の広町２－１－３６になじんでいるということで、これは品川区役所の位置変更に関する条例によって定められているのですけれども、まだ先のことだと思いますが、どのような決め方をいつ頃していくのか、お伺いします。","respondent":"山下新庁舎整備課長","answer":"ただいまご質問いただきました、位置に関する条例についてです。こちらは、住所地の付番が定まりましてから、実際に議会に上程していくことが予想されますので、一定、設計が進んでいく段階で、住所地の付番が成ります段階で、また議会にお諮りしていくことを考えてあります。","id":"exchange-126"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"それと同じように広がる可能性、つまり住所が変わらない可能性もあるのではないかと思います。そうすると、条例を今出せる。ほかの自治体だと、竣工の５年ぐらい前には、いわゆる位置条例を議会にかけたりしています。枚方市や鎌倉市は否決されましたが、そのようなことから、かなり前に、こういうところでこうやってやっていくという、きちんとした形をやっていただきたいと思いますが、いかがでしょうか。","respondent":"山下新庁舎整備課長","answer":"ただいまご指摘がございましたように、第二庁舎においては広町二丁目１番３６号を拡張したというようなお話ですけれども、実際、今回予定しておりますのは、今、委員からもご紹介があった、委員の後ろところになりまして、場所として少し離れたところになりますので。","id":"exchange-127"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"適切な時期ということですが、できるだけ早く、きちんとした議論を議会でするべく提出していただきたいと思います。今、課長からお話があったように、道路が通るのです。これは仮定の話なので。ともあれ何がお話ししたいかというと、位置条例については、きちんと早めに議会に提出して、議会の中でしっかりと議論をしていくと思っていますが、その点、いかがでしょうか。","respondent":"山下新庁舎整備課長","answer":"当然、条例ということですので、議会審議を経てこちらを定めていく形になりますので、適宜適切なタイミングで議会に上程できるよう、こちらとしても努力を続けてまいります。","id":"exchange-128"},{"speaker":"高橋（し）委員","kind":"質問","question":"時間がないのですが、そのために必要な議決はどれぐらいでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-129"},{"speaker":"高橋（伸）委員","kind":"質問","question":"６５ページ、地域振興経費、７９ページ、商店街にぎわい創出事業、８５ページ、高層マンション対策リーフレット作成等経費についてお伺いいたします。初めに、６５ページ、地域振興経費に関連いたしまして、質疑をします。小学生マラソン大会が、私の記憶ですと４年ぶりに開催されたと思います。お聞きしたいのは、担当の課長に、昨日見たことで率直な感想をお伺いしたいと思います。","respondent":"川島地域活動課長","answer":"最盛期は１,０００人ほどのランナーがいたということなのですけれども、昨日は６００人ぐらいの参加者だったということで、まちの中にも回って走るということで、通行止めにしたり、それから警察署の協力で白バイの先導がついたりという、かなり本格的なところもございまして。","id":"exchange-130"},{"speaker":"高橋（伸）委員","kind":"質問","question":"そうすると、私が思っているのが、今後、来年はどうなるか分かりませんけれども、再来年以降も継続していくのであれば、源氏前小学校以外の近隣の小学校などになるのか、青少年の地区委員たちの会議体によって、それが決まると思うのですけれども、そうすると関連して警察・消防などもいろいろな絡みが出て、道路使用許可等もありますので、区として今現在、どういうお考えか。","respondent":"川島地域活動課長","answer":"どこの会場にするのかというのは非常に大きな話ですが、今回５年ぶりにやったということで、占用許可、それから警察への届けなどというのも、多分、皆さん、従事者も地区委員の皆様も初めてのことも多かったと思いますので。","id":"exchange-131"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"これもやはり継続していただくのが私の要望なので、ぜひとも早い時期から検討していただきたいと思います。続きまして、７９ページ、商店街にぎわい創出事業に関連いたしまして質問します。２月１８日土曜日から３月１２日日曜日まで、これは大田区と大田観光協会としながわ観光協会が、今、「商店街をめぐって合言葉を探そう！それについて、まず最初にご説明をお願いしたいと思います。","respondent":"山崎文化スポーツ振興部長","answer":"品川区と大田区は、例えば東急電鉄などによって、まち、商店街がくっついて、あるいは近隣で形成されているような状況があります。両区の観光協会が連携しながら、相乗効果を狙って回遊性を高めてというようなことで、現在実施している事業です。","id":"exchange-132"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"これは開催場所が、荏原町と旗の台が主となっているのです。大田区は長原と洗足池エリアなのです。このイベントは旗の台にとってすばらしいイベントだなと、本当にいいイベントを開催していただいて、私はありがたく思っております。もう少し近隣地域との連携も意識したイベントにしたほうが事業性の効果が高いと私は思っているのですけれども、お考えをお聞かせいただきたいと思います。","respondent":"山崎文化スポーツ振興部長","answer":"品川区は、先ほども、鉄道はつながっておりまして、例えば大田区や、武蔵小山のほうですと目黒区の商店街も、一体的に実は商売のなりわいの商圏とすると、区域を挟んで広がりを持たせている部分もありますので、今、委員がおっしゃったようなイベントの広がり云々も含めて。","id":"exchange-133"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ですから、旗の台に特化、荏原町に特化するわけではないですけれども、今後、旗の台・荏原町エリアも、先ほどの大田区とやっているようなイベントができたらいいのかなと私は思っていますので、これは要望として入れていただきたいと思います。よろしくお願いします。続きまして、８５ページ、高層マンション対策リーフレット作成等経費についてお伺いいたします。","respondent":"平原防災課長","answer":"高層マンションにおけるフラッシュオーバーにつきましては、高層マンション特有の現象といいましょうか、火災時の要注意事項の一つだと認識しております。","id":"exchange-134"},{"speaker":"高橋（伸）委員","kind":"質問","question":"先日、２月に江東区で高層マンションの火災がありました。これはフラッシュオーバーだったそうです。高層マンションに関していうと、リーフレットの中に「フラッシュオーバー」という用語というのですか、それはいずれ何かしらで区民の皆さんに、記載していただくということもあったほうがいいのかなと私は思っているのですけれども、そのことについてお伺いしたいと思います。","respondent":"平原防災課長","answer":"今ご指摘のございましたフラッシュオーバーをどのような形で位置づけるかですけれども、こちらは、ご指摘のとおり、高層マンションにかかわらず懸念される事項ですが、こちらの具体的な書きぶりについては、東京消防庁と連携しながら工夫してまいりたいと考えています。","id":"exchange-135"},{"speaker":"高橋（伸）委員","kind":"意見","question":"恐らくこれは、１,０００度を超える高温の火災が一気に広がることから、マンションの延焼に相当な打撃があると思っているのです。低層マンションも含めてご検討をお願いしたいと思いますので、そのご見解をもう一度お願いしたいと思います。","respondent":"平原防災課長","answer":"今回の事業の見直しに伴いまして、対象とするマンションですけれども、改めて、今、検討し直しています。前回、１０階建て以上といったところを対象とさせていただきましたけれども、こちらは実情に合わせまして拡大する方向で、今、検討を進めているところです。","id":"exchange-136"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ぜひ検討を進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-137"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"私からは、８５ページの住宅費のところで、住宅改善工事助成事業、エコ＆バリアフリー住宅改修について、それから５１ページの新型コロナウイルス感染症緊急包括支援交付金に関連して新型コロナウイルス感染症対応地方創生臨時交付金について伺いたいと思います。それから、４３ページの生活困窮者自立支援事業について伺います。初めに、住宅改善工事助成事業、エコ＆バリアフリー住宅改修について伺います。","respondent":"竹田住宅課長","answer":"住宅改善工事助成についてのご質問です。過去５年ということですので、平成２９年度からご説明いたします。平成２９年度当初予算額が４,２００万円、申請件数が２６１件、受付が２月７日に受付期間満了です。","id":"exchange-138"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"厳しい経済情勢の中で、中小事業者の経済を循環させるためにも、今年度に限っては５か月間も制度が使えないという状況は改善が必要なのではないかと思うのですけれども、ぜひとも補正を組んで希望者全員が受けられるように求めますが、いかがでしょうか。","respondent":"竹田住宅課長","answer":"こちらの工事助成の申請状況ですが、年度により、令和元年度や令和３年度のように、申込み予定終了日前に、受付期間満了まで受付を行い、予算に達し、受付を終了した年度もあれば、平成２９年度や令和２年度のように、受付期間終了まで受付を行って。","id":"exchange-139"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"新型コロナウイルス感染症対応地方創生臨時交付金について伺います。国のホームページでは、３回目の実施計画提出締切りが１０月３１日となっていました。４回目の計画というのは、品川区としてどんなものを提出したのか伺いたいと思います。計画については、しかるべきときに公表するということで、総務委員会で課長が答弁されていましたけれども、計画の公表はしないのか、その点についても伺います。","respondent":"黒田財政課長","answer":"その後の交付の予定はですが、その後、地方単独事業について改めて交付するということで調査が来ておりまして、そちらでは、最終補正予算になりますと、事業の実施がなかなか難しいところもありますので、当初予算で編成しておりました。","id":"exchange-140"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"そうしますと、４回目の一億四千数百万円が、これから使える臨時交付金ということになるのでしょうか。それ以外は、活用できるものはないのか。その点についても伺いたいと思います。そういうところで改めて、臨時交付金も使いながら区独自に臨時交付金を活用して、ひとり親家庭への給付金や、住民税均等割世帯への支援を求めたいと思いますが、いかがでしょうか。","respondent":"黒田財政課長","answer":"これから交付される金額ですが、こちらはあくまでも補正予算編成後に交付の内示があるものですから、使うとしますと、既存歳出がある事業について、要綱にかなうものについて、充当できそうだというところで。","id":"exchange-141"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"そういう国の対応だけでは足りないので、改めてぎりぎりのボーダーの方々への支援もぜひともやっていただきたいということで提案していますので、ぜひご検討いただきたいと思います。３つ目に、生活困窮者の支援について伺いたいと思います。生活困窮者への支援が、もう次々に打ち切られてしまって、大変な状況になっています。","respondent":"櫻木生活福祉課長","answer":"社会福祉協議会が実施している生活福祉資金のうち緊急小口資金につきましては、６,５０７件、１２億９,５２１万円、総合支援資金につきましては、合計で１万９３０件、再貸付けを含めた金額は５５億１,９３７万円。","id":"exchange-142"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"もう時間がなくなってしまって、これ以上質問できないので、態度だけ申し上げたいと思います。第１号議案、一般会計補正予算に対しては、３年にわたるコロナ禍に加えて物価高騰によって多くの区民が追い詰められているにもかかわらず、暮らしを守る対策もなく基金に積み立てるものであり、反対です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-143"},{"speaker":"若林委員","kind":"提案","question":"私はいわゆる賛成の立場で。私はその中で１つのアイデアとして、これは広く区民の方に啓発・啓蒙ということですので、私もよく分かりませんでしたけれども、手元で調べてもあれでしたけれども、区内で多くのオレンジキャンドルを作って、灯して、それがギネスに認定されるぐらいのことをやりましょうという提案をして、採用されるかどうか分かりませんけれども、そういうことを申し上げました。","respondent":"提坂税務課長","answer":"令和４年度の当初予算につきましては、コロナの影響等を考慮しまして、前年度比４,９００万円マイナスということで予算を組んだのですけれども、加熱式たばこというものがございまして、従来、葉たばこと溶液を合わせて１グラムにつき１本という換算だったのですが。","id":"exchange-144"},{"speaker":"若林委員","kind":"質問・要望","question":"ということで、喫煙所の話題に入るわけですが、２月から工事が始まって、大崎駅の西口のコンテナ型の喫煙所が４月中旬に完成する予定です。ただ、やはり何かやると、また新しい懸念が出てきます。西口のコンテナ型の喫煙所の定員を、まず教えていただきたいと思います。やはり最初が肝心だと思いますので、その辺は今どういうふうに西口について対策を考えておられるか、一言お願いいたします。","respondent":"森田生活安全担当課長","answer":"定員です。大崎駅西口のコンテナ型喫煙所につきましては、現在、工事中ですが、１０名を予定しております。大崎西口の喫煙所につきましては、コンテナ型にプラスしまして、加熱式喫煙の方もできるようなエリアも設ける予定です。","id":"exchange-145"},{"speaker":"若林委員","kind":"質問・要望","question":"この敷地内に並ぶ人と、それから道路に並ぶ人も当然、どこまで足跡をつけるか分かりませんけれども、敷地内と敷地の外、歩道・道路側というのですか、そこの規制の根拠というのは、どのような違いが何かあるのか、ないのか。要するに、ポイ捨て条例の適用内とか外とか、その辺を精査していただきたいと思うのですが、お考えがあればお願いいたします。","respondent":"森田生活安全担当課長","answer":"大崎駅西口の喫煙所の周辺につきましては、指定地区ということで、路上喫煙禁止の場所です。指定喫煙所の中については当然喫煙できますが、路上につきましては規制にかかるところですので、ここで吸うことは当然、禁止になっております。","id":"exchange-146"},{"speaker":"若林委員","kind":"意見","question":"そうすると、今、敷地内はあまり規制がないというようなお話で、そうすると、コンテナに入れない人が道路の間の敷地内の足跡に立ったときに吸ってしまうという懸念のことを申し上げているので、ではもう一言お願いいたします。","respondent":"森田生活安全担当課長","answer":"これは、足跡マークと同じように表示物として、並び列での喫煙はできませんという表示もしますのと、あと、２か月の間、整理・誘導につきますけれども、そのときにしっかりとルール化を図っていきたいと考えています。","id":"exchange-147"},{"speaker":"渡部委員","kind":"質問・要望","question":"６４ページは人事管理費で、６３ページは国際友好都市交流事業、８６ページで教育指導費の中で伺っていきますが、教育指導費のところから聞きます。やっていただいていることに感謝申し上げます。過去には義務教育学校で勉強合宿がなされていて、それ以外の学校などでも日帰りでなさっていたということなのですけれども、これはしっかり復活していくのかどうかというのを、まず１つ、教えてください。","respondent":"中谷指導課長","answer":"次年度に関しましては、コロナが明けて、またこれが展開できるというところになっておりますので、これまでと同様の形で、当初予定ということで宿泊事業を実施して継続していきたいと考えています。","id":"exchange-148"},{"speaker":"渡部委員","kind":"質問","question":"新年度を楽しみにしています。誰か１人出してくださいと。国際友好協会の仕事かもしれないのですけれども、総務課、この辺何かあれば教えてほしいのと、例えばニュージーランド、オークランドとはそういうつながりがあるのだけれども、これだけ今、グローバル化していく中で、そうしたら少しほかの国と何かできることをやっていくというのをそろそろ考えてほしいなとも思います。","respondent":"古巻総務課長","answer":"今、ご紹介いただきましたオークランド市、今年派遣で語学研修を予定しておりますけれども、説明会に２００人ぐらいの方がいらっしゃったということで、私もびっくりしたのですけれども、行ける人数が本当に３０人、校長枠が１５人。","id":"exchange-149"},{"speaker":"渡部委員","kind":"質問・要望","question":"子どもたちのところですけれども、今、総務課長からご紹介いただいた、１５人の枠に２００人の申込みがあったというのはすごいことだと思うのです。それは分かるのですけれども、ただ、ライフプランの変更というのは大きいのと、予算書も確認しました。その中で、困る人たちがいた場合、それを助ける仕組みというのは、やはりどこか必要なのではないかと私は思うのだけれども、どうなのですか。","respondent":"崎村人事課長","answer":"今、委員からお話がありましたように、課長補佐に降任となりますと、確かに経過措置で一定の給与水準というのは保障はされているのですけれども、ただ、これまで管理職で働いてきた者が、課長補佐として、では１係長級として働けるのかというと。","id":"exchange-150"},{"speaker":"渡部委員","kind":"質問・要望","question":"新たな制度が生まれるわけですから、ここは本当に丁寧にやっていただかないと。皆様、すごく能力があって、やる気があって、なさってこられた方だから、その心配は全くないと思いますけれども、本当にここは、私は心配していますし、この５年間、様子を見ていく。多分、ほかの議員たちもそうだと思うのですけれども、何か不利益がないようにだけは努めて差し上げていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-151"},{"speaker":"松本委員","kind":"質問","question":"私からは、４７ページ、学校ＩＣＴ活用経費、あと時間が足りなくなるかもしれませんが、６４ページ、人事管理費、４０ページ、特別区財政調整交付金について伺います。学校ＩＣＴ活用経費についてなのですけれども、昨年の１２月から、令和４年度ＩＣＴ活用状況に関する保護者アンケートというものが実施されているかと思います。こちらの実施費用なのですけれども、どの程度かかったのか、お伺いいたします。","respondent":"中谷指導課長","answer":"ＩＣＴの活用状況のアンケートということですけれども、こちらに関しては、指導課の特色ある教育活動経費の予算の中で１５０万円の予算を取りまして、実質は８５万５,０００円ということで支出をする見込みとなっております。","id":"exchange-152"},{"speaker":"松本委員","kind":"質問","question":"そのアンケートについて少し具体的に聞こうかと思ったのですけれども、その前に、午前中に、せらく委員からの質疑で、学校との連絡、プリントなどのやり取りについての質疑があって、どうなのかなというところがあったので、引き続きここを少しお伺いしたいのですけれども、先ほどの答弁では、せらく委員から、学校のプリントや連絡というのをタブレットでできるようになったらペーパーレスにもなるし。","respondent":"勝亦学務課長","answer":"そういった学校でも、それぞれ保護者の状況を確認した上で対応を取っているという状況です。","id":"exchange-153"},{"speaker":"松本委員","kind":"質問・要望","question":"ここでカットされているのが、保護者の方たちの意見が直接教育委員会に届いているかというところが大事なのかなと思います。その中で、せっかく令和４年度ＩＣＴ活用状況に関する保護者アンケートというものが行われているというところなのですけれども、紙の連絡について、今、不便を感じているとか、そういうアンケート項目があったのか、お伺いいたします。","respondent":"中谷指導課長","answer":"ただ、教職員については、ご家庭での使用時のルール決めというのは除く項目となっております。その中で、３者の意識が同じようなものになるのか、もしくは異なるものになるのかといった視点で分析をしていくというのが、このアンケートの趣旨となっております。","id":"exchange-154"},{"speaker":"松本委員","kind":"質問・要望","question":"それで、今おっしゃったアンケートの項目を、ある程度私のほうでも拝見したのですけれども、今おっしゃられていたようなアンケートの内容を見ても、これは目的としては、今後ＩＣＴをさらに推進していくというところが目的だと思うのですけれども、今おっしゃっていただいた項目を聞いても、ではどういうふうに具体的にこれから前に進んでいくのかというところが。","respondent":"中谷指導課長","answer":"教育委員会としましては、１１月にＩＣＴ ＳＹＭＰＯＳＩＵＭを行っておりますので、その成果が動画として現在もホームページにありますので、そういったものの閲覧というところを積極的に働きかけていきたいと考えています。","id":"exchange-155"},{"speaker":"松本委員","kind":"質問・要望","question":"自由記載欄もないし、では、なぜ活用できていないかという保護者の意見を問うような、なぜの質問がなかなかないというふうなことがありました。ですので、今後アンケートを取られるときには、こういった自由記載欄、あるいは、なぜ今活用できていないかということについて、保護者から意見を聞くような項目を入れていただきたいと思いますが、いかがでしょうか。","respondent":"中谷指導課長","answer":"そういったところも把握しておりまして、個人的にインストールすることはできないのですけれども、教育委員会の判断で、学校から申請があったものについては許可をするというような形を取らせていただいております。","id":"exchange-156"},{"speaker":"松本委員","kind":"意見","question":"知らないという方もいらっしゃるので、きちんと周知をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-157"},{"speaker":"吉田委員","kind":"質問・要望","question":"６９ページの民生費、障害者グループホーム整備等助成について伺います。両方とも、ほかの委員からも質疑が出ましたので、併せて、午前中の生活者ネットワークの質問で聞き切れなかった、６１ページ、羽田空港周辺振興協議会のことと、８３ページ、コミュニティバス試行運行実施経費、７７ページ、新型コロナウイルス感染症対策について、聞けるところまで伺います。","respondent":"櫻木生活福祉課長","answer":"マスクにつきましては、区に寄贈されたようなマスクにつきましては、全体として配分されているような経緯がございまして、また今後、マスクについて、そのようなお話があった場合は、そのような状況で、また検討してまいりたいと思います。","id":"exchange-158"},{"speaker":"吉田委員","kind":"質問・要望","question":"住居確保給付金のことです。先ほど他の委員からの質問の中で、いろいろな数字も確認させていただきましたが、やはり広報で、年代層によってどういう広報を受け止めやすいかというのは違ってくるのかなと思います。現状でその辺がどうなっているのか、気になるところです。やはり、私たちにご相談が来るぐらいですから、困っている方は結構いらっしゃると思うのです。ぜひその辺、ご見解を伺いたいと思います。","respondent":"櫻木生活福祉課長","answer":"原則はそのようなことですが、ご提案できるようなところがあれば提案をするように、また指導してまいりたいと考えています。","id":"exchange-159"},{"speaker":"吉田委員","kind":"提案","question":"具体的・客観的に資産がどの程度というのは、私も提案は持ち合わせていないので、ぜひこれは検討していただきたいという要望にとどめたいと思います。例えば、今、いろいろ複数件、ご相談が進行中ということでしたが、その中で、感覚的に２,５００万円で何とかなりそうかなという事例かどうか、伺いたいと思います。ぜひその辺の支援をお願いしたいのですけれども、いかがでしょうか。","respondent":"川崎障害者施策推進課長","answer":"積極的なグループホームの普及活動というのも行っているので、品川区としましては、今後、障害者グループホームの整備を進めていく上で、運営事業者紹介の手だての一つとして、ホームページ上でこういった団体を紹介・周知していくということも、検討したいと考えております。","id":"exchange-160"},{"speaker":"吉田委員","kind":"質問・要望","question":"運営事業者について、分かりました。先ほどの午前中の質問について、要するに助成金が出ているのであれば、その助成金を区民が必要としている助成金に使うべきではないのですかということを伺いたかったのです。それで、書いてあるのだったら見せてほしいし、書いていないのだったら、区としてそういうものも助成金の対象にしてほしいと要望してほしいという趣旨の質問だったのですけれども、見解を伺います。","respondent":"鈴木都市計画課長","answer":"羽田空港周辺協議会の募集要項に関するお尋ねですが、こちらの内容につきましては、以前のお問合せを頂いた際に、防音工事助成の対象になるかどうかについても併せてご回答させていただいているところです。","id":"exchange-161"},{"speaker":"吉田委員","kind":"質問・要望","question":"だから、私たちとしては、それがどうか確認できないということですよね。もし、そういうものが助成対象になっていないのであれば、区としてやはりこういう助成制度があるのだったら、区民のそういう要望に応えられるような項目を入れてほしいということを要望してほしいのですけれども、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"この要項を見直していただいて、対象としていただけるのかも含めて、幅広く、様々使いやすい形で、航空機騒音防止法だけではなくて様々な形で助成制度を行っていただけるように、国には引き続き求めていきたいです。","id":"exchange-162"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひ要望していってください。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-163"},{"speaker":"鈴木（博）委員","kind":"質問","question":"本日は、７７ページ、感染症対策事業から新型コロナウイルス感染症対策の類型変更と感染予防対策についてお尋ねいたします。政府は本年５月８日から、新型コロナ感染症の感染症法上の位置づけを２類相当から５類へ移行する方針を決定し、現在、準備が進められています。政府のこの２類相当から５類に移行するという決定に対する品川区のご理解と今後の対応について、簡単にご説明をお願いします。","respondent":"坂野保健予防課長","answer":"それで、感染が再拡大した場合に備え、機動的に対応できる体制を維持していくという、これは東京都の方針なのですが、これに準じた形で品川区もやっていきたいと考えております。","id":"exchange-164"},{"speaker":"大倉委員","kind":"提案","question":"８５ページ、防災普及教育費、７９ページ、商店街にぎわい創出事業、７７ページ、新型コロナウイルス感染症対策、学校ＩＣＴ活用経費で伺えればと思います。そうした支援というのは、今までは政府から補助金などが入ったり、マスクの無料配布みたいなものがあったかと思うのですが、現在に関してはどのようになっているのか教えていただきたいと思います。７９ページ、商店街にぎわい創出事業。","respondent":"菅野高齢者福祉課長、平原防災課長、中谷指導課長、山崎文化スポーツ振興部長","answer":"今までも、令和２年度には、介護サービス業務継続支援金や、クラウドファンディングによる寄附金を活用してフェースシールド等を購入して。民間アプリというような形で考えてきたところ、これまでの普及率から、品川区公式アカウントのＬＩＮＥアプリを使いまして、今。オンラインの活用状況ということも引き続きやっておりまして、課題としましては。来年度も実施しますので、さらなる連携強化に努めて、区民の皆さんに一時楽しんでいただけるイベントを醸し出したいと思うところです。","id":"exchange-165"},{"speaker":"大倉委員","kind":"質問・要望","question":"冊子を常に持ち歩くことはなかなかない中で、やはり携帯電話、スマートフォンにアプリを入れて、災害時に安心して、これを見て避難するというのが現実的だろうと思うところでは、そうしたＬＩＮＥアプリということなので、これをさらに発展させていって、より安心安全な、災害時に使えるようなものにしていっていただきたいと思いますが、ご見解を伺いたいと思います。教えてください。","respondent":"平原防災課長、菅野高齢者福祉課長、中谷指導課長","answer":"ＬＩＮＥアプリを通じました防災普及ですけれども、現在、委員ご指摘のとおり、例えば地図を連動していますけれども。区としましては、東京都もＰＣＲ検査を、少し６月まで延ばしているというところになっておりますので、それ以外の緊急性を要するところで。ＩＣＴです。現在、各校で１取組の優良事例というものをまとめておりまして、それらを全て集約した事例集というものを作成していく予定になっております。","id":"exchange-166"},{"speaker":"大倉委員","kind":"提案","question":"その負担が事業所に行って、その負担を事業所が担うことによって、また様々、費用の部分で環境を整えられなくならないようにしていただきたいと思って、しっかり応援していただければと思って伺いましたので、ぜひよろしくお願いいたします。ＩＣＴ推進については分かりました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-167"},{"speaker":"石田委員","kind":"質問","question":"私は、９７ページからの、国民健康保険事業会計、そして後期高齢者医療特別会計、介護保険特別会計の３つをまとめて伺っていきたいと思います。令和３年度は、当初予算１０億円余から、最終補正で６億円余のマイナスにしています。それで、これだけマイナスする額に開きがあるというのはどういうことなのか、ばらつきの理由を伺いたいと思います。","respondent":"池田国保医療年金課長","answer":"令和３年度につきましては、医療費の伸びを多く見込みを立てたところ、そこが意外に、予想したより伸びなかったというところで、繰越金が多く計上されたものがございまして、繰り越すお金が多くなってきたもので、こちらの多いものを実際にいろいろなところに充てましたところ。","id":"exchange-168"},{"speaker":"石田委員","kind":"質問・要望","question":"医療費がそこまで伸びずに、繰越金で済まされたみたいなところだと思うのですけれども、やはり国民健康保険料はそもそも高いですから、負担軽減のために、法定外繰入れはマイナスにするのではなく、それこそ繰り入れてほしいと思っているのですが、２０１８年に国民健康保険の広域化が進められて、広域化の目的は法定外繰入れの解消ですから。","respondent":"池田国保医療年金課長","answer":"国民健康保険の賦課に関することにつきましては、国民健康保険法で決まっておりますので、一自治体が変えることはできません。","id":"exchange-169"},{"speaker":"石田委員","kind":"質問・要望","question":"それで、昨年の２月の厚生委員会で、後期高齢者保険料の値上げ改定の説明がされて、その中で所得の伸び率がマイナス１.２％となっているということについて、７５歳以上の方の所得がマイナス１.２％になっている理由を伺いましたところ、後期高齢者で働いている方が、その労働をやめたり、高齢のために控えたことで、所得が減っているという説明でした。今も把握はされていないのでしょうか。伺います。","respondent":"池田国保医療年金課長","answer":"先ほどの国民健康保険料につきましては、賦課については国民健康保険法で決まっているということでご説明をさせていただきました。減免と賦課は全く違うもので、ご理解いただきたいというご答弁をさせていただいたところですので、減免できるという言い方はしておりません。","id":"exchange-170"},{"speaker":"石田委員","kind":"質問","question":"把握されている人数はお答えいただいて、分かりました。年金は毎年のように下げられて、保険料や医療費の窓口負担は値上がって、さらに物価高騰もあるわけで、７５歳以上になっても働くということは、年金だけではやっていけないということではないかなと。そういう状況が高齢者の中にあるという状況だと思わないのか、伺いたいと思います。","respondent":"池田国保医療年金課長","answer":"働いている方が多くいらっしゃるということではなく、１割・２割の負担をされる方が５割以上いらっしゃるということは、年金収入だけで５割だけ働いている方ということも、はっきりとこちらでは把握はしていないですけれども、収入の少ない方ということでの把握をしています。","id":"exchange-171"},{"speaker":"石田委員","kind":"質問・要望","question":"そういう方が働かれているという現状を見れば、保険料や窓口負担を引き上げるのではなく、引下げこそ国に求めていただきたいし、それで、国がやらないのであれば区として独自で引下げこそすべきだということを、ずっと私たちは求めております。そこを進めていただきたいのに、最終の補正予算では軒並みマイナスという状況ですので、マイナスではなく繰入れこそするべきだと求めたいと思います。","respondent":"菅野高齢者福祉課長","answer":"介護保険制度の改悪についてというお話ですけれども、国で現在、審議会等で、来年度第９期の介護保険事業計画についての方針等、いろいろと審議している最中です。","id":"exchange-172"},{"speaker":"石田委員","kind":"質問・要望","question":"ぜひ反対していただきたいと思うのです。これだけの介護改悪、もう史上最悪の介護保険改悪だと言われておりますので、ぜひ負担軽減、そして利用しやすい制度の充実へと求めていっていただきたいと思います。軽減こそすべきです。よって、令和４年度の各補正予算、第２号議案、国民健康保険事業会計第３号議案、後期高齢者医療特別会計第４号議案、介護保険特別会計に反対の態度を表明して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-173"},{"speaker":"塚本委員","kind":"質問","question":"私からは、４７ページ、公立学校情報機器整備費補助金と併せて、６２ページの情報化推進費。これは２つ併せて、いわゆる学校運営上の事務について、具体的には入学手続なのですけれども、これについて伺いたいのと、あと、８１ページの第二戸越幹線整備工事について伺いたいと思います。","respondent":"勝亦学務課長","answer":"転校等に当たりましても、添付書類や選考に当たっての面談等を行う状況がありますので、紙で対応しているような状況になってあります。","id":"exchange-174"},{"speaker":"塚本委員","kind":"質問","question":"今のお話でいくと、保護者が学校に持参するということが前提ということなのですかね。面談をする必要があるなどということをおっしゃっていたので。これについて、教育委員会としてのご見解を伺いたいと思います。","respondent":"勝亦学務課長","answer":"手続に関わるデジタル化など、利便性の向上は重要な課題だと考えています。今後、紙をデジタル化するだけでなく、例えば面談、添付書類といったものを、業務フローの見直しややり方の見直しの研究を重ねまして、利便性の向上に努めてまいりたいと考えています。","id":"exchange-175"},{"speaker":"塚本委員","kind":"質問・要望","question":"そのときに、効率化できそうな、あるいはデジタル化できそうな業務として、１６５の業務がリストアップされたということでございました。要するに、オンライン化されるものとして対象となっているのかどうか。これはもうすぐなるんですとか、これはまだいろいろ課題があってできないんですなどということが分かるといいなというところがあるのですけれども、これについてご見解を伺いたいと思います。","respondent":"宮澤情報推進課長","answer":"見える化につきましては、ＤＸの取組につきましては、ホームページで公開しております。分かりやすい形で公開していくような形は工夫していきたいと考えております。","id":"exchange-176"},{"speaker":"塚本委員","kind":"質問","question":"令和７年度に向けてということで、全ての手続とご答弁いただきましたか。そういう意味では、全てそうなるのだということで、一義的にはまず皆さんにご説明できるのかなと思いますけれども、それについて何かあれば、もう一言お願いしたいと思います。併せて、第二戸越幹線整備工事ですけれども、１６億６,５００万円の減額ということになっております。この減額理由についても、併せて伺います。","respondent":"宮澤情報推進課長、栗原河川下水道課長","answer":"手続のオンライン化につきまして、手続の洗い出しというのを行いまして、中には課題のある手続等もあるというのは認識しております。その辺の課題を一つずつクリアしながら、手続をオンライン化していくです。本工事は、令和２年から令和５年までの４か年にわたる債務負担工事でございまして、残りの掘削につきましては令和５年度に実施する予定です。","id":"exchange-177"},{"speaker":"塚本委員","kind":"質問","question":"今、そういう理由で、一部工事がストップしたような状況があったというようなお話でしたけれども、これが、遅れを取り戻して、当初の予定で計画されていたとおりにスケジュールどおり完成するのか。一部、公園を押さえて、使えないような状況でやっているところがあるので、そこが元どおり戻る日というのは地域の方も期待しておりますので、そこについてお伺いしたいと思います。","respondent":"栗原河川下水道課長","answer":"第二戸越幹線の下流部シールド工事ですけれども、現在、トンネルの掘削を行っておりまして、その後、マンホールの築造や目黒川への雨水のはけ口の設置を行いまして、今回の遅れを含みまして、これまでの進捗を踏まえまして、今回の遅れの分は。","id":"exchange-178"},{"speaker":"鈴木（真）委員","kind":"質問","question":"私からは、先に７３ページの３款民生費、２項児童福祉費、私立保育園費、それから４０ページの９款特別区交付金の２点についてお聞きしたいと思います。私立保育園の関係です。区内私立保育園開設経費が、新規開設助成２億５,８００万円が今回減額になっていました。これは単純に新設がなかったということなのでしょうけれども、申込み状況など、その辺の関係をまず教えてください。","respondent":"中元保育支援課長","answer":"申込みの状況は、それほど大きく減ってはいないのですけれども、ただ、少し定員に空いているところができているというところです。それも、でもエリアによって、まちまちなところはあります。","id":"exchange-179"},{"speaker":"鈴木（真）委員","kind":"質問","question":"品川区は私立保育園の申込みを今、募集していないというか、受けていないという感じで捉えていいのでしょうか。その辺をまず１点、お聞きしたいと思います。今の、少し空きが出ているという中で、地域的には例えば第一京浜国道から海側ですか、東品川方向、また南大井。殊にお話を聞いていると、小規模保育の中でも空きが出ているということで、その辺、区の保育園に対する考え方を教えてください。","respondent":"中元保育支援課長","answer":"育児休暇の制度が普及してまいりまして、割とその辺りのクラスに余裕はありますが、ただやはり地域の中で、子育てに関して様々な悩みを抱えていらっしゃる方もいますし、今、国でも、一時預かりのモデル事業や、一時預かりに対して保育園での補助メニューが出てまいりましたので。","id":"exchange-180"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"先日の文教委員会の資料の中で、認証保育所から認可保育園への移行が２園あると出ていました。この点は終わらせていただきまして、財政調整です。時期的にどうなってくるのか、まず確認をさせてください。","respondent":"黒田財政課長","answer":"過去の事例といたしましては、昭和５１年度から５４年度に、都議会第２回定例会で都区合意して条例が改正されたという例があると聞いてあります。","id":"exchange-181"},{"speaker":"鈴木（真）委員","kind":"確認","question":"今まで、品川区に限らず２３区では、財政調整についてしっかりと、いろいろ議論しているのですが、東京都と特別区長会でやっている話なので、確認させていただきたかった点があるのですけれども、都議会として財政調整というのはどう捉えているのか。その辺で、都議会経験者として、どんな感じだったのかというのを教えていただければと思うのですが、いかがでしょうか。","respondent":"黒田財政課長","answer":"区側が現在５５.１％ですので、都側は４４.９％ということになりますから、これはいわゆる大都市事務について、都と区で、これまでの経過で合意してきたですから、当然、区側の配分が増えれば、都側の配分が減るということになりますが。","id":"exchange-182"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"今、区長の思いは分かりましたけれども、ぜひ特別区長会としても、これからも同じように、しっかりと東京都に対して要望して、０.１％、逆に言えばそれをもっと増やしてほしいというのを私どもも思っています。区の財源を確保するためにも、ぜひ区長のご努力をこれからもどうぞよろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-183"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/491981?Template=document&Id=1162#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":134880,"voices":414}},{"id":"r05-20230307-3","meetingId":"r05-c-budget","date":"2023年3月7日","dateIso":"2023-03-07","committee":"予算特別委員会","time":"午前１０時００分～午後 ６時０５分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を187件抜き出しています。","topics":[{"id":"topic-01","title":"令和５年度品川区一般会計予算","agenda":"令和５年度品川区一般会計予算","exchanges":[{"speaker":"澤田委員","kind":"質問","question":"おはようあります。本日もどうぞよろしくお願いいたします。１１３ページ、１４款都支出金、地域生活支援事業、１５２ページ、１９款諸収入に関連して質問いたします。地域生活支援事業についてお伺いします。地域生活支援事業ほか５事業、補助基本額とありますが、この中にペアレント・トレーニングは含まれているのでしょうか、お聞かせください。","respondent":"松山障害者支援課長","answer":"委員のおっしゃられるとおり、ペアレント・トレーニングはこの中に含まれております。","id":"exchange-001"},{"speaker":"澤田委員","kind":"質問・要望","question":"ら・るーとより対象年齢の低い未就学児などを対象とした障害児支援施設である品川児童学園では、現在、まだペアレント・トレーニングは行われていませんが、来年度からこちらの施設でもペアレント・トレーニングがスタートすると伺っています。もし予定されていないのであれば、ぜひ広く受講していただけるように、オンラインでの実施を行っていただきたいという要望を込めて、区のご見解をお聞かせください。","respondent":"松山障害者支援課長","answer":"来年度から品川児童学園で実施します、ペアレント・トレーニングにつきましての詳細な内容は、現在、指定管理者と、ペアレント・トレーニングの専門家と、協議、調整しています。委員のおっしゃられるオンラインでのメリットも含めまして検討しています。","id":"exchange-002"},{"speaker":"澤田委員","kind":"質問・要望","question":"続いての質問にまいります。自閉症やアスペルガーなどと呼ばれているＡＳＤやＡＤＨＤ、また、ＬＤなどの発達障害は、見た目では分からないため、その特性を周りに理解してもらえないことが珍しくありません。小中学校などの教育施設での知識の普及・啓発に取り組むことが大変重要だと考えており、強く要望するとともに、区としては、どのようなお考えをお持ちなのか、ぜひお聞かせいただけないでしょうか。","respondent":"松山障害者支援課長、矢部教育総合支援センター長","answer":"現在は、思春期サポート事業や、品川児童学園におきまして、支援者向け、あるいはご家族向けに普及・啓発を行っておりますけれども、今後どのような、広く一般の方にご理解いただけるのか。私どもは、まず、人権教育が一番大切だというふうに考えてありますので、市民科を中心に日々の指導に努めてまいりますが、発達障害等の対応につきましては、特別支援学級の自閉症・情緒障害の中学校の部において。","id":"exchange-003"},{"speaker":"澤田委員","kind":"質問","question":"続いての質問です。諸収入の雑入についてお伺いいたします。昨年の６月から新しい防災ラジオの発売が始まりましたが、新年度も発売されると思います。この代金は諸収入になるのでしょうか。","respondent":"平原防災課長","answer":"こちらの収入ですけれども、財産収入の財産売払収入という形で歳入とする形になります。","id":"exchange-004"},{"speaker":"澤田委員","kind":"質問・要望","question":"防災ラジオの販売についてお聞きします。品川区では、防災ラジオを１世帯につき１台を求める方に有償で配布しています。主な対象は、スマートフォンで災害情報を受け取ることが困難な６５歳以上の高齢者世代や障害をお持ちの方、また、経済的に困窮している非課税世帯の方だと伺いました。そこでお聞きします。何台製造し、また、販売実績はいかがでしたでしょうか。お願いいたします。","respondent":"平原防災課長","answer":"現状ですけれども、前回購入者の方が１,８２０台、それから新規のご購入の方が、昨日現在で１,３３６台の合計３,１５６台が、現在、３００台以外に販売分として３,１５６台が販売対象となったところです。","id":"exchange-005"},{"speaker":"澤田委員","kind":"質問・要望","question":"在庫が現在まだ１,０００台以上あるということになりますけれども、ぜひ、しながわ防災体験館内に防災ラジオの在庫を予約せずに購入できるカウンターを設けることはいかがでしょうか。そして、カウンターで本人確認のできる保険証や障害者手帳などをその場で提示することにより、写しをわざわざ用意する手間を省くことはいかがでしょうか。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"新妻委員","kind":"質問・要望","question":"７７ページ、温水プール、１０１ページ、公園・児童遊園維持管理費、１２９ページ、都市計画交付金、しながわ区民公園から、順不同に伺ってまいります。昨日、時間が切れてしまいましたので、公園内における多言語化についてお伺いいたします。しながわ区民公園内には、大変人気のある子どもの自転車レンタルがあります。現在の公園内の案内等に関しての多言語化、区のお考えを改めてお伺いいたします。","respondent":"高梨公園課長","answer":"公園の全体としてのお話ですが、しながわ区民公園をはじめ、新しく改修等を行う公園等に関しましては、サインの英語表記併記であったりとか、トイレを中心として複数言語、今、区民公園の再整備の中では。","id":"exchange-007"},{"speaker":"新妻委員","kind":"質問・要望","question":"新しくなるところの多言語化は進んでいるということでありますが、この自転車のレンタル、非常に人気があります。現場の方からもお声があるところですので、ぜひ具体的にここは早く進めていただきたいと思います。改めて伺います。","respondent":"高梨公園課長","answer":"そういった声と、委員からのご指摘も受けまして、この区民公園の自転車貸出しのご案内の部分についての多言語化、英語と中国語の表記ということで現在考えておりますが、今月中にやるように、今、手配をかけているところです。","id":"exchange-008"},{"speaker":"新妻委員","kind":"質問・要望","question":"引き続き、翻訳機もご検討をお願いしたいと思います。順番を変えまして、温水プールの利用について伺います。令和４年度から現在までの利用状況をお知らせいただき、また、令和５年度の利用状況の見込みをお知らせいただきたいと思います。地域住民としては、区の施設を有効に使わせていただきたい、そのような思いがあるのですけれども、現状をお知らせいただきたいと思います。","respondent":"辻スポーツ推進課長","answer":"これは上部団体のプール協会が新しい指針を出したところで、また変更になるかと思いますが、制限はしておりますが、盛夏、真夏以外のところでは、十分コロナ禍前と変わらないような状況で推移しているという状況です。それから、団体貸切の件です。","id":"exchange-009"},{"speaker":"新妻委員","kind":"質問・要望","question":"学校施設でありますので、まずはそこを優先にということは理解をしておりますが、この３年間の間に、利用できる回数が大きく減ってきたという現状もありますので、そのところは、ぜひスポーツ推進課が主導していただきながら、地域の方も利用ができるようにご配慮いただければと思います。利用条件の緩和をご検討いただきたいと思うのですが、いかがでしょうか。","respondent":"辻スポーツ推進課長","answer":"委員ご指摘のように、他区ではコースで貸しているところもあることも承知しています。いろいろな区民の方の声をいただきながら、どのような貸出しの仕方が区民の健康増進に一番つながるのかということを随時考えていきたいと考えています。","id":"exchange-010"},{"speaker":"新妻委員","kind":"質問・要望","question":"ぜひ検討を進めていただきたいと思います。これに加えて、今年度は、できたら鮫洲駅からの案内をしていただきたいということ、また、隣接する民家への対応について、広場の植栽がある程度の高さになると剪定をされていくと、そのようなお声もありましたので、視線を塞ぐための工夫もしていただきながら、鑑賞時の声のことも含めて対応をお願いしたいと思いますが、いかがでしょうか。","respondent":"高梨公園課長","answer":"この間、境界にネットを張るなどの対応はしたところですが、引き続き近隣住民の方々からお話を聞きながら、必要な対応については前向きに行っていきたい、このように考えているところです。","id":"exchange-011"},{"speaker":"安藤委員","kind":"質問","question":"私は、５０ページ、特別区民税、５６ページ、特別区交付金、税収あるいは森澤区長の区政運営の姿勢についても伺っていきたいと思います。所得の高い５０代の人口が増えていると述べていました。伺いますけれども、人口を増やす、あるいは高額納税者を増やすということは、区が進めている超高層再開発事業の目的に入っているのか。それとも、全く関係ないのか、どちらなのでしょうか、伺います。","respondent":"黒田財政課長、多並都市開発課長","answer":"いわゆる税収の部分ですが、区民税は、ご案内のとおり、前年の個人収入に対してかけられるということでございまして、そういった意味では、まちが更新されて住むところが新しくなると、それなりの住居費がかかるという意味では。再開発事業につきましては、その地区のまちの課題を解決するために、地域の皆様が、地域主体でまちづくりの課題を解決するためにお話し合いいただき、その実現をするために。","id":"exchange-012"},{"speaker":"安藤委員","kind":"質問","question":"人口を増やす、高額納税者を増やすことは、再開発事業の目的と全く関係ないということなのか、それとも関係あるということなのか、もう一度伺います。","respondent":"多並都市開発課長","answer":"再開発事業につきましては、繰り返しになりますが、そのまちの、今あるまちの課題を解決するために、地域の方が、そこの土地の、例えば、低未利用地、要するに、駐車場であったり、駅前にあるものが、今度は、高度化を図るべきだとか、皆さんでお話ししていただいて。","id":"exchange-013"},{"speaker":"安藤委員","kind":"質問","question":"はっきり関係するとも関係しないとも言わないという感じだと思いますが、区長が４つの重点施策の第一に、「子育て・教育で選ばれるしながわ」と掲げています。しかし、案外この意味は語られていないと思っています。「選ばれるしながわ」とは、具体的にどういう意味なのか伺いたいと思います。選ぶ人は誰なのか、なぜ選ばれたいのか、改めて伺いたいと思います。","respondent":"佐藤企画調整課長","answer":"区長の施政方針における選ぶ、選ばれるというところのご質問だと思います。区におきましては、３つの無償化をはじめ、国に先駆けて先進的な子育て支援も含めて、来年度、選択と集中で財源を充てて進めていくものです。","id":"exchange-014"},{"speaker":"安藤委員","kind":"質問","question":"前濱野区政の成果として３つ挙げていまして、人口約７万人増加、９０％超が今後も住み続けたい、経済誌において財政力日本一と挙げていまして、それを継承と発展させるとしています。人口を増やすことと税収を上げることが１つのキーワードになっていると思います。「選ばれるしながわ」とは、これから区に転入する方、転入人口を増やしたいという意味なのでしょうか、伺います。","respondent":"佐藤企画調整課長","answer":"もう１点、先ほどご答弁しましたけれども、そういった施策について共感を得て、品川区に住みたい、都市ブランディングも活発化し、コロナの移行もありますので、やっていくというところで、そういうものも様々政策の効果で人口増につながれば、それはそれで。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問","question":"「選ばれるしながわ」、９割以上、品川区に住み続けたいという方がいますけれども、既にこの方々は品川区を選んで住んでいるわけですけれども、「選ばれるしながわ」という方針、この言葉は、現在住んでいる区民への目線が感じられないのですけれども、いかがでしょうか。","respondent":"佐藤企画調整課長","answer":"区といたしましては、そういった思いは全くなく、施政方針で書かれているとおり、区民の福祉向上に向けて、様々な施策をバランスよく、４つの体系をもって進めていくところです。","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問・要望","question":"私はこれは大いに違和感があって疑問なのです。子育て支援の充実は、「選ばれるしながわ」の実現のために行うものではないと思いますけれども、いかがでしょうか。人口を増やして税収が増えたら福祉に回すという考え方は転換していただき、住民福祉の増進との基本に立って、そういった区政運営に転換していただきたいのですけれども、併せて伺います。","respondent":"佐藤企画調整課長","answer":"「選ばれる」という言葉の捉え方だと思うのですが、今、４０万人、品川区民の方に住んでいただいていて、９割の方に引き続き住み続けたいと言っていただけている。それも１つ選ばれるというところだと思います。","id":"exchange-017"},{"speaker":"松永委員","kind":"質問","question":"私は、６９ページのボルダリング場について、９７ページの児童虐待防止対策等総合支援事業費補助金の中で、ヤングケアラー支援事業について、１０１ページの無電柱化推進事業について、時間がありましたら、１４７ページの過料についてお伺いいたします。６９ページのボルダリング場について伺います。","respondent":"辻スポーツ推進課長、高梨公園課長","answer":"ボルダリング場という専門の施設もありますが、その前に、まず少しやってみたいだとか、家族で行って少し楽しんでみようというような、そのような施設をつくりたいという思いで、区の真ん中にある適地として。これからも区民の方々のニーズ等をしっかりと踏まえて、アーバンスポーツについても機会を捉えて展開をしてまいりたい、このように考えているところです。","id":"exchange-018"},{"speaker":"松永委員","kind":"質問","question":"これで区のお考えははっきり見えたかと考えています。今後も、こうした幅広い層の方に周知していただければと考えています。続けて、令和５年度の予算では、約１万２,０００回ということなのですけれども、これはどのような形で計算されたのでしょうか、お知らせください。","respondent":"辻スポーツ推進課長","answer":"初めての施設ですので、区内に弓道場があります。こちらが一般利用と団体貸出しということで、こちらの施設と非常に類似していることから、弓道場の実績、それから、スケートボード場の利用率などを勘案しまして、その中から算出してこの数字を出したところです。","id":"exchange-019"},{"speaker":"松永委員","kind":"質問・要望","question":"実は私も、もう４１歳になるのですが、様々な意見を聞いて、ボルダリングデビューをしようかというふうに思っております。これから始めようとする方に対して、例えば、初心者教室や、またボウリング場のように、多分、シューズとか、滑り止めとか、レンタルできる環境にしていただきたいとは思っているのですけれども、現段階で、品川区はどのようなお考えをしているのかお知らせください。","respondent":"辻スポーツ推進課長","answer":"初心者でそのまま利用することもできるのですが、やはり不安な方もいらっしゃると思いますので、今のところ、月に１回、初心者講習会ということで、無料で開くような予定をしております。","id":"exchange-020"},{"speaker":"松永委員","kind":"質問・要望","question":"このボルダリング場の設計図を確認させていただいたのですが、無料エリアと有料エリアに分かれており、私自身は無料エリアで鍛えてから有料エリアで挑戦させていただきたいと考えています。無料エリアでは、２４時間使える環境だと聞いており、深夜等、使用される方がおられるかもしれません。こうした対策について、どのようにお考えでしょうか、お知らせください。","respondent":"高梨公園課長","answer":"夜間のそういったことが起きるようであれば、夜間の閉鎖等も視野に入れながら適切に管理してまいりたい、このように考えているところです。","id":"exchange-021"},{"speaker":"松永委員","kind":"質問・要望","question":"ぜひこうした近隣住民に配慮をしていただきたいと思います。さらに、使用上のルールとか、例えば入り口付近に、ふれあい掲示板みたいな少し大きい使用上のルールみたいな看板等を設置されてはどうかと考えていますが、いかがでしょうか。","respondent":"高梨公園課長","answer":"利用者の方に混乱のないように、分かりやすい掲示、周知に努めてまいりたいと考えております。","id":"exchange-022"},{"speaker":"松永委員","kind":"質問","question":"続きまして、９７ページのヤングケアラー支援事業について伺います。ヤングケアラーの問題は喫緊の課題の１つであると認識しております。そこで、相談の費用について、どのようになっているのでしょうか。相談を受け、教育、福祉、介護、医療の各機関の緊密な連携を促進させると伺っておりますが、その後の機関につながったとしても、その後また費用がかかってしまうのか、あわせて伺います。","respondent":"染谷子ども家庭支援センター長","answer":"ヤングケアラー支援におきましての相談にかかる費用のお問合せですけれども、現在想定しておりますＳＮＳの相談窓口、それから、コーディネーターの配置を行う部分の経費としまして、１,２６０万円程度を、現在、提案をさせていただいているところです。","id":"exchange-023"},{"speaker":"松永委員","kind":"質問","question":"ぜひそうした無料相談ができるようにお願いしたいと思います。そこで、このヤングケアラーについてですが、基準について伺います。プレス発表では、小学校６年生、中学校２年生と例が挙げられております。区として、この年齢についてどうなっているのでしょうか。高校生につきましては、義務教育の学校でないので、例えば、高校を中退された方などは対象に含まれるのでしょうか、あわせて伺います。","respondent":"染谷子ども家庭支援センター長","answer":"来年度におきましては、お子さんご本人向けのアンケート調査を実施していきたいと考えておりますけれども、その調査対象をおおむね小学校の中学年から、上は高校３年生ぐらいまでと想定しておりますので、年齢が上がるにつれて、ケアの内容ですとか。","id":"exchange-024"},{"speaker":"松永委員","kind":"質問・要望","question":"ぜひよろしくお願いいたします。こうした方に対しても、相談できる環境が必要と考えます。そのためには、周知が必要だと考えております。誰一人見逃さない気持ちが大切であると考えますので、そのための、例えば教育委員会、民生委員、地区委員会、町会・自治会など、掲示板等も含めて、ポスターで周知をしていただきたいと思うのですが、いかがでしょうか。","respondent":"染谷子ども家庭支援センター長","answer":"来年度におきましても、周知用のリーフレットの作成などを行っていきたいと考えておりますので、掲示板の活用を含め、広く地域の方に認知いただけるように、周知啓発に努めてまいります。","id":"exchange-025"},{"speaker":"松永委員","kind":"質問・要望","question":"１０１ページの無電柱化推進計画事業の補助金について伺います。このたび無電柱化を行うに当たり、地域住民への周知はしっかりとされているかとは思うのですけれども、どのような形で地域住民に周知をされているのでしょうか。その際、区の対応についてお伺いしたいと思います。今後、地域住民に対し、こうした業者が突然来ないように対策をとっていただきたいのですが、いかがでしょうか。","respondent":"森道路課長","answer":"無電柱化推進事業の周知についてですけれども、当然、事業を始める前に、今回も文庫の森から補助２６号線にかけてについては説明会をさせていただきました。","id":"exchange-026"},{"speaker":"江野下委員","kind":"質問","question":"私からは、１２５ページのひきこもり支援推進体制立ち上げ支援補助金についてお伺いします。調査した文部科学省は、コロナ禍による環境変化が子どもに大きな影響を及ぼしたことが伺えるとしています。これは、立ち上げ支援補助金とあるのと、８２５万円と、予算的にも、ひきこもり支援のための新たな施設を立ち上げるものではないとは思いますが、新たな事業を立ち上げるものなのでしょうか。","respondent":"廣田子ども育成課長","answer":"こちらの補助金につきましては、東京都が、令和４年度より、各市区町村等にひきこもりの地域支援センターという機能の開設を目指すというところで、令和４年からできた補助金となっています。","id":"exchange-027"},{"speaker":"江野下委員","kind":"確認","question":"機能強化と重症事例が増えているのですね。確認がとれました。ひきこもりとは、厚生労働省の定義などを参考にすると、自宅にひきこもって学校や仕事に行かずに、家族以外との親密な対人関係がない状態が６か月以上続いている状態を差します。区内のひきこもり人数の把握、また、年齢層や状況などをどの程度把握されておりますでしょうか、お聞かせください。","respondent":"廣田子ども育成課長","answer":"そのようなところなのですけれども、現在、区としては、ひきこもりという定義に当てはまる子ばかりを支援しているわけではございませんで、生きづらさを持っている人たちが、フリースペース等、エールしながわ等に相談に来ておりまして、年齢層的には。","id":"exchange-028"},{"speaker":"江野下委員","kind":"質問","question":"今、幅広い年齢層だというふうに伺いましたが、４０代という、私も５０代でありますが、以前ですと、ひきこもりはやはり若年層であったり、不登校児のイメージがあったと思いますが、当事者が徐々に高齢化して、近年は５０代以上の高齢者のひきこもりも多くなったと伺います。そこで、ひきこもり支援についての現状、また、取組の成果や今後の目標、方向性等のお考えをお聞かせください。","respondent":"廣田子ども育成課長","answer":"子ども・若者計画、当初立てて、平成３０年から取組を強化しているのですけれども、当初は、居場所をつくって社会体験をして就労につなげて自立を促すところを目標にしてきたのですけれども、この五、六年、取り組んできた中では。","id":"exchange-029"},{"speaker":"江野下委員","kind":"質問・要望","question":"今、本当に多様性といいますか、その人その人でゴールが違うということを伺い、現状がどんどん変わっていくのだなというふうに感じました。これからも、子ども・若者、そしてまた、その子どもたちが年をとっても前向きに生きていけるように、充実した支援を要望して質問を終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"田中委員","kind":"質問・要望","question":"１２１ページ、ネウボラネットワーク経費に関連して、おむつ等宅配事業と、１２５ページ、地域自殺対策強化交付金に関連して、子どもの権利擁護についても伺います。最初は、おむつ等宅配について伺います。すみません、もしかしたら代表質問等でもあったかもしれないけれども確認をさせてください。新規事業開始に向けても、やはり保健センターの人員を増やすべきだと考えますが、区の見解を伺います。","respondent":"柏木品川保健センター所長","answer":"体制と人員の確保についても、現在、検討をしています。","id":"exchange-031"},{"speaker":"田中委員","kind":"質問・要望","question":"明るい方、子育てに前向きになっている方はいいのですけれども、そうでなくて本当に落ち込んでいる方をキャッチできる、そういった専門性が求められるので、ぜひそういう専門性のある方をきちんと配置していただきたいと思います。保健センターの増員は、ぜひ増やすべきだと強く求めたいと思います。特に、子どもの自死を食い止めるためには、区はどこに焦点を当て施策につなげていくのか伺いたいと思います。","respondent":"坂野保健予防課長","answer":"どこに焦点を当てた対策、施策かというところかと思うのですが、いろいろな要素があるのかと思うのですが、若年者からテキストベースでの相談を受けた際には、ほかにどういうところとつながっているか、頼れる大人がその辺にいるのか、医療機関にはアクセスがあるのか。","id":"exchange-032"},{"speaker":"田中委員","kind":"質問・要望","question":"待ったなしに進めるべきだと考えますが、現在、他自治体の事例から、どのような事例を学んで区として反映されるのか、検討状況を伺いたいのと、また、子どもに関わる団体を、今こそ子どもアドボカシー、アドボケイトの必要性を求めていますが、進捗状況等を伺いたいと思います。そして、具体的に子ども意見表明支援員の配置を何人程度で予定されているのか伺います。","respondent":"長谷川児童相談所移管担当課長","answer":"中でも子どもアドボケイトの仕組みに関しましては、導入に向けて検討しています。その中で、意見表明支援事業をつくっていくわけになりますが、ここをどういった方に担っていただくかということを含めて、今現在、検討しています。","id":"exchange-033"},{"speaker":"田中委員","kind":"質問・要望","question":"しても検討ということで、非常に残念です。次の保育の質の確保について伺います。今年１月の契約情報に、保育所等の質の確保・向上のための巡回支援事業委託があり確認しました。生活者ネットワークは、これまで保育の質確保・向上に向けた１つとして、品川区独自の保育士配置基準を設けることを求めてきました。質問をします。この事業の報告、公表については、どのように契約時に求めているのか伺います。","respondent":"立木保育課長","answer":"対象の施設になりますけれども、これは認可保育園と私立認可保育園、それから、認可外保育施設ということになっておりまして、１５０施設ほどを年２回回りますので、約３００回ほどの予定ということで、今、考えているところです。","id":"exchange-034"},{"speaker":"田中委員","kind":"質問・要望","question":"公表についても伺ったのでお答えください。私立幼稚園も含まれるということで、よかったなと思います。ただ、本当に今、保育の質というか、園児の置き去り事案は毎年ゼロになっていない状況があるので、ぜひ品川区として、品川区独自の配置基準を求めていただきたいと強く求めます。ぜひ質の確保の取組を積極的に公表、報告をしてほしいと考えますが、いかがでしょうか。伺います。","respondent":"立木保育課長","answer":"職員、質の向上という部分に関しまして、のびしなプロフェッショナルスクール、これは公立の職員だけでなく、私立の職員に対しても研修の機会をご用意させてもらっているなどとしておりまして。","id":"exchange-035"},{"speaker":"田中委員","kind":"質問・要望","question":"件数ではなくて、具体的な事故の内容だったりとか、ヒヤリハット、事故の前にヒヤッとしたことの事例とかを、ぜひ公表していただきたいと思います。区としての配置基準はぜひ設けてください。強く要望したいと思います。保育園は命を預かる現場だということをぜひ強く思っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"須貝委員","kind":"確認","question":"今、このような状況に追われていると思うのですが、それぞれの所管にお聞きしたいと思うのですが、根本的な解決策は、それぞれの所管でどのように考えているのでしょうか。そのようなことではないのではないのですか。それぞれの所管にお聞きしますが、根本的な解決策、現場を見ていて、どのようにお感じなのですか。どのように対策をすればいいとお思いなのですか、お聞かせください。","respondent":"初貝保育教育運営担当課長、染谷子ども家庭支援センター長、飛田子育て応援課長、菅野高齢者福祉課長、矢部教育総合支援センター長、松山障害者支援課長","answer":"こちらは、園児の方が病気の急性期にあって集団保育が困難な場合に、一時的に保育園併設の病児保育でありましたり。ヤングケアラーの支援につきましては、児童福祉の分野だけでなく、ケアの対象となる介護ですとか医療、それから保健の分野。ひとり親家庭の支援としましては、児童育成手当を受給している世帯、また、それに準ずる世帯に、義務教育修了前の児童やその親などが一時的な病気等。そういった老老介護や、介護があるから離職する、そういった状況の方を。","id":"exchange-037"},{"speaker":"須貝委員","kind":"質問・要望","question":"これ、急に入れるのですか。すぐ入れる施設があるのですか。だって、もう困ってしまっているではないですか。私は、どのような対策があるのですかとお聞きしました。私が病院へ行かなければいけないときにどうするのですか。だって、そのときに間に合わなかったら、行動はみんな止まってしまうではないですか。それは当たり前のことかもしれないけれども、現実、そういう状況にあるのではないですか。","respondent":"初貝保育教育運営担当課長、菅野高齢者福祉課長、中元保育支援課長、松山障害者支援課長","answer":"先ほどご説明させていただきましたけれども、区では、病児保育をやっております。個人の方の意思も尊重しなければいけないところもありますので、急なお預かりは難しい部分もあるのかなとは思いますが、日頃から相談等に応じて。午後１０時以降、午前７時までも上限３,５００円の補助制度を用意しています。本人の状況等、健康状況、パニック等の状況、あるいは施設の受入れ態勢等も加味しながら、可能な限り受入れを行っているところです。","id":"exchange-038"},{"speaker":"須貝委員","kind":"質問","question":"本当にやはり急な場合は無理なのです。そこで少しお聞きします。今の事業部もそうですが、保育課、障害者支援課、高齢者福祉課もそうですが、煩雑な書類はたくさんあるのではないですか。こういうものをそろそろ導入していかないと、煩雑な事務関係がパンクしてしまうのではないですか。その辺について、区として、また、各事業部としてどのように思っているのか、お考えをお聞かせください。","respondent":"宮澤情報推進課長","answer":"ただ、ＤＸ推進基本方針においても、デジタル技術を活用して区民の利便性や業務の効率化を図るとしておりますので、今後、先端技術の動向には注視していきたいと考えております。","id":"exchange-039"},{"speaker":"須貝委員","kind":"質問・要望","question":"今、このチャットＧＰＴは、産業革命やインターネットに匹敵する、それだけの技術だそうです。ぜひ、こういういいものは、どんどん採用していただいて、そして、区の職員も少し仕事量を減らせるように、なおかつ、円滑に様々な事業が進められるように対応していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"せらく委員","kind":"質問","question":"７５ページ、自転車駐車場使用料、５２ページ、特別区たばこ税について質問します。自転車駐車場使用料では、駐輪場についてです。１１２台の収容と戸越の地域では台数も多い駐輪場だったので、駅利用者は不便に思わないか、また、商店街の中ですので、道幅も狭いところに駐輪が増えてしまわないか、心配な声も届いておりますが、状況と、新たな駐輪場整備などの計画はいかがでしょうか。","respondent":"工藤交通安全担当課長","answer":"現在の区営駐輪場の利用状況については、おおむね９０％台ということで、収容範囲内ということですので、引き続き、現在の駐輪場については、現状のままやっていきたいと考えております。","id":"exchange-041"},{"speaker":"せらく委員","kind":"提案","question":"収容台数について間違いがありました。１１４台ということで、ご訂正ありがとうございました。放置自転車対策として、前回ご提案した子どもたちが描いた絵の設置については、劣化してしまうと景観悪化になるというご答弁をいただいておりましたので、視点を変えて、１つ提案させていただきたいと思います。先日、大阪に行く機会があり、まちの様子を見てきました。こういった形など、いかがでしょうか。","respondent":"工藤交通安全担当課長","answer":"そちらもまだ空きがあるところですので、まずはそちらの駐輪場への案内、指導啓発の中での案内をしていきたいと思います。歩道への駐輪の可否については、その状況を見ながら、今後、検討してまいりたいと考えています。","id":"exchange-042"},{"speaker":"せらく委員","kind":"質問","question":"歩道への駐輪を禁止せずに、止めてください、駐輪料金をいただきますという形で、禁止看板が置いてある印象が大阪にはなかったので、きれいに禁止看板が並んでいて、それをきれいに駐輪できるスペースへ転換できたら、景観を守りつつ放置自転車対策ができると思います。この禁止看板、ずっと置いておくわけにはいかないと思いますので、改めてこういった別の視点からということはいかがでしょうか。","respondent":"工藤交通安全担当課長","answer":"大阪の件も、非常にきれいで整理整頓がされている、景観も乱れることがない、おっしゃるとおりだと思います。そちらも当係のほうから問合せをしまして、また、やり方等を確認をしまして、どういったものが品川区にあっているのかも確認をしながら検討してまいりたいと思います。","id":"exchange-043"},{"speaker":"せらく委員","kind":"質問","question":"喫煙関係で質問します。喫煙者と非喫煙者、子どもを守るためにも、しっかり分煙できて、受動喫煙のないまちにしたいと考えています。看板を受け取った際に、ご自身の敷地内へ設置してくださいということで、なかなか捨てられるポイントと違ってくるのではないかと悩まれておられました。当区でも、路地のそういった投げ捨ての多いポイントに貼ってもらえたら効果的だと思うのですが、いかがでしょうか。","respondent":"森田生活安全担当課長","answer":"どうしても貼れない場所につきましては、ご自宅のほうに掲げられる看板についてもご提供させていただいているところです。","id":"exchange-044"},{"speaker":"せらく委員","kind":"質問","question":"路地裏の路地のポイントに投げ捨て禁止のシールを貼ってはいかがと、港区ではそうされているので、品川区でもいかがですかという質問だったのですが、そちらはまた後ほどお願いします。喫煙に関しては、見回りも行っていて、投げ捨てや吸い殻の清掃もしていただいていますが、看板の配布以外でも、投げ捨てに関するご相談があった場合、見回りの強化などはしっかり対応されていますでしょうか、伺います。","respondent":"森田生活安全担当課長","answer":"先ほどの答弁と少し重なるところもありますが、私どもで相談を受けた際には、現場に行きまして、まずは状況がどのようなことになっているのかを把握した上で、表示であるとか、または、パトロールの強化であるとか。","id":"exchange-045"},{"speaker":"せらく委員","kind":"質問・要望","question":"分かりました。子育て中の方からは、商店街といった多く人が集まるエリア、歩いているだけで煙たくなってしまうので、ベビーカーで赤ちゃんを連れて通る際に、駆け足で通り抜けないといけない。喫煙者や灰皿設置者に向けた配慮義務の周知も引き続きしていただきたいと思うのですが、その灰皿設置者に向けた配慮については、どのように指導はされていますでしょうか。","respondent":"森田生活安全担当課長","answer":"路上に灰皿を置く場合につきましては、これはどちらかといいますと、道路の設置になりますので、道路の禁止行為になるところから、これは警察とも相談をしながら進めていくべきものではないかと考えています。","id":"exchange-046"},{"speaker":"小芝委員","kind":"質問・要望","question":"私からは、５０ページの特別区民税について、また、５２ページの特別区たばこ税について伺います。５０ページの特別区民税について伺います。一方で、その区民の血税をいかに区民の暮らしの向上に還元できるか、それが求められるのではないかと考えます。その意味では、行政の気づきが必要になると考えます。品川区として、特別区民税の税収アップをどのように評価、捉えておられるのか教えてください。","respondent":"黒田財政課長","answer":"補正予算のときにもご答弁申し上げましたが、税収アップの要因といたしまして、個人の所得の収入が増えているのではないかというところもありますので、そういった意味では、景気が回復してきて経済活動が活発になってきますと、そういったところで企業の収益も上がりまして。","id":"exchange-047"},{"speaker":"小芝委員","kind":"質問","question":"その税収アップを分析するに当たりまして、その参考になるものとしては、１月２３日の総務委員会で資料として出されていました２５回目の世論調査があります。アンケートの結果、このまま品川区に住み続けたいと考える人が回答者の９割を超えるということは、品川区の行政は一定程度評価されていると認識をいたしますが、その辺り、世論調査のアンケートに対して、区はどのようにお考えか、教えてください。","respondent":"佐藤企画調整課長","answer":"人口減少になりますと、逆に様々な影響が出ますので、区といたしましては、住民の方々に対して住民福祉を向上させることは使命ですので、そういった面も含めまして、引き続き多くの区民の方に住んでいただけるように全力で施策を展開してまいりたいと考えています。","id":"exchange-048"},{"speaker":"小芝委員","kind":"質問・要望","question":"一方で、転入も増えてきております。であるならば、今後さらに品川区の人口増を目指すならば、交通の利便性をさらに追求していくべきだと私は考えております。リピーターになるかもしれない可能性を秘めていると考えておりますが、交通利便性、この先にあるものをどのように品川区は考えておられるのか、ご見解をお聞かせいただきたいと思います。","respondent":"鈴木都市計画課長","answer":"さらには、今現在、検討を行っておりますが、羽田アクセス新線に関わる新駅の設置の要望の可能性の検討なども行っております。やはり品川区にとっては非常に重要な都市基盤、地域公共交通の充実について、今後もしっかりと検討を行っていきたいです。","id":"exchange-049"},{"speaker":"小芝委員","kind":"質問・要望","question":"課長から、大変心強い、力強い答弁をいただきました。ありがとうございました。私は常々思っておりますが、この３０億円を受動喫煙や副流煙で不快な思いをされてきた区民、健康を害されてきた区民のためにも分煙を徹底すること、コンテナ型喫煙所の整備拡大を進めるべきであるとの立場に立ちまして、質問をします。西口に喫煙所を整備することになりましたその経緯について教えていただきたいと思います。","respondent":"森田生活安全担当課長","answer":"大崎駅西口バスターミナル内の喫煙所についてのご質問です。当喫煙所につきましては、煙の漏れなどもございまして、また、喫煙所に隣接する歩道に喫煙者が出るなどのこともございまして、この改善のために取組をさせていただいたところです。","id":"exchange-050"},{"speaker":"小芝委員","kind":"質問・要望","question":"今、１つのコンテナ型喫煙所を設置すると、その経費は大体３,０００万円を切ると認識しております。は路上禁止エリア、先ほど大崎が出ましたけれども、ほかの武蔵小山だとか、大井町、青物横丁、五反田に、それぞれコンテナ型喫煙所を設置していただきたい、検討すべきと考えますが、ご見解をお願いいたします。","respondent":"森田生活安全担当課長","answer":"このコンテナにつきましては、ある程度の敷地面積が必要でございまして、また、埋設物等々も含めまして、様々な検討が必要です。現状、そういった敷地を確保した上での設置をしないといけませんところから、現在も、個々、場所の選定を図りつつ、今進めているところです。","id":"exchange-051"},{"speaker":"小芝委員","kind":"質問・要望","question":"民間の土地もありますので、ぜひ民間の事業者の協力を得た上で、設備の拡大に向けて取り組んでいただきたいと思います。たばこを不快に思われる方、何も煙だけではありません。道端に落ちています、ポイ捨てされた吸殻も同じく不快に思われます。特に、これはまちの景観を貶めることにもつながります。それがまちの景観を守ることにもつながってくると思いますが、区の見解を教えていただければと思います。","respondent":"森田生活安全担当課長","answer":"この範囲を広めるということにつきましては、現状、こういった取締りなど、指導、取締り、またはマナーアップ等々、こういったものを加味しながらやっていきたいと考えていますので、現状でこれを広げていくというところでの検討は、今のところしていないところです。","id":"exchange-052"},{"speaker":"小芝委員","kind":"質問・要望","question":"今、大分外国の方も日本に来られております。例えば、羽田空港の国際線の到着ロビー、そこには訪日外国人向けに東京観光情報センターが置かれています。そこでは恐らく地図も載っていたかと思いますが、そういった地図にも、ぜひ外国語で喫煙所の位置を明確に分かるようにしていただきたいと思いますが、ご検討いただきたいと思いますが、いかがでしょうか。","respondent":"森田生活安全担当課長","answer":"喫煙所のお話です。現在、ホームページに掲載をしています。様々なご検討もいただきまして、引き続き検討してまいりたいと考えています。","id":"exchange-053"},{"speaker":"横山委員","kind":"質問・要望","question":"私からは、９３ページ、児童虐待・ＤＶ対策等総合支援事業費補助金、１３５ページ、いじめ防止対策事業補助金、１４５ページ、地域振興基金繰入金、時間があれば、１２７ページの商店街活性化推進事業助成金と、１２９ページ、武蔵小山駅周辺地区再開発事業についてお伺いいたします。１点目に、児童虐待・ＤＶ対策等総合支援事業費補助金、いじめ防止対策事業補助金についてお伺いいたします。","respondent":"矢部教育総合支援センター長、長谷川児童相談所移管担当課長、染谷子ども家庭支援センター長、柏木品川保健センター所長","answer":"初めに、学校の対応です。区としましては、児童相談所開設に向けて、ペアレント・トレーニング等の手法を取り入れ。子ども家庭支援センターといたしましては、お子さんの支援のみでなく、保護者の方を含むご家庭全体の支援が役割と認識しておりますので。心理士一人で行うわけではなく、保健センターの保健師等、あとは、関係機関と連携しながら治療等につなげていくものです。","id":"exchange-054"},{"speaker":"横山委員","kind":"質問・要望","question":"いろいろな背景があることを確認していただいたりですとか、準備段階のものもあるかと思います。研究を進めていただいて、ぜひ理解を広めていただけたらと思いますので、よろしくお願いいたします。２点目に、地域振興基金繰入金、協働推進経費についてお伺いいたします。地域活動課では、協働推進を進めていただいているかと思います。","respondent":"川島地域活動課長","answer":"地域活動団体とのコーディネートということで申しますと、まず、伴走型支援ということで、ＮＰＯサポートセンターに、今、月に１回、相談に入っていただいていますが、そういった中で知り合った団体等のコーディネート、団体と団体のコーディネートもありますし。","id":"exchange-055"},{"speaker":"横山委員","kind":"質問","question":"件数だけでも増えておりますし、実感としても、すごく浸透してきているかと思っているのですけれども、今後さらに、来年度以降なのですけれども、例えば支え愛・ほっとステーションのように、各地域ごとに、区民ですとか団体と区をコーディネートする職員を配置していただいて、そうした現在の流れをさらに加速してほしいと考えているのですけれども、協働推進の拠点づくりの見通しについて教えてください。","respondent":"川島地域活動課長","answer":"私どもの所管としましては、例えば新庁舎のほうに、ぜひ協働推進スペースですとか、集いの場のような部分を置けたらいいなということは考えているところですが、まずは今、こみゅにてぃぷらざ八潮に協働推進室はありますが、少し場所が不便ということですので、駅に至近の部分。","id":"exchange-056"},{"speaker":"横山委員","kind":"質問・要望","question":"昨日、子どもたちのマラソン大会、川島参事にも楽しく見守っていただいたという感想をお聞きしたのですけれども、こちらの協働推進、庁内とＮＰＯの協働推進の強化等につきましても、楽しみながらお仕事を進めていただきたいと思っていますが、最後、感想ではなく、一言お願いします。","respondent":"川島地域活動課長","answer":"仕事をしっかり楽しくやっていきたいと思います。","id":"exchange-057"},{"speaker":"あくつ委員","kind":"確認","question":"私からは、１４３ページ、財産貸付収入、地所賃貸料５億３,４８０万８,０００円の中から、「大崎ブライトコア５・６階等」とあるのですけれども、この「等」の中身を調べるために歳入予算見積書を確認しますと、環境学習交流施設地所賃貸料６２万８,８００円と計上されていました。","respondent":"河内環境課長","answer":"こちらの地所賃貸料ですが、飲料用自動販売機の貸付料です。","id":"exchange-058"},{"speaker":"あくつ委員","kind":"質問・要望","question":"簡潔にありがとうございました。さて、このエコルとごしに関連いたしまして、本日は歳入の款なのですが、これまで何回となく求めてまいりましたＳＤＧｓへの積極的な品川区の取組について、まとめて確認をさせていただきたいと思います。そうこうしているうちに目標達成の時期である２０３０年まであと７年を切っています。私ども、令和３年第４回定例会一般質問でこのように要望しました。","respondent":"河内環境課長","answer":"令和５年度につきましては、さらに倍加いたしまして１４講座を展開しつつ、星薬科大学などの新たな大学など、学生連携を進めまして、こういった問題に新たに進んでいくものです。","id":"exchange-059"},{"speaker":"あくつ委員","kind":"質問・要望","question":"もう１つ、以前から国連の規程に基づきましたＳＤＧｓのホイールバッジの作成と着用を求めてまいりました。昨年５月、私ども会派としても、オープンしたばかりのエコルとごしを視察した際には配布はありませんでしたが、このバッジはどういうものであって、どういう基準で配られているのかということ、また、さらなる活用を求めたいと思うのですが、これについてご見解を伺います。","respondent":"河内環境課長","answer":"翻りまして、令和５年度ですが、先ほど申し上げましたＳＤＧｓの参加、関係者につきましても、こういった配布を通じまして一層の意識醸成を図ってまいりたいというふうに考えているところです。","id":"exchange-060"},{"speaker":"あくつ委員","kind":"提案","question":"そして名刺に、部署の代表すべきアイコンを載せれば、区民とか外部の企業に配るときに、自分のお仕事の内容とか、ＳＤＧｓの説明をする話題ともなりますので、一石二鳥、何鳥にもなるのではないかと思うのですが、繰り返しになりますが、ＳＤＧｓ未来都市に挑戦をされると、内閣府の公募をされるということなのですけれども、こういったこともぜひ検討していただきたいと思いますが。","respondent":"佐藤計画担当課長","answer":"そうした中で、委員にただいまご指摘いただきました名刺へのロゴの印刷ですとか、先ほどご指摘いただきましたホイールバッジですとか、様々なＰＲの手段が考えられると思いますので、検討しつつ取り組んでいきたいというふうに考えております。","id":"exchange-061"},{"speaker":"あくつ委員","kind":"提案","question":"区長または区幹部のリーダーシップで品川区のＳＤＧｓの取組を早急に区内外に宣言をしてくださいと、このような要望をいたしました。今回、新規事業として、このＳＤＧｓ未来都市に向けた取り組みとして質問で要望したとおり、議会提案から３年を経まして、このＳＤＧｓ未来都市とＳＤＧｓモデル事業への応募をされることが示されました。その辺り、お考えを教えていただければと思います。","respondent":"佐藤計画担当課長","answer":"これに関しましては、区としまして、「経済と環境が両立するＳＤＧｓ しながわ」を目指して、幅広い分野の新しい価値の創出につながる施策を検討するということもありますので、併せてそちらで担当して進めていきたいというふうに考えております。","id":"exchange-062"},{"speaker":"あくつ委員","kind":"質問・要望","question":"この質問で私が何が言いたかったのかというと、ＳＤＧｓに取り組むことは、もう皆さん既に、皆さんというか、区役所全ての課が取り組んでいらっしゃると思うのです。だからもういいのだという、今までそういうご答弁が多かったと思うのですけれども、それを対外的に発信をしていただきたい、強く強く意識を持って発信をしていただきたいという趣旨で質問させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-063"},{"speaker":"おくの委員","kind":"質問・要望","question":"私からは、１４１ページ、非核平和都市品川宣言事業に関わって、ウクライナを侵略したロシアへの品川区の２度目の抗議を求めて質問いたします。昨年の２月、ロシアがウクライナの侵略を開始しましたけれども、直ちに抗議の声が世界に広がり、この品川でも、区議会で抗議する決議が全会一致で議決され、また同日、濱野区長も抗議文を発表いたしました。この現状を区はどのように思われますか、伺います。","respondent":"古巻総務課長","answer":"その後、状況につきましては、報道等であるとおりですけれども、なかなか解決といいましょうか、終結の見込みが立たないような状況ということで、これに対しましては、抗議文にもあるとおり、この侵攻に関しましては、区として憂慮していますので、この状況については。","id":"exchange-064"},{"speaker":"おくの委員","kind":"質問","question":"解決の見込みが立っていない悲惨なことだと、いや、おっしゃるとおりだと思います。森澤区長は、この濱野区長が出した抗議文と同じ立場でしょうか、伺います。","respondent":"古巻総務課長","answer":"区として抗議文を出しておりますし、その立場については、区長が代わっておりますけれども、変わっていないと認識しております。","id":"exchange-065"},{"speaker":"おくの委員","kind":"質問・要望","question":"ロシアのウクライナ侵略開始１年に当たって先日開催された国連総会、２月２３日に、国連憲章の原則の実現実施を求める決議案を、同様に１４１か国の賛成多数で採決いたしました。同じ立場だと言うのなら、非核平和都市品川宣言に基づいた取組として、区長が濱野区長から森澤区長へと代わったのですから、森澤区長自身の同様の抗議文を出すべきではないかと考えるのですけれども、いかがでしょうか、伺います。","respondent":"古巻総務課長","answer":"区長名ということで、代表して当時の濱野健区長のお名前で出していますけれども、区としてということで抗議文を出していますので、そちらは立場は変わらないということで、国連での新たな決議でありますとかもありますけれども、現時点で、特段。","id":"exchange-066"},{"speaker":"おくの委員","kind":"質問","question":"今のご答弁の中にもありましたけれども、確かに区として出しているのですが、濱野区長名で出されている抗議文なわけです。森澤区長、新しく当選されました。区長が代わった以上、公約も別の公約を掲げて当選されているわけです。ということですから、全く区として同じなので、抗議文、しないというわけにはいかないと思うのですけれども、そういう話にはならないと思うのですけれども、いかがでしょうか。","respondent":"古巻総務課長","answer":"抗議文ですけれども、区は引き続きウクライナに関して支援を継続していくということで、今日は歳入のお話ですけれども、ウクライナ支援ということでは、支援金については、引き続き来年度も予算計上していますし、新たにまた携帯翻訳機の貸出し等も始めるというようなことで。","id":"exchange-067"},{"speaker":"おくの委員","kind":"質問・要望","question":"もう１つが、事態の収拾を見通せず、むしろ悪化していることから、区としても抗議する必要が相当であると判断したと区として答弁されております。だからこそ選挙で代わっているわけですから。その点、もう一度お伺いしたいと思います。それでも抗議文を出せないと言うのなら、なぜ抗議文を出せないのか、もう一度明らかにしていただきたいと思いますけれども、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-068"},{"speaker":"おくの委員","kind":"質問・要望","question":"ウクライナの現状、お認めのとおり、非常に深刻です。それを終わらせるためには、世論、それと支えられた政治や外交の動きが繰り返し必要だと思います。抗議文を強く求めて質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"},{"speaker":"西村委員","kind":"質問","question":"１２１ページ、とうきょうママパパ応援事業補助金、産後の家事育児支援から、子育て世帯の現状と男性育休について、時間が許しましたら、９５ページ、１３款国庫支出金、２項国庫補助金、子ども・子育て支援交付金に関して、充当事業のすまいるスクール運営費ほか１３事業の中に私立保育園の一時預かり事業が含まれていると伺っておりますので、関連して伺ってまいります。","respondent":"染谷子ども家庭支援センター長","answer":"令和５年度、来年度につきましては、これまでは出産をした方ということで、母親、お母さんからの申請のみをお受けしておりましたけれども、男性の育児休業取得を支援するという観点からも、お母さんに限らず。","id":"exchange-070"},{"speaker":"西村委員","kind":"確認","question":"そこで、区役所内の男性育休取得率について伺います。？」というテーマの講義を受けました。区役所内でも、昨年４月から、男性職員に子どもが生まれた場合には、必ず育休意向確認を実施していると伺っています。今、職員の男性育休取得率はどのくらいでしょうか。昨年１０月から育休を分割して取得できるようになっていると思いますが、どのような庁内の事例があるかお聞かせください。","respondent":"崎村人事課長","answer":"今、委員ご紹介ありましたように、昨年の４月に育児休業制度の改正、また、１０月にも育休が分割取得できるですとか、男性の産後パパ育休といった制度も開始になったことから、その機会を捉えて、職員に対して周知を行ったりですとか、区の職員報などで。","id":"exchange-071"},{"speaker":"西村委員","kind":"意見","question":"区職員の育休取得率の高さに驚きますけれども、やはり上司の後押し、職場の後押しがあるからこそ普及が進んでいると感じます。職員の皆様の働き方の改革の推進と、まずは足元から子育てとの両立を目指す取組を引き続きお願いしたいと思います。区内企業に対する啓発や取組で、現在、実施していることがあればお聞かせください。","respondent":"遠藤商業・ものづくり課長","answer":"区内の中小企業に対する育休等の支援ですけれども、区内では、働き方改革推進事業ということで、セミナーの開催や、あるいは、働き方改革の推進の取組、それから働き方への対応のために。","id":"exchange-072"},{"speaker":"西村委員","kind":"質問・要望","question":"品川区は様々力を入れて創業支援をしておりますので、例えば、書類を作るときに、男性、女性関わらず、育休取得をルール化した企業には融資の利率を下げるですとか、そういった創業時からルールをつくるように促し、結果的に民間経済が回るような取組もぜひともご検討いただきたいと思います。次に、品川区の子育て世帯の現状について伺います。現在の品川区の子育て世帯の現状はいかがでしょうか、伺います。","respondent":"廣田子ども育成課長","answer":"児童センター等で行います事業につきましても、父親の参加率が大変上がっておりまして、親育ちのワークショップ等で父親の親育ちの事業等もやっておりますが、かなり参加率が増えていると認識しています。","id":"exchange-073"},{"speaker":"西村委員","kind":"質問・要望","question":"そもそもなぜ父親に育休をとってほしいのかという、何のためにというメッセージを届けていくことが必要だと思いまして、お伺いさせていただきました。次に、親子健康手帳の改訂と父親学級について伺います。品川区は、母子手帳から親子健康手帳に変わりましたが、さらに父親に向けた記載の改訂などは検討されているでしょうか。パパ向けやパートナーシップ講座など、現在どのような講座があるか伺います。","respondent":"若生健康課長、柏木品川保健センター所長","answer":"この改正を受けまして、来年度、親子健康手帳、品川区のほうにもそちらを反映していけるように、現在、検討を進めているところです。父親学級の中では、実技、講義、あと、個人ワークといいまして、時間配分等も含めて自分でその後の育児等を考える、そういうことで父親向けの教室を実施しております。","id":"exchange-074"},{"speaker":"西村委員","kind":"提案","question":"北欧は女性の就業率が８割から９割なのですけれども、父親が夕方に帰ってくるため、家事・育児を大半の家庭で分担していると伺っております。次に、未就園児の定期的預かりモデル事業について伺いますが、こちらもそういった母親、父親の働き方につながっていく、支援する取組ではないかと考えています。モデル事業を実施するに当たり、実施する園について、どのように決めていかれるでしょうか。","respondent":"中元保育支援課長","answer":"区内の私立保育園事業者に案内したところ、７事業者の応募がありましたが、今後、提案内容などを加味した上で実施する保育園を選定する予定です。そのほか対象年齢ごとの受入枠等につきましては、選定した園と調整させていただきたいと考えています。","id":"exchange-075"},{"speaker":"せお委員","kind":"提案","question":"私からは、１４４ページ、ふるさと納税寄附金、１３７ページ、特別支援教育推進補助金についてお伺いします。ふるさと納税に関しては、私も以前から、そしてほかの委員も提案などをしていますが、区長も代わりましたので、改めて提案します。昨年から増額しています見込み、どういった理由か教えてください。","respondent":"提坂税務課長","answer":"令和３年度、令和４年度については、やはりコロナ禍の影響を踏まえまして、実績がやや伸び悩んでいる部分があると。令和５年度につきましては、コロナも５類へ移行するということも踏まえまして、かなり期待的な観測もあるのですけれども、金額を増額させていただいた次第です。","id":"exchange-076"},{"speaker":"せお委員","kind":"質問・要望","question":"続けてですが、報道によると、世田谷区が、制度に問題提起するため返礼品競争には加わらないとしていた従来の方針を転換して、今年度、約１００点の返礼品を追加して寄附額を増加させているということでした。ただ、私は以前から申しております。そこで、品川区のホームページには、「返礼品競争に加担せず」と書かれていますが、そこの考え方だけ教えてください。","respondent":"提坂税務課長","answer":"返礼品としましては、物よりも事ということで開発を進めております。今後も新しい体験型の返礼品の開発を進めていきたいと考えているところです。","id":"exchange-077"},{"speaker":"せお委員","kind":"質問・要望","question":"そういった時代に合った、先ほどおっしゃっていたいわゆる体験型返礼品を積極的に準備していくこと、そこの点について見解をお聞かせいただきたいのと、そして、返礼品ではなくて、子どもの未来応援プロジェクトのような使い道のところに賛同していただけるようなプロジェクトを増やしていただきたいです。そして、返礼品の検討に関しても、所管は税務課なのでしょうかと、少し疑問です。","respondent":"提坂税務課長","answer":"プロジェクトというお話がありましたけれど、それはそれぞれの所管課で、区民の皆様からいろいろな行政要望とかも寄せられていると思いますので、それに賛同していただけるようなプロジェクトを立ち上げてやっていただくということを全庁的に取り組んでいきたいと思いますので。","id":"exchange-078"},{"speaker":"せお委員","kind":"質問・要望","question":"もちろん補助していただけるのは大変ありがたいですし、教育支援員は、支援員ですから、学校全体を見ることも可能だと思うので、こちらも配置していただけることは大変ありがたいことです。この特別支援教育推進補助金は、どのような補助金なのか教えていただきたいのと、さらに、なぜ東京都は原則１年としたのか、ご存じでしたら教えてください。","respondent":"矢部教育総合支援センター長","answer":"特別支援教室のガイドラインが改訂された１つの大きな理由は、基本的に、小学生だったら１年生から入室すれば、徐々に指導していって６年生まで使えるようなシステムでございましたが、やはりきちんと１年間で、ある程度の目標を決めて。","id":"exchange-079"},{"speaker":"せお委員","kind":"質問・要望","question":"以前から議論もありますけれども、本当にお声をいただくのは、１年で戻って大丈夫なのかというところをやはりご家族の方がかなり不安になっているというお声はたくさんありますので、そこの支援をしっかりしていただきたいということと、発達障害のお子さんに関しては、支援教室に通われる方が多いのですけれども、そこも週１回だったりするので、そういった支援教室のあり方みたいなものも。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-080"},{"speaker":"こんの委員","kind":"確認","question":"私からは、１０３ページ、空き家等対策事業、１２５ページ、地域自殺対策強化交付金、１４３ページ、不用品売払代金、この３点をお伺いしたいと思います。空き家等対策事業と、それから地域自殺対策強化交付金、この２点について、簡単に事業概要を確認させてください。","respondent":"竹田住宅課長、つる委員長、坂野保健予防課長","answer":"品川区内には、区で把握しておりますのは約１００近い管理不全の建物があると認識しております。所管の担当の課長はいらっしゃいますか。自殺の対策のことについて概要を説明してください。自死遺族の支援機能、これは割と新しい事業なのですが、２か月に１回やっている自死遺族の方に集まっていただいて交流するという会。","id":"exchange-081"},{"speaker":"こんの委員","kind":"質問・要望","question":"品川区の現状が分かれば教えていただきたいのですけれども、また、現状を踏まえて、現状に対する対策、品川区の今の対策は、このままでよいのか、それとも、もっと必要なのか、その辺のお考えをお聞かせいただきたいと思います。さらなる対策を考えることも必要だと私は思っているのですけれども、今後の品川区の自殺防止対策の方向性についてお伺いしたいと思います。それぞれお願いします。","respondent":"竹田住宅課長、坂野保健予防課長","answer":"今後、与えられた権限を最大限に使って、空き家対策を進めていきたいと考えております。若年層の場合は、電話とか対面でのアプローチが非常にアクセスがよくないということで、これは検索エンジンでそれっぽい単語が入ったら誘導するというスキームですが、こちらは民間のＮＰＯに委託をしてお願いしていますが。","id":"exchange-082"},{"speaker":"こんの委員","kind":"質問・要望","question":"要望で終わります。地域だけでは対応が困難なケースに専門家が伴走支援する仕組みを構築するとしております。こうした情報は捉えていらっしゃいましたでしょうか。こうした品川区のさらなる強化というところでのお気持ち、お考え、少し厳しい言い方ですけれども、足りないな、薄いな、そういう感じがいたしました。そこら辺のところはどう考えでしょうか。","respondent":"坂野保健予防課長","answer":"地域特性重点特化事業ですが、これは新しいスキームでございまして、今、品川区で活用しているいろいろな事業があるのですけれども、それらのうち、委員のほうからお話があったのですが、自治体において課題の分析、事業の効果等の検証。","id":"exchange-083"},{"speaker":"こんの委員","kind":"質問・要望","question":"そうなると、今のご答弁だけ聞いても、本当に自殺対策をされていこうというお考えでしていらっしゃるのかというのは、大変に残念でなりません。これは実際にもう金額が提示されているわけですけれども、この不用品というのは、いわゆる見通しのついている不用品があるといったことなのでしょうか。どのようなものが不用品として売り払われているのでしょうか。参考までに伺いたいと思います。","respondent":"品川品川区清掃事務所長、坂野保健予防課長","answer":"清掃車、一定の年数が経った清掃車を売却する金額、それから、昨年の１０月から始めています粗大ごみのリユース事業、これで一部有料のものがあります。こういったものの歳入を計上しているものです。今、非常に厳しいお話であったわけなので、できるだけ前向きというか、積極的に、一歩前というのはなかなかあれで、半歩でも前にということでお答えしたいと思います。","id":"exchange-084"},{"speaker":"芹澤委員","kind":"質問・要望","question":"私からは、１４４ページのふるさと納税寄附金、先ほど出てまいりましたが、その話と、時間があれば、１０９ページの障害者自立支援給付費についてお伺いしていきます。ふるさと納税の区のスタンスをもう一度確認していきますが、これまでと同様に、特別区長会を通じて、不合理な税制度の抜本的な改善を見直していくことを求めていく。","respondent":"提坂税務課長","answer":"今委員ご指摘のスタンスで変わりないかと思います。","id":"exchange-085"},{"speaker":"芹澤委員","kind":"質問","question":"流出対策というところで、ふるさと納税の反対をしていくというのは、２３区、基本的にはほぼ同じスタンスだと思っています。お伺いしますが、特別区長会として、先ほど来、返礼品競争には基本的に参加しないというようなスタンスだったのだと思いますが、今回、世田谷区のこの一件は、事前に何かお話があったのでしょうか。","respondent":"提坂税務課長","answer":"ふるさと納税に対するスタンスとしては、特別区長会で要望しているとおりなので、品川区としては、淡々とそのスタンスで進めていくということで、ほかの区の状況は特に情報は仕入れてございません。","id":"exchange-086"},{"speaker":"芹澤委員","kind":"提案","question":"当時から、例えば、港区とか、外国人とか、高額納税者の方が近隣にたくさんいらっしゃるので、その方が使っていただけるようなものをつくってはどうですかというようなご提案をさせていただきましたが、当時は、広く浅く検討したいというようなお話だったと思うのですが、今、世田谷区のお話も受けて、ご見解をお聞かせください。","respondent":"提坂税務課長","answer":"返礼品を積極的に展開している区が増えていることも事実ですけれども、２３区中、数区でまだ返礼品の開発を行っていないような区があることも実情です。","id":"exchange-087"},{"speaker":"芹澤委員","kind":"提案","question":"シナモロール云々という話ではないのですが、品川区としては、すごく活用されて、愛をもってシナモロールにお願いをしたいというようなお話をされていた中で、結構私はショックだったのですけれども、この２０２２年当時に神奈川県の中井町の応援大使に着任をされたそうなのですが、そのとき、シナモロールから品川区に対して、兼務になりますというか、そういったご報告はあったのでしょうか。","respondent":"山崎文化スポーツ振興部長","answer":"ただ、例えば、一般企業で企業ＰＲでシナモロールを活用するとか、別の用途については契約を容認するというような内容になっているところですので、区独自の一意のものと、サンリオ、企業が開放する別の用途の領域というようなところで。","id":"exchange-088"},{"speaker":"芹澤委員","kind":"質問","question":"今のご答弁だと、品川区が、ある意味、専任契約に近いのかと思っているのですが、ただ、自治体として、神奈川県中井町の応援大使もされていらっしゃったということで、これは契約違反ということでお考えなのでしょうか。いかがでしょうか。","respondent":"山崎文化スポーツ振興部長","answer":"私どもが企業のほうから聞いているところにつきましては、行政としての契約については品川区としての契約が成立しております関係で、他の自治体と観光大使という内容の中では、品川区と一意の関係にあるというふうに聞いております。","id":"exchange-089"},{"speaker":"芹澤委員","kind":"意見","question":"しながわ」のキャッチも、そろそろ変えてもいいのではないかという思いでありますので、このタイミングでぜひ前向きにご検討していただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-090"},{"speaker":"のだて委員","kind":"質問・要望","question":"私からは、１０３ページの公的賃貸住宅家賃対策調整補助金、１３３ページ、住宅確保要配慮者円滑入居賃貸住宅補助金に関わって、家賃補助と区営住宅増設を求めて質問します。低額所得者や被災者、高齢者、障害者、子育て世帯等の入居を受け入れるセーフティネット住宅への家賃補助を来年度から始めるということですが、これはどういった補助制度なのか。実証する目的を伺います。","respondent":"竹田住宅課長","answer":"登録住宅のほうは、２月１０日現在、品川区内に１,０１５戸ありますが、専用住宅のほうは残念ながら０戸となっております。今回の令和５年度予算では、専用住宅に家賃低廉化補助、家賃補助を導入することをご提案しています。","id":"exchange-091"},{"speaker":"のだて委員","kind":"質問","question":"専用住宅に家賃補助するということですが、これが幾らなのか、誰に給付されるものなのか伺います。","respondent":"竹田住宅課長","answer":"こちらの制度は、貸主の方が入居者の方に対して家賃を下げた分を貸主の方に補助するという制度になってあります。金額としては、最大４万円となっております。","id":"exchange-092"},{"speaker":"のだて委員","kind":"質問","question":"しかし、専用住宅が増えれば、家賃補助を受けられるわけですから、入居者にとってはとても助かりますので、拡充をしてほしいと思います。先ほど、実施をする目的についても伺いましたので、そこを伺いたいと思います。","respondent":"竹田住宅課長","answer":"こちらの制度の目的ですが、住宅確保要配慮者、高齢者、障害者、ひとり親、その他法律で規定されております該当者、あるいは省令等で決まっている該当者の方々の住宅確保を支援していくことが目的です。","id":"exchange-093"},{"speaker":"のだて委員","kind":"質問・要望","question":"目的について、要配慮者の住宅確保をしていくということが目的だということなのですけれども、それをなぜ促進していきたいかということなのです。住まいは生活の基本であり、憲法第２５条に基づく健康で文化的な生活にとっての基盤です。この住まいを保障することが自治体の役割だという立場で進めていただきたいと思いますが、いかがでしょうか。","respondent":"竹田住宅課長","answer":"こちらの制度は国の制度でございまして、全国で都道府県が中心になって行っている制度です。こちらの制度の趣旨を十分活かしまして、品川区としても、住宅の確保に努めていきたいと考えております。","id":"exchange-094"},{"speaker":"のだて委員","kind":"質問","question":"制度を活かしてということなのですけれども、私が聞いたのは、この住まいは生活の基盤だと、人権の基盤だということで、その立場で施策を実施することが重要だと。それがやはり住民が安心して住み続けられる施策になっていくと思いますが、いかがでしょうか。","respondent":"竹田住宅課長","answer":"委員おっしゃるとおり、住宅は生活していく上での基盤です。しっかりと適切な環境でお住まいいただき、品川区に長く住んでいただけるよう支援していきたいと考えています。","id":"exchange-095"},{"speaker":"のだて委員","kind":"質問・要望","question":"このセーフティネット住宅について、今後、専用住宅が登録されていったときに、想定の家賃額はどの程度になるのか。伺いたいのが、生活保護受給者も入れるのかということです。いかがでしょうか。先ほど挙げた人たち以外に、同性カップルも民間住宅に入居することはハードルがあると思いますが、このセーフティネット住宅には同性カップルは入居できるのでしょうか、伺います。","respondent":"竹田住宅課長","answer":"生活保護受給者の方については、登録住宅には入居が可能です。それから、パートナーシップ制度を取得された方につきましては、ご入居いただける制度となっています。","id":"exchange-096"},{"speaker":"のだて委員","kind":"質問","question":"同性カップルについては入居できるということで、それはよかったと思います。それと、生活保護受給者は登録住宅しか入れないということなのですが、専用住宅には、なぜ入れないのか伺います。","respondent":"竹田住宅課長","answer":"専用住宅には、６か月間、併用が可能だというふうになってあります。こちらの制度は、家賃補助も専用住宅には可能です。生活保護の場合は、住宅扶助等もありますので、そういったところの併用を避けるため、こういった制度になったと考えております。","id":"exchange-097"},{"speaker":"のだて委員","kind":"質問・要望","question":"入居後のフォローなども区として支援をしていっていただきたいというふうに思います。このセーフティネット住宅の制度だけでなくて、区独自に、子育て世帯や低所得者、高齢者、若者、単身者など、住宅困窮者への家賃助成を実施することを求めますが、いかがでしょうか。","respondent":"竹田住宅課長","answer":"生活保護の方につきましては、先ほど申し上げた理由から、登録住宅に入居していただくことを考えてあります。それから、ほかの方々への家賃補助ですが、こちらについては研究させていただきたいと考えています。","id":"exchange-098"},{"speaker":"のだて委員","kind":"質問・要望","question":"家賃補助を研究するということですので、ぜひ区としても独自にやっていただきたいと思います。時間がなくなってしまったのですが、パートナーシップ制度、区営住宅のところでも始まりましたけれども、やはり民間アパートではなかなか入りづらいので、そういった意味でも区営住宅を増設していっていただきたいと要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-099"},{"speaker":"木村委員","kind":"質問","question":"私からは、議会費から質問いたしますけれども、議会運営費の中、議員報酬等、令和４年度６億３,４００万円余。そして令和５年度が６億５,３４７万円。この差は、議員数が空白の時期のためにできた差と私は思いますけれども、もう一度、どのようにできた差なのかをお聞かせください。","respondent":"工藤区議会事務局長","answer":"一方、令和５年度は、議員定数どおり４０名分を計上しておりまして、これによる差です。","id":"exchange-100"},{"speaker":"木村委員","kind":"質問","question":"我々の報酬も、令和４年度、そして令和５年度とほぼ同額の予算が組まれているわけですけれども、あまりコロナには関係ないと思いますけれども、コロナ禍以前と比べて、議会費にどのような変化が感じられるのか、それとも変化はないと言えるのでしょうか。お聞かせくだい。","respondent":"工藤区議会事務局長","answer":"毎年度、必要なものを予算措置しておりまして、コロナ禍によって予算を大きく増減したということはございませんが、予算の執行というところでは、行政視察に関わる経費につきましては、コロナ禍によって実施できなかった部分があったです。","id":"exchange-101"},{"speaker":"木村委員","kind":"意見","question":"もし変化があるとすれば、私的には、視察費が増えること。増えることによって行政に変化が生まれる。変化が生まれることで、本区は裕福になり、区民の笑顔があふれるというふうに思っていますけれども、そう簡単にはまいりませんけれども、それが理想だと思っています。行政としては、どのようなことを感じているのか、コロナに対しての感想をお願いいたします。","respondent":"工藤区議会事務局長","answer":"そういった意味では、区政の変化や区民の幸せにつながる大切な議会活動の１つであるというふうに思ってあります。令和４年度は日帰りでの視察を再開したところですが、令和５年度は通常の形で予算どおりに実施できることを願っているものです。","id":"exchange-102"},{"speaker":"木村委員","kind":"意見","question":"区民の生活が少しでも裕福になることを願って、次にまいりたいと思います。次に、区議会だより発行ですけれども、昨年より２５４万円余、増えています。家庭の数や人数が、人口が大きく変わったわけではないと私は思っていますけれども、増えた要因とは、人口増なのか、それとも物価の上昇等などが関係しているのか、お聞かせください。","respondent":"工藤区議会事務局長","answer":"区議会だより発行経費の増の要因についてです。主な要因といたしましては、やはり印刷経費および配布に係る経費の単価が上昇したことによるものです。","id":"exchange-103"},{"speaker":"木村委員","kind":"質問","question":"区議会だよりの発行６回で３,２３９万円余からですけれども、年６回発行されていますが、１回当たり５４０万円弱の費用が充てられています。以前もお聞きしたと思いますけれども、区民の皆さんに対し、購読率を上げるためにはどのような施策を行っているのか。率直に、その策が効果が出ているとお考えでしょうか。それとも、そうではないとお考えでしょうか、お聞かせください。","respondent":"工藤区議会事務局長","answer":"効果ですけれど、直近の区の世論調査、こちらは２０２２年１２月に実施された調査におきましては、区議会情報の入手先というところでは、区議会だよりが約６３％で最も高く、４年前の調査時が５３％でございましたので、約１０ポイントほど大幅に上昇しております。","id":"exchange-104"},{"speaker":"木村委員","kind":"質問・要望","question":"伸びているということで、大変これもほっとしているところでありますけれども、頑張っていただきたいと思います。このほかに議会をもっと知っていただくために、ＣＡＴＶ、そしてホームページ、インターネット映像配信など、議会をもっと身近に感じていただく、もしくは、品川区をよく理解していただくために頑張っていると思いますけれども、苦労は報われているとお思いでしょうか。","respondent":"工藤区議会事務局長","answer":"効果や評価というところだと思います。ケーブルテレビでの番組放映や、インターネットでのライブ配信、映像配信を行っているところですが、やはりこちらは議場に直接傍聴に行くことができない方を補完する上でも重要な情報発信手段です。","id":"exchange-105"},{"speaker":"木村委員","kind":"質問・要望","question":"これは品川区の宣伝にもなりますし、いろいろと、我々４０名の区議会議員のためにもあると思います。ぜひとも皆さんのお力をおかりして頑張っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-106"},{"speaker":"松澤委員","kind":"質問","question":"私からは、１２７ページ、商店街にぎわい創出事業、そして、事業承継支援事業、それと、１４７ページの歩行喫煙防止過料について順不同に質問いたします。防止過料のほうは先ほど少しお話を聞きましたので、１,０００円の過料ということで、この計上が９万６,０００円ということは９６人が違反したことになります。","respondent":"森田生活安全担当課長","answer":"過料の数につきましては、近年の取締件数を参考にしまして算出をさせていただいているところです。","id":"exchange-107"},{"speaker":"松澤委員","kind":"質問","question":"そういった意味で、私のところにもクレームの電話が相当数ございました。国では、５月から新型コロナが２類から季節性インフルエンザなどと同じ５類に移行する方針が決定されました。そうすると、閉鎖と言われていたいろいろな喫煙所、こういったものも再開となるのか教えてください。指定喫煙所、または、庁舎内の喫煙所、公園にある喫煙所、それぞれの今後の計画をお聞かせください。","respondent":"森田生活安全担当課長、高梨公園課長、東野経理課長","answer":"今後の喫煙所の設置ですが、これにつきましては、引き続き検討をしてまいりたいと考えています。５類以降後も、地域の方のご意見を伺いながら、公園の喫煙所のあり方については決めていきたい、このように考えているところです。５類移行後ですが、まだまだ紙巻きたばこ、臭いが気になるというような区民の声もありますので、そういった声を聞きながら対応してまいりたいと思います。","id":"exchange-108"},{"speaker":"松澤委員","kind":"意見","question":"庁舎、紙巻きたばこ、確かに臭いですけれども、紙巻きたばこの方も大分多くて、私もその１人でありますので、何とかいろいろ検討していただけたらと思います。やはり場所によっては、こういったところは有効に活用するべきではないかと思っています。閉鎖して５年近くが経ったと思いますけれども、庁舎内、また、地域センター内の元屋内喫煙所、そういった活用についてご見解をお聞かせください。","respondent":"東野経理課長、川島地域活動課長","answer":"喫煙所、もともと臭いが染みついているような箇所でもありますので、なかなか人が集まって、それから、当然、密閉されたというようなところになりますので、そういったところも加味しながら、運用については。地域センターのほう、６か所、屋内喫煙所があったのですが、そちらは今はほとんど倉庫として使わせていただいております。","id":"exchange-109"},{"speaker":"松澤委員","kind":"質問","question":"次は、商店街にぎわい創出事業と事業承継についてお聞きしたいと思います。例えば、プレミアム付区内共通商品券、今年で２０年目となる事業でありまして、大変好評だとお聞きしております。例えば、このプレミアム商品券、相当な成果があったのではないかと思いますが、効果測定といいますか、区のほうで何か分かっている費用対効果、結果等がありましたら、教えてください。","respondent":"遠藤商業・ものづくり課長","answer":"ご質問の効果測定ですけれども、厳密なものはないのですが、実施後に商店街連合会でアンケートをとっておりまして、例えば、商品券の入手がきっかけとなって購入した金額、あるいは商店街での支払いに追加した金額など、そのようなものから判断いたしますと。","id":"exchange-110"},{"speaker":"松澤委員","kind":"質問","question":"３０％、分かりました。次に、事業承継、ＢＣＰです、事業継続計画についてお聞きします。私、これ、恥ずかしながら、会社経営に関わっていますけれども、防災士講習の中でこのＢＣＰを知りました。区内の事業所に対して、ＢＣＰの取組がどれだけ進んでいるのか、周知方法、計画、また事例の紹介などがありましたら、教えてください。","respondent":"遠藤商業・ものづくり課長","answer":"ＢＣＰですが、２０１１年３月の東日本大震災以降、サプライチェーンがというようなところで注目されたところでございまして、区のほうでもいろいろな形で実施させていただいているところです。","id":"exchange-111"},{"speaker":"松澤委員","kind":"質問","question":"事業承継についてお聞きします。この事業承継の一番の課題、これは経営者が長くトップに立ち続ける。国としても、経営を早く若い人に渡してほしい、チャレンジしないと中小企業は生きていけないと考えています。中小企業の約６割が後継者不足で悩んでいる今、もうからない仕事を継いでほしくないとおっしゃる方も多いのが現状であります。区として、この課題をどう捉えているのか教えてください。","respondent":"遠藤商業・ものづくり課長","answer":"区では、事業承継事業、平成２８年度から実施させていただいておりまして、これまでセミナーや、あるいは専門家の派遣、後継者塾などを中心に実施しています。","id":"exchange-112"},{"speaker":"松澤委員","kind":"質問","question":"経営者の多くは、なかなか生きがいを感じ、そして経営から、トップから下りることに抵抗があります。例えば、先ほどからやじが飛んで、うちの父などもそうです。引退した社長、例えば辞めた社長が、そこの社長をまとめて、「もう俺も辞めたのだから、おまえたちも辞めろよ」と、そういうような交渉というか、会議体というのですか、そういった取組もあるかと思いますが、ご見解をお聞かせください。","respondent":"遠藤商業・ものづくり課長","answer":"事業承継については、産業ニュース等で特集号なども組ませていただいているところですので、今後も様々なツールを用いまして、事業承継の重要性について周知していきたいと考えています。","id":"exchange-113"},{"speaker":"たけうち委員","kind":"質問・要望","question":"１３９ページの無料乗車券発行事務委託金、１６１ページの雑入の公園内自動販売機設置運営事業収入について伺います。初めに、無料乗車券発行事務委託の主な事業内容をお知らせいただきたいと思います。公園のほうは、公園数はどれくらいあって、自販機の数、また、金額など、どれくらいの収入になっているのか教えてください。","respondent":"松山障害者支援課長、飛田子育て応援課長、高梨公園課長","answer":"無料乗車券についての事業内容をお答えいたします。ひとり親家庭につきましても交通費無料パスをやっておりまして、児童扶養手当を受けている世帯の世帯員のうち１人に交付しています。利益分配額として区のほうで歳入をしておりまして、令和５年度予算では９８７万円の利益分配額の歳入を予定しています。","id":"exchange-114"},{"speaker":"たけうち委員","kind":"質問・要望","question":"うれしいことに、この３月１８日から、それが全部フリーになるということになっていますけれども、この辺の状況を、どのような内容なのか教えていただきたいと思います。公園のほうにつきましては、そうすると、約９８０万円で２１台ですから、自販機が１台当たり４７万円ぐらいの利益になっているわけです。","respondent":"松山障害者支援課長、高梨公園課長","answer":"障害者無料乗車券に伴いまして、新たなサービスが展開されるということで、東京都交通局のほうでプレス発表がございました。東京都交通局では、新たにＩＣカードを、障害者用ＰＡＳＭＯ等によるサービスを開始するということです。設置している公園ですが、運動施設があったりとか、また、広い面積で一定滞在時間が長くなるような大きな公園に設置しています。例えばですと、しながわ区民公園や東品川海上公園、戸越公園等に設置しています。","id":"exchange-115"},{"speaker":"たけうち委員","kind":"質問・要望","question":"本当に利便性がよくなるということで、こちらの委託をされて、大体１,０００人を超える方が発行を求められる中で、この方たちは、都営だけでしたら今までとあまり変わらないのですけれども、例えば、ほかの交通機関を使っているようであれば、それと統合することで非常に利便性が高まりますので、恐らく各障害者の団体のほうからもご案内がいっているかもしれませんけれども。","respondent":"松山障害者支援課長、高梨公園課長","answer":"３月１８日から開始されます新たなサービスについての周知についてお答えいたします。自動販売機が設置されている公園と、仮にその事業がかぶった際には、Ｐａｒｋ－ＰＦＩで実施する事業者と飲料の事業者と、区も間にしっかりと立ちながら協議して、取扱いについては決めていきたいと考えています。","id":"exchange-116"},{"speaker":"たけうち委員","kind":"質問・要望","question":"公明党としても、２０１９年１１月に、当時の赤羽国交大臣時代に、障害者の団体の方からご要望をいただいて、その後、様々な省庁に働きをかけて、何とか、関西のほうでは既にできていたわけですけれども、関東のほうではなかなかできなかったところを、風穴を開けてこういう形になったということで、当事者の方からしたら、非常にうれしいニュースになっておりますので。","respondent":"松山障害者支援課長、高梨公園課長","answer":"改札を出る際に、駅員の方に障害者手帳を見せるという行為がなくなるということで、非常に利便性が向上されることになります。今後とも、利便性向上のために、障害者支援課としても積極的に周知を図ってまいります。自動販売機のさらなる設置といったところですが、公園の周辺に設置されているほかの事業者の自販機の設置の状況であるとか、また、公園利用者からの自動販売機が欲しいというようなニーズの声とか。","id":"exchange-117"},{"speaker":"高橋（し）委員","kind":"質問","question":"ページが分からないのですが、小中学校給食費の無償化に係る懸案についてお尋ねします。小学校、中学校、給食の無償化が新年度からスタートし、私費会計制度から公会計制度に移行することになります。品川区においては、過去の給食費未納分が存在するのでしょうか。あるとすれば、何世帯で、金額にしてどれぐらいなのでしょうか。そして、債権の継承はするのでしょうか、しないのでしょうか、お伺いします。","respondent":"勝亦学務課長","answer":"直近３年間で、多くは１０名程度、直近では５世帯程度となってございまして、未納の金額については、直近では１０万円程度、全体の給食費で言いますと０.０１％程度となっています。こちらについては、私費で未納ですので、引き続き、徴収には努めてまいりたいと考えています。","id":"exchange-118"},{"speaker":"高橋（し）委員","kind":"質問","question":"私費なので徴収していくということは、学校で徴収するのですか。","respondent":"勝亦学務課長","answer":"学校のほうから徴収のお願いを引き続きしていくという形になります。","id":"exchange-119"},{"speaker":"高橋（し）委員","kind":"質問","question":"文科省のほうで、学校給食費徴収・管理に関するガイドラインとあって、債権の継承をするためのガイドラインが出ているのですが、それに基づいて、公会計に、私費会計のままでして、債権にならないで、学校のほうでこのままずっと徴収していくというか、督促をしていくのですか。","respondent":"勝亦学務課長","answer":"基本的には、学校のほうで徴収をお願いする形になります。徴収がなかなか果たせない部分につきましては、教育委員会のほうからの督促をかけていくような形を考えてあります。","id":"exchange-120"},{"speaker":"高橋（し）委員","kind":"質問","question":"ということは、給食費の滞納分は私費会計のままで、公会計に入れて、地方自治法による私債権の回収の流れに乗せていかないということでよろしいですか。","respondent":"勝亦学務課長","answer":"給食費の食材費につきましては、引き続き、私費の口座を使ってまいりますので、そのような形で継続してまいります。","id":"exchange-121"},{"speaker":"高橋（し）委員","kind":"確認","question":"公会計に入れないということが、今、説明があったので、それでどうなるかということは、また別の機会にお話を伺いたいと思います。","respondent":"勝亦学務課長","answer":"現状の食材費の口座をそのまま継続していく形で考えてあります。","id":"exchange-122"},{"speaker":"高橋（し）委員","kind":"質問","question":"これはこれで終わります。ほかの機会に伺いたいと思います。小中学校の無償化の根本的なことをお尋ねします。学校教育法第１１条および同法施行令第２条に、給食食材費は保護者負担と規定されていて、このとおりに理解すれば、無償化はあり得ないと考えますが、無償化が可能の考え方と、あるいは文科省の見解があれば教えてください。","respondent":"勝亦学務課長","answer":"ただ、国のほうでも首相答弁の中で、こちらは自治体で独自に費用負担することについては妨げないという見解も示されてありますので、こちらは義務の規定ではございませんので、そういった形で対応しているものです。","id":"exchange-123"},{"speaker":"高橋（し）委員","kind":"確認","question":"そうですね。私は決して給食無償化に反対しているわけではなくて、大変重要な政策だと思っているのですが、その道筋をもう一度確認したくてお尋ねしています。ということは、去年の９月の段階で、そういう解釈をしていれば無償化にできたわけです。ほかの自治体ではやっています。ということで、どうしてそのときにできなかったのでしょうか。","respondent":"勝亦学務課長","answer":"昨年度の段階、基本的には、給食については、人件費ですとか設備費は設置者が負担、食材費については保護者の負担、こういった考え方につきましては、まず基本的な考え方があった部分、こちらについては、戦後、復興期も保護者の方が給食費を負担して給食を支えて。","id":"exchange-124"},{"speaker":"高橋（し）委員","kind":"質問","question":"次です。１４４ページ、減債基金繰入金、約８億２,０００万円についてお尋ねします。充当先が書かれたので、大変分かりやすくなりました。ただ、充当先の公債費を見ると、起債償還元金、利子の合計が約１１億円、ということは、繰入金が充当されていない約２億８,０００万円、これに該当する起債はどのような内容のもので、充当されない理由はどのようなことかお尋ねします。","respondent":"黒田財政課長","answer":"全体の財政フレームの中で、一般財源が幾らあって、その中で国庫ですとか、都ですとか、特別財源を事業で差し引いて、その一般会計の最後の調整として、この減債基金の繰入額等のところでやっておりますので、起債償還元金の中で繰入れていない差額の部分につきましては。","id":"exchange-125"},{"speaker":"高橋（し）委員","kind":"質問","question":"それは充当できない都市計画とか学校関係の建設費でない部分というふうに考えてよろしいですか。財調で手当てをされない部分を一般財源で充てているという考え方でよろしいでしょうか。","respondent":"黒田財政課長","answer":"繰入れの原資の中に財調で、算定で措置された部分もありますので、そういったところの減債基金の補填の積み立てた部分については充てておりますし、それ以外の部分について、繰入分に対して一般財源を充てているといったものです。","id":"exchange-126"},{"speaker":"渡部委員","kind":"質問・要望","question":"どちらにも「止まれ」表示がない。ただ、どういう経緯か分からないけれども、昔は私道にスクールゾーンの溶着をかけていたというのです。でも、そこがその学校にスクールゾーンとして指定をされていて、子どもたち、ないし車も通って、７時半から８時半、規制をかけるのだろうから、地域の人から要望があれば、私はここはどんどんつけるべきだと思うのですけれども、その２点、お答えください。","respondent":"森道路課長、工藤交通安全担当課長","answer":"基本的には、私どもにしても、例えば、多くの方が通られたり、今言われたようなスクールゾーンであったり、通学路指定をされているような公道と同じような扱いをされている私道につきましては、区としても。両方の道路に「止まれ」がないといったご質問にお答えします。こちらは、基本的には、主の道路のほうが優先道路となりますので、従の道路、いわゆる細いほうの道路については「止まれ」の表示があると。","id":"exchange-127"},{"speaker":"渡部委員","kind":"質問・要望","question":"ですから、その地域から要望等があったら、それは丁寧に聞いていただいて、私道だから駄目ですよという対応は違うのではないのかというふうに思いますので、ぜひ地域の声が届いたら、聞いて差し上げていただきたいと思いますので、これでやめておきます。その５年前に聞いた話をもう１回聞くようになるのですけれども、今年いよいよ１,５００万円でしょうか、減りましたよね。手が挙がりましたので。","respondent":"鈴木都市計画課長","answer":"りんかい線の貸付金に対する償還の話ですけれども、貸付金につきましては、平成７年度から平成１４年度まで合計３６億円の貸付けを行っておりまして、それが順次、今、返還されてきているというところで、令和１１年度をもって最終的な返還が全て完了するというような状況です。","id":"exchange-128"},{"speaker":"渡部委員","kind":"質問・要望","question":"やはりそうでしたね。そうなったら何のために出資していたのだという話にもなりかねないので、そこはしっかり、せめて出資したお金は戻ってくるように言い続けていただきたいと思うのですが、その辺で何か情報があったら教えてほしいし、それはしっかりとってくるべきだと思いますので、少しお考えだけ。","respondent":"鈴木都市計画課長","answer":"区のほうからの出資は、平成７年度から平成１０年度あるいは平成１７年度、平成１８年度、合計して、ご指摘のとおり２２億円の出資をしています。","id":"exchange-129"},{"speaker":"渡部委員","kind":"質問・要望","question":"しかない。ふるさと納税にもってこいではないですか。よそではできないですから、そういうものもぜひ少しご研究をされて、これから先、進めていただきたいと思います。森林環境譲与税のところなのですが、活用検討がされるということで、これ、逆を言うと、活用検討すれば、いわゆる基礎自治体、この東京都にも、もっともっと出てくる性質のものなのですかということをまず教えていただきたいのが１点です。","respondent":"黒田財政課長、森道路課長","answer":"森林環境譲与税の譲与額ですが、こちらは、林業従事者の数ですとか、人口ですとか、そういった形で全国の区市町村の譲与額が国で決まっていますので、そういった意味では、活用を検討するから額が増えるということではなくて。申し訳ありませんが、都の補助金の原資として森林環境譲与税が充てられているかどうかということは確認しておりませんけれども、こういった補助金を活用して、区としてもしっかり進めてまいりたいというふうに考えております。","id":"exchange-130"},{"speaker":"渡部委員","kind":"質問","question":"事業も違いますので。環境課でエコルとごしができて、そこにも当然、いろいろなお金が入ってきているのだと思うのだけれども、ぜひ活用検討という形で、額は小さいですけれども、上がっているのであれば、いわゆる子どもたちへの環境教育、自然教育の部分、研究を進めてもらえて、ここから出ている目的税、そのまま使えるような仕組みを考えてほしいと思うのですが、環境課長、いかがでしょうか。","respondent":"河内環境課長","answer":"こういったものの延長線にあるかどうかは別ですが、やはり木材の大切さやＣＯ２の削減につきまして取り組んでまいりたいと考えています。","id":"exchange-131"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私からは、１１７ページの高齢社会対策包括補助金から、補聴器購入費助成について伺います。共産党は、２０１９年６月に一般質問でこれを取り上げてから、８回にわたる購入費助成を求める請願や陳情が出されて、そのたびごとに、この制度を求めてきましたので、今回、第一歩という形で実現をすることになって本当によかったと思っています。この拡大を求めて質問をしたいと思います。その点を１つ伺います。","respondent":"川原高齢者地域支援課長","answer":"現段階に関しましては、補助金の活用をする、申請をする予定で考えてあります。２点目は、本人のみの非課税か、もしくは世帯のみの非課税とするかというご質問です。現時点の検討の段階におきましては、本人の非課税とするというように考えてあります。","id":"exchange-132"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"この点について、共産党の石田区議が代表質問をしています。その代表質問では、１つは、「なぜ所得制限を設けたのか、伺います」と、そしてもう１つは、「所得制限はなくすべきです。いかがでしょうか」と質問をしています。それに対して、住民税非課税の方を対象とすることで、聴覚に障害のある方の補装具等の支給要件に準じているとの答弁でした。これはどういうことなのかご説明ください。","respondent":"川原高齢者地域支援課長","answer":"これを実施する上でまず大事なのが、本来必要な方々に、補聴器がなぜ必要かという、そして使う上で大切なこと、長期装用することが必要だという、そういった普及啓発をまず第一に取り組んでまいりたいというふうに考えてあります。","id":"exchange-133"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"あえて２つの質問に「伺います。いかがでしょうか」とつけたのです。この所得制限をなぜ設けたのかということに対して、やはり答弁がされていなかったわけです。私は、この代表質問に答弁していないことは問題だと思います。改めて、対象をなぜ住民税非課税者だけにしたのか伺いたいと思います。","respondent":"川原高齢者地域支援課長","answer":"他の自治体に関しては、一定の所得要件を設けている、そして多くの自治体が非課税を対象としているという調査を踏まえまして、品川区としても、非課税を要件としたのですが、ただ、品川区で大事なことは、きちんと装用に関して正しい理解を、知識を深めていただく上で。","id":"exchange-134"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"普及啓発のことは質問していませんので、そして、普及啓発のためにもこの補助金をつくることが必要なのだということで、ずっと求めてきましたので、ということは、今の答弁ですと、東京都の補助金をもらうには、住民税非課税者としなければ東京都の補助金は受けられないということなのか、その点も伺いたいと思います。その点、２つお願いします。","respondent":"川原高齢者地域支援課長","answer":"こちらは、まだこれから申請をするところですので、どのような結論を下すかに関しては都が判断するものと認識しています。ただ、私どもで判断している内容としましては、非課税のみを要件としているものではないというふうに考えてあります。","id":"exchange-135"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"先ほどの答弁は、収入であれば６００万円以上ということなので、準ずるというのは当たらないのではないかというふうにお聞きしましたので、その点も伺いたいと思います。子育て世代に選ばれるために所得制限を設けないのに、高齢者には所得制限をつける、これはどういうことなのでしょうか。","respondent":"川原高齢者地域支援課長","answer":"２個目の所得制限の撤廃についてですが、区としましては、様々な情報収集を行った上で、今回の要件を６５歳以上の高齢者、住民税非課税という形で設定をさせていただきました。引き続き情報収集に努めてまいりたいと考えています。","id":"exchange-136"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"だって、地域包括支援センターだって、品川区独自につくらないではないですか、地域に。そして、これだけ子育て支援については、あえて所得制限を設けないで、「選ばれるしながわ」ということを打ち出しているのに、子育て支援に所得制限なしで、高齢者には所得制限をつける、これは矛盾になるのではないかと思うのですけれども、区の姿勢としては、根本的なところでどうなのでしょうか。","respondent":"佐藤企画調整課長","answer":"そういったところで、区長も申しておりますけれども、重点的な政策に財源を振り向けた選択と集中というところでございまして、令和５年度予算に関しましては、少子化対策、３つの無償化に対して財源を振り向けて、それから福祉施策に関しましてもバランスよく実施していくです。","id":"exchange-137"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"少子化だから所得制限を設けないと、では、高齢者は高齢化率が高いから所得制限を設けるというのですか。しかも、この予算は約３５５万円なのです。１７７万円ぐらいになってしまうわけです。高齢者の非課税者は約５割なのです。品川区の財政で、これができないはずないではないですか。３万５,０００円というのは、隣の港区の４分の１ぐらいなのですけれども、どこから出した額なのか、このことも伺います。","respondent":"川原高齢者地域支援課長","answer":"繰り返しの答弁になりますが、私どもも調査を踏まえた上で、他の自治体に関しましては、大体２万円から３万５,０００円の助成額を行っているところも踏まえまして実施をしたことですが、まずはしっかりと必要な方へ支援を行っていきたいと考えています。","id":"exchange-138"},{"speaker":"若林委員","kind":"質問・要望","question":"６３ページのプラネタリウム、歳入から伺います。それからプラネタリウムについては、これはまず実績をお伺いしたいと思います。それから、入場者のうち区民の方と区外からの方の割合が分かれば教えていただきたいと。それから、８６席あるということですが、定員に対する入場者数というか、入場率というか、稼働率、こういった点、分かれば教えていただきたいと思います。","respondent":"黒田財政課長、山崎文化スポーツ振興部長","answer":"予算編成過程の公表の中で、特に「新規」と書いてある事業で、例えば、企画費の中の計画策定経費の政策評価の追加は、これは区長が就任されてから掲げられた公約というところもありますので、そういった意味では。実は、貸出しの方法が２通りありまして、１つが、一般投影ということで、お休みの土・日・祝日に関しまして、１日３回、これは来場者を特定せずに、要は、フリーで入場をしていただくパターンと、それから、通常の月曜日から金曜日。","id":"exchange-139"},{"speaker":"若林委員","kind":"質問・要望","question":"それからプラネタリウムのほうは、時間が、分かりました、傾向性、いずれにしても全国的に見ても、近年プラネタリウムは入場者数が増加傾向、コロナ禍で少し、当然ダウンしたわけですけれども、令和３年度は既に持ち直しているということで、五反田文化センターのプラネタリウムもぜひ頑張っていただきたいという思いで、五反田文化センターのプラネタリウムのと聞きましょうか。","respondent":"山崎文化スポーツ振興部長","answer":"施設が五反田周辺に立地する特性に合わせて、相乗効果を生むような取組というのですか、施設も複合機能がありますので、様々工夫しながら魅力アップにつなげていけるようなことに、区としても様々事業を取り組んでまいります。","id":"exchange-140"},{"speaker":"鈴木（博）委員","kind":"質問","question":"本日は、予算書、５３ページ、森林環境譲与税、地域エコ活動推進事業に関連して、特にチョウに着目した品川の環境活動について質疑してまいりますので、よろしくご答弁をお願いいたします。本日は、委員長のご許可を得て、６枚のスライドを提示します。品川区は、２００８年頃に、「蝶の道プロジェクト」という環境活動が行われました。次は、ゼフィルスです。これに関する区のご見解をお伺いします。","respondent":"河内環境課長","answer":"こうした中ではありますが、自然関係の大切さだとか、あるいは、慈しみの入り口といたしまして、平成生まれのプロジェクトをアップグレートいたしまして、大都会におけます自然環境保全の入り口といいますか、住み続けたいまちや、脱炭素や、環境保全、また。","id":"exchange-141"},{"speaker":"鈴木（博）委員","kind":"質問","question":"この取組を進める上で、品川区立環境学習交流施設「エコルとごし」の活用は非常に有用ではないかと考えますが、現在の展望や構想などはいかがでしょうか。","respondent":"河内環境課長","answer":"現在、いろいろなボランティアの方もご登録いただいておりますので、学生などの連携、活用を含めまして、こういったところとの検討を進めてまいりたいというふうに考えているところです。","id":"exchange-142"},{"speaker":"鈴木（博）委員","kind":"質問","question":"蝶の道品川プロジェクトを、品川区の環境行動計画の中にぜひ取り入れて検討されることを大いに期待しております。品川区の公園にも、このような観点から積極的に里山環境、例えば、クヌギ、コナラ、エノキなどのチョウの食樹を、かつての武蔵野雑木林のように、その１区域にできれば再建することはできないでしょうか。区のご見解をお伺いしたいと思います。","respondent":"高梨公園課長","answer":"公園内の里山環境の再現は、都立公園など広い面積を有する公園が区立公園では少ない中で、実現は簡単ではないと考えておりますが、都会におけるオアシスとして、公園内の自然環境は貴重なものであるとの認識ですので、大規模公園の改修の際には。","id":"exchange-143"},{"speaker":"鈴木（博）委員","kind":"質問","question":"ぜひよろしくお願いしたいと思います。美しいチョウが舞い、美しい花が咲き乱れる魅力あふれる未来の品川が実現することを祈願しまして質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-144"},{"speaker":"松本委員","kind":"質問","question":"私からは、８１ページ、車体ラッピング広告等、関連して、コミュニティバスについて、都市計画課について伺います。５６ページの特別区財政調整交付金についても伺いたいと思います。車体ラッピング広告についてですけれども、ここの車体ラッピング広告というのはどういうものを差すのか、お願いいたします。","respondent":"溝口土木管理課長","answer":"その許可をする際に、手数料を予算計上として上げているものです。","id":"exchange-145"},{"speaker":"松本委員","kind":"質問","question":"これ、ラッピングだけではなくて、コミュニティバスで仮に広告を出した場合、この広告収入については、品川区の歳入としては上がってこないというふうな理解でよろしいのかというところと、あわせて、このコミュニティバス、今、広告が展開されているということであれば、広告の内容、あるいは、どの程度広告収入が、これは東急のほうにはなると思うのですけれども。","respondent":"鈴木都市計画課長","answer":"収入は、９か月で、バス停両方向で、おおむね６万円弱というようなところです。２件ほどの応募があって、お使いいただいている状況です。","id":"exchange-146"},{"speaker":"松本委員","kind":"確認","question":"確認ですが、車体ラッピングも募集自体はされたということでよろしいのでしょうか。","respondent":"鈴木都市計画課長","answer":"ラッピングも含めて、東急バスのほうでは募集をかけているというような状況です。","id":"exchange-147"},{"speaker":"松本委員","kind":"質問","question":"そこでお伺いしたいのですが、今の６万円というのも、これも今、区のほうでも試行の検討といいますか、状況の検討はされているかと思うのですけれども、この６万円というのは、収支率の中に入ってきているのかどうなのか、そこの部分をお願いいたします。","respondent":"鈴木都市計画課長","answer":"広告収入につきましても、運行経費も含めて全体の収支率の中には入ってくるという考えです。","id":"exchange-148"},{"speaker":"松本委員","kind":"質問・要望","question":"車体ラッピングについては、場所によっては、１台３０万円ぐらいで、両面で、運転手側と反対側で両方やったら６０万円とか、そういうふうなものをやっているところもあるというところです。今のところ、品川区はまだそこまでの様子が見られないように見られるので、ここの部分、ぜひとも積極的に区としても広告を増やしていく、そちらのほうでやっていただきたいなと思いますが、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"やはり品川区のコミュニティバスは、地域の方に利用いただいて、地域の沿線の方々、事業者、商店街の方々のＰＲ、広告のために積極的にお使いいただくということが一番効果的なのかなという意味では、この沿線の連絡会の中で、そうした積極的な周知、ＰＲを図っていく。","id":"exchange-149"},{"speaker":"松本委員","kind":"質問・要望","question":"正に地域の活性化にもなるかと思いますので、そこの点は地域と連携しながら、東急バスとも連携しながら、増やしていただきたいなというふうに思います。次に移ります。昨日の議論では、この後、合意すれば、次にまた都のほうで条例案が上がってくるというお話があったかと思うのですが、これ、この後、合意に至らない場合はどうなっていくのか伺います。","respondent":"黒田財政課長","answer":"いわゆる調整税の歳入フレームは東京都のほうで予算を組んでいますから、これは合意をしなくても、その税収は上がってくるということを前提としますと、これ、合意しませんと、令和４年度分でしか算定ができませんので、算定残がかなり出ると。","id":"exchange-150"},{"speaker":"松本委員","kind":"質問・要望","question":"それは区としては結構困ったことになると思うのですけれども、やはり特別区長会として、ぜひともやっていただきたいのが、これまでも５５.１対４４.９ですか、この割合で、結局、児童相談所を区も設置できるようになった。これをもっと積極的に、例えば特別区長会で記者会見をやるとか、そういうことも必要かと思いますが、いかがでしょうか。","respondent":"黒田財政課長","answer":"区長会でも引き続き協議しておりますので、そういったところも含めて、区側としても発信していきたいというふうに考えてあります。","id":"exchange-151"},{"speaker":"吉田委員","kind":"質問","question":"９５ページと１１５ページで、すまいるスクール運営費、それから、１５９ページのプラ製容器包装等・再資源化支援事業補助金について伺いたいと思います。なぜ五反田ではないのかということを伺ったところ、渋谷区のプラネタリウムのほうが圧倒的に性能がいい、それがまず１つ。ただ、障害者への配慮としての施設利用料の扱いは、品川区ではどのようになっているのでしょうか。それをまず伺います。","respondent":"山崎文化スポーツ振興部長","answer":"プラネタリウムの利用料につきましては、大人の方が２００円をいただく形、それから、４歳から中学生までの方につきましては５０円というようなところで、一般的な公共施設の利用相場からすると。","id":"exchange-152"},{"speaker":"吉田委員","kind":"質問","question":"つまり、障害者手帳を見せても、それ以上の減免はないという理解でしょうか。それから、ほかの施設についても伺いたいのです。運動施設については利用料が免除、減になっているのですけれども、それ以外は、各施設にお問合せくださいなので、それぞれ違うかと思うのですけれども、教えていただけますか。","respondent":"山崎文化スポーツ振興部長","answer":"例えば、みんなでプラネタリウムを見て云々というようなことも成立するかなというふうには思ってありますので、何か少し曖昧な答弁で大変恐縮ですが、よろしくお願いいたします。","id":"exchange-153"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひ、もし何か見解があったら、伺いたいと思います。委託内容はかなり多岐にわたっていて、全部で１５項目、例えば、保護者の依頼により預かった児童用のアドレナリン自己注射薬、またはアレルギー薬ほかの管理とか、要保護児童等の早期発見、これ、なかなか難しいのではないかと思うのですけれども、それから、要保護児童の予防への配慮も行うことも区として求めていることが確認できました。","respondent":"廣田子ども育成課長","answer":"いつのときの情報公開か分からないのですけれども、８者あるかと思うのですけれども、仕様書も私も手元で見たのですが、少し内容が合っていないのですが、おおむね内容はあれなのですけれども、障害者、配慮が必要な児童に対する見守り等なのですけれども、義務教育の学校等だと。","id":"exchange-154"},{"speaker":"吉田委員","kind":"質問・要望","question":"今、課長からもありましたとおり、もちろんこの内容で委託をすることは必要ですけれども、やはり受け止める事業者としては、かなりの力量を求められるものだなと思ったので、その辺について、具体的に、今どのように運営されているかということが確認できたのでよかったと思います。そういうときには、やはりそれはそれできちんと配慮してくださる。","respondent":"廣田子ども育成課長","answer":"もちろんご配慮をさせていただいておりまして、今度もう新１年生が入りますけれども、４月はそれまで幼稚園、保育園だった子も参りますし、また、トイレまでの距離が、学校だと遊んでいる場所で遠かったりするので、低学年であったりとか、配慮が必要。","id":"exchange-155"},{"speaker":"吉田委員","kind":"確認","question":"分かりました。よかったです。そのようにお伝えしたいと思います。何か少し行き違いとか勘違いがあったのではないかというふうに思います。ただ、先ほども言いましたとおり、業務を受ける側は結構大変かなというふうに思いますが、その事業者が、ＳＮＳ上の求人広告というのですか、マイナビバイトで、楽しみながら働きたい人、資格や経験は必要なしということで人員募集をしているものを確認いたしました。","respondent":"廣田子ども育成課長","answer":"事業者が求人しているのは私も見たことがありますけれども、仕様書の中に、放課後児童支援員という資格を持った人が、子どもの人数に対して何人いなければならないということが書いてありまして、それ以外は、無資格の人もいていいという。","id":"exchange-156"},{"speaker":"吉田委員","kind":"確認","question":"いろいろ確認できてよかったです。ぜひ両方、区のほうはしっかり委託してほしいし、受け止めるほうは、なかなか厳しい条件ではあるけれども、しっかり受け止めていただいていることを区としても確認しながら運営されているということで理解をいたしました。もう時間がないので、その後の質問は衛生費のところで伺います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-157"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"１０３ページ、災害時応急物資確保費、６７ページ、八潮北公園スケートボード場、６９ページ、ボルダリング場についてお伺いします。防災課でブースを出すというふうになっているのですけれども、この無人航空機、確認だけです。無人航空機は、区の職員の方の操作で飛行をされるのかということだけお知らせいただきたいと思います。","respondent":"平原防災課長","answer":"３月１１日に開催予定の防災フェアにおける無人航空機のデモ飛行につきましては、区の職員が行います。","id":"exchange-158"},{"speaker":"高橋（伸）委員","kind":"確認","question":"無人航空機は、免許がないと多分できないと思いますけれども、区の職員の方は、大体何人ぐらい免許を持っておられますか。それだけ確認だけさせてください。","respondent":"平原防災課長","answer":"現時点では、職員５名が取得しておりまして、追加で２名、今、取得の練習中です。","id":"exchange-159"},{"speaker":"高橋（伸）委員","kind":"質問","question":"分かりました。ぜひ今後とも有事が起きたとき、あるいは訓練のときにも、職員の方、５名の方のデモ飛行もぜひ今後ともよろしくお願いいたします。以上です。ありがとうございました。６７ページ、スケートボードについてお伺いします。","respondent":"高梨公園課長","answer":"過去、ポスター等を作って周知したところなのですが、改めて八潮北公園のスケートボード場をしっかりと、品川区にあるアーバンスポーツのできる箇所ということで、周知の内容についても今後検討していく必要があるかというふうに考えてあります。","id":"exchange-160"},{"speaker":"高橋（伸）委員","kind":"質問","question":"ぜひよろしくお願いします。八潮北公園スケートボード場のポスターなのですけれども、しながわ中央公園のところに、ポスター、公衆便所の入り口に掲示してあるのです。６９ページ、ボルダリング場についてお伺いいたします。ボルダリング場の運営についてお伺いいたします。午前中の質疑にもありましたけれども、今回、ボルダリングをなぜ選ばれたのか、事業の趣旨をご説明をお願いいたします。","respondent":"辻スポーツ推進課長","answer":"委員も今おっしゃいましたとおり、省スペースでも楽しんでできるということで、ぜひ品川でも、子どもたちを元気づけてもらうという、また、種目もたくさんの、今まであったスポーツではない種目を増やすという意味で、こちらの設置を決定したところです。","id":"exchange-161"},{"speaker":"高橋（伸）委員","kind":"質問","question":"４月、施設がオープンするというところで、オープニングイベントを開催をするとプレス発表の中にも記載がありましたけれども、そこで絶好のチャンスなので、私の思いです、ブレイクダンスとか、皆さんに魅力を発信していただけたら、すごく、一番効果的な、品川区にとっても、アーバンスポーツの啓発普及にとってもすばらしい、重要なことになるのかと思っていますので、お考えをお聞きしたいと思います。","respondent":"高梨公園課長、辻スポーツ推進課長","answer":"安全面については、４ｍの高さの下には、厚さ３０cmのマットを敷いて安全面に配慮いたしますが、当然、施設そのものがしっかりと安全に使用できるように管理することはもちろん、施設を利用される方々に。私からは、オープニングイベント等についてお答えいたします。オープニングイベントを開催する予定でして、一定程度有名なボルダリングの選手をお呼びしたりということは考えております。","id":"exchange-162"},{"speaker":"大倉委員","kind":"質問","question":"１０１ページ、公園・児童遊園整備費から、これはどういう内容なのか教えてください。同じ１０１ページ、武蔵小山駅周辺地区再開発事業の内容、これは予算の内容も教えてください。１３５ページ、部活動指導員配置経費補助金から、これも伺っていくのと、スポーツの地域移行をあわせて伺いたいと思います。こうした２名体制になっていった経緯について教えてください。","respondent":"高梨公園課長、多並都市開発課長、矢部教育総合支援センター長、中谷指導課長","answer":"その下、公園・児童遊園整備費につきましては、現在行っていますしながわ区民公園の再整備に伴う北側ゾーンの２期工事の工事請負費に対しまして。設立を予定しておりますが、その後の事業の設計調査等に必要な補助に対しての財源として。部活動指導員です。こちらは、地域移行も含めまして、学校があと一歩進めるために、２人ずつ配置できるような予算案を計上したものです。現在、次年度の教育課程の編成に向けて、地域移行につきましては、まず。","id":"exchange-163"},{"speaker":"大倉委員","kind":"質問・要望","question":"増えてきてはいるのかと、徐々に増やす努力もされている中で、公園の箇所数、２８０か所ということで、これを見てみると、やはりなかなかバランスがとれていないというところでは、例えば、品川地区だと６６か所で、１人当たり２.１４m2とか、大崎地区３４か所、１人当たり０.５２m2、大井地区５７か所、２.５８m2とか、荏原地区は１１３か所あるけれども、人口の関係で１.２５m2と、今。","respondent":"高梨公園課長、多並都市開発課長、辻スポーツ推進課長","answer":"区といたしましては、なかなか用地の確保は難しいような状況ですが、条例で定める面積を目指して。ただ、地域の方、または新しく住まわれた方々、再開発ビルに住まわれている方々からもご意見があって。今現在でも、教育委員会側といろいろと検討を重ねながら、どういった形で移行していくのかということを。","id":"exchange-164"},{"speaker":"大倉委員","kind":"質問・要望","question":"公園、住民１人当たりの面積５m2以上ということで、様々努力していただいているかと思いますので、その点は、これは引き続きやっていっていただきたいのですけれども、これ、人口が増えれば増えるほど１人当たりは増えていくなと思っていて、その辺はどういうふうにお考えなのかということと、公園を改修する際に、以前もあったのですが、遊具については、西霧ヶ谷公園だったかと思いますが。","respondent":"高梨公園課長、中谷指導課長","answer":"今、委員ご指摘ありましたように、何か支障物をとれば、また一回り大きな遊具が設置できるということもあろうと思いますので、しっかりと周辺の状況等を調査して、また。現在、学校のほうから、次年度の取組で部活動指導員としてのお願いをさせていただきたいという人材についてですが、例えば、元教員で部活動指導経験のある方ですとか。","id":"exchange-165"},{"speaker":"大倉委員","kind":"質問・要望","question":"部活動のほうなのですが、教育委員会としては、そのようなご答弁でいいかと思うのですが、地域のスポーツとの連携というところでは、協力しながらというところで、地域スポーツ、連盟とかとの話し合いとか、その辺のことは、地域コーディネーターだけではできないのかと思うのですが、その辺しっかり横串というか、課と連携しながら進めていっていただきたいと思うのですが、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-166"},{"speaker":"大倉委員","kind":"質問・要望","question":"１つ進めていくというお話も先ほどあったかと思うのですが、ぜひそういった好事例を参考にしながら進めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-167"},{"speaker":"いながき委員","kind":"質問","question":"これに関して、道路の脇に、今、２ｍしか歩道がとれなかったというお話でしたが、私、ここは歩道ではなく、敷地というふうに伺いました。どちらが正解なのかを伺います。それと、これは本来、説明だと、高木はビル風対策というふうに伺っていたような気がします。けれども、今回、低木にしてしまったことによって、ビル風に対しての手当ては、どういった方向になってしまったのかということをお尋ねします。","respondent":"多並都市開発課長","answer":"武蔵小山についてお答えいたします。１点目の、先ほどのご説明の繰り返しになりますけれども、敷地内の歩道です。敷地内に歩行者が歩ける空間ということですので、公道、いわゆる道路ではなくて、歩行者が通れる空間を先ほど歩道と説明しました。敷地の中という答えです。","id":"exchange-168"},{"speaker":"いながき委員","kind":"質問","question":"そうなると、歩道というよりは、やはり敷地内という理解で、このお隣のパルムと何とか、名前はごめんなさい、忘れてしまったのですけれども、その敷地内ということで、品川区が所持している歩道という意味ではないという理解でよろしいでしょうか。","respondent":"多並都市開発課長","answer":"品川区が所有している土地ではなくて、武蔵小山パルム駅前地区という市街地再開発事業の区域内ですので、その持ち主の方々が共有でお持ちの土地、民間の土地になります。","id":"exchange-169"},{"speaker":"いながき委員","kind":"質問","question":"私がお伝えしたかったのは、道路が８ｍあるということであれば、通常、道路の脇に歩道がなければ危ないと思うのです。このときはたしか植栽があって、歩道部分といわれる敷地が歩けなくて、わざわざ道路に出てしまっていたという方たちの訴えだったと思います。そもそも８ｍ道路をつくった際に、歩道がきちんとつくられていれば、そういったこともなかったのではないかと思うので、その見解を伺います。","respondent":"多並都市開発課長","answer":"その一環として今回も行ったものであり、都市計画、まちづくりの中でしっかり確認させていただきながら進めている事業、そういうふうにご理解いただければと思います。","id":"exchange-170"},{"speaker":"石田委員","kind":"質問・要望","question":"私からは、５０ページの特別区民税の増収について、そして、増収している全体的なこの歳入は、区民や中小業者の暮らしの支援に使うことを求めて質問します。令和５年度の新年度予算は、今日は歳入ですけれども、１,９８７億９,４００万円。なぜ高額所得者が増えているのか、そして、なぜ５０代が多いのか、区はこの理由をどう考えていますか、伺います。","respondent":"提坂税務課長","answer":"昨日も申し上げましたが、もう一度説明しますけれども、所得というか課税標準額が７００万円を超える方の比率は約１１％なのですが、その方たちが占める所得割税額が約４５％です。ですから、少ない人数でかなりの所得割の税額を負担しているということです。","id":"exchange-171"},{"speaker":"石田委員","kind":"質問","question":"７００万円超えの方が増えていることは昨日も説明されたので分かっているのですけれども、なぜ増えているのか、そういう所得の方が品川区に増えたということなのですよね。再開発が進んで１棟ビルが建つと、もう数百人、一気に世帯が増えるという状況ですので、人口はそういうことで増えるのかと。再開発が大きな要因だと思うのですけれども、いかがでしょうか。","respondent":"多並都市開発課長","answer":"その地区につきましては、例えば、先ほどもご説明しましたが、駅前に駐車場があって、なかなか高度利用が図れていないような土地であったり、そういうものを皆さんで考えて共同で建物の計画をしていく事業であります。","id":"exchange-172"},{"speaker":"石田委員","kind":"質問","question":"だから、要するに、再開発によって人口が増え、そういう再開発マンションを購入できる高額所得者が増えているということで、再開発によって増えていることも１つの要因として考えていいですかということをお聞きしたのです。","respondent":"多並都市開発課長","answer":"そういう大きな考え方の中ですけれども、皆さんとしては、その地区をよくしていこうと考える中で今につながっていると、そういうご理解をいただきたいと思ってあります。","id":"exchange-173"},{"speaker":"石田委員","kind":"質問・要望","question":"それで、そういう方も増えているのですけれども、そこには格差が私はあるのではないかと思います。所得階層別に、人数または割合が分かれば、７００万円を超えている方、２００万円から７００万円の方、そして２００万円以下の方、この３つの分類で分かれば教えていただきたいのですが。","respondent":"提坂税務課長","answer":"比率でよろしいですか。","id":"exchange-174"},{"speaker":"石田委員","kind":"質問・要望","question":"代表質問でも、物価高騰に苦しむ区民や中小事業者の実態をどう受け止めるかと伺いましたが、区は、この間の物価高騰等は、区民や中小企業を直撃し、経済的な負担や不安を抱える方が多くいると認識しているという答弁でした。この間の代表質問や、昨日の最終補正でも、区として重い負担に苦しむ区民へ直接支援をということで求めてきました。なぜやらないのか伺いたいと思います。","respondent":"黒田財政課長","answer":"ですので、そういった意味では、こちらのほうに計上している予算は、必要な事業に対して財源を示すですので、それにプラスアルファで、各個人の方でありますとか、事業者にいわゆる所得を保障するといった意味では、区単独ではなかなかできる。","id":"exchange-175"},{"speaker":"石田委員","kind":"質問・要望","question":"認識している下で、区が直接やらずに、国や都の動向を注視することが理解できないのです。なので、個人個人の所得を応援するとかではなくて、暮らしを、要は、今、物価高騰で苦しみ、どこにどれをどれだけ節約してやりくりしようかと言っている、こういう悲鳴が上がっている中で、区がそこに独自に支援をすることが求められていると思いませんか、伺います。","respondent":"黒田財政課長","answer":"令和２年度には、コロナ禍というところで、区民の方に活力を取り戻していただこうということで、しながわ活力応援給付金ということで、そういった政策判断をして１３４億円の支出をしたこともありますので、そういった中では、１年を通じた行政活動として、しっかり福祉も含めて。","id":"exchange-176"},{"speaker":"石田委員","kind":"質問・要望","question":"今日は歳入ですけれども。なので、そういう区民への必要な予算として、改めて直接支援をするべきではないかと思いますし、求められていると思いませんかということと、あと、国や都の財源で、この間、物価高騰対策等が行われています。それをやらずに、国や都の動向待ちにしているということは、区独自でやる気がないということなのか、そう思われても仕方がないと思うのですけれども、いかがでしょうか。","respondent":"黒田財政課長","answer":"今回の令和５年度の歳入予算につきましては、いろいろ新しい施策も打ち出しています。","id":"exchange-177"},{"speaker":"石田委員","kind":"質問","question":"足立区、豊島区、渋谷区、江戸川区、板橋区、台東区、中野区等々、今年に入って区独自で直接支援を行っています。苦しい区民の負担軽減のための社会保障や福祉の充実は拒みながら、国の改悪にも何も言わずに、そして一方で、大企業のもうけのための超高層再開発には躊躇なく財源を使って、それによって増えた税収、それを暮らしの応援として区独自に使う考えはないということなのでしょうか、伺います。","respondent":"黒田財政課長","answer":"予算ですので、積極的に編成して、区の独自の政策を行っているものです。","id":"exchange-178"},{"speaker":"塚本委員","kind":"質問","question":"私からは、１１１ページの防犯設備整備補助金、それから９１ページの新型コロナウイルスワクチン接種負担金についてお伺いしたいと思います。防犯カメラの設置経費とか、そういうことではないかと思いますけれども、お伺いしたいと思います。","respondent":"森田生活安全担当課長","answer":"防犯設備整備補助金についてのご質問です。この増額理由としましては、令和４年度の実績で、１７４台の防犯カメラの設置ということで、令和３年度は予算を５,４００万円としておりましたが、それを上回る希望がございまして、実績増として増額しています。","id":"exchange-179"},{"speaker":"塚本委員","kind":"質問","question":"この防犯カメラを、今、たくさん実績としてつけた町会とか商店街とかということでございましたけれども、このニーズというか、今後の設置の考え方というか、設置の状況、防犯カメラは、今後、防犯性を高めるためにどういうところにつけていくべきものと考えているのかもお伺いしたいと思います。","respondent":"森田生活安全担当課長","answer":"設置の考え方ですが、これはやはり、防犯カメラの補助金のあり方みたいなものも、補助金自体をまだご存じでない町会もありますので、そういったところにはしっかりとご説明をしてやっていきたいと、そのように思っているところです。","id":"exchange-180"},{"speaker":"塚本委員","kind":"質問・要望","question":"そういう意味では、パトロールは、今はもう目いっぱいという感じなのか、まだ拡大できるというか、もっと手厚くできるような余地はあるのか、パトロールの強化みたいなことは、どういうふうに、今、状況として捉えていらっしゃるのかお伺いしたいと思います。","respondent":"森田生活安全担当課長","answer":"今、私どものパトロールとしますと、青色回転灯をつけまして、５台のパトロールカーがありますが、全てが出ているわけではありませんが、シフトを組みながら品川区内全域に回っているところです。","id":"exchange-181"},{"speaker":"塚本委員","kind":"質問","question":"もう１つは、地域の目です。そういう中で、♯９１１０も案内されているわけですけれども、この辺の２つの、♯９１１０なのか、１１０番なのか、この辺のどちらにすればいいのだということを迷う区民の方々が結構いらっしゃるのですけれども、ここについての、どうなのだという見解です、難しいのですけれども、どっちもどっちで正義というか、意味があるのですけれども、ここをお伺いしたいと思います。","respondent":"森田生活安全担当課長","answer":"緊急に、今この場で何かが起こっている、すぐにでも対応してほしいという方は、遠慮なく１１０番という形でしていただければと思います。これは遠慮してしまって、♯９１１０につながったとしても、警察ですので、対応は当然緊急の対応とさせてはいただきます。","id":"exchange-182"},{"speaker":"塚本委員","kind":"質問","question":"時間がないので、最後に簡単にお伺いします。今後の接種体制、まだ無償化でこの先もワクチンの接種は続くということでなっているかと思いますが、予約方法、接種会場、あるいはまたＶＲＳの登録などの運用、こういったことで今後の変更等が起こるような部分があるのか、その点だけお伺いしたいと思います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"今週の木曜日、明後日、我々のほうに自治体説明会がありまして、そこで詳細が示されることとなっておりますが、少なくとも令和５年度、令和６年３月３１日までは無料で接種が行われるというふうに聞いております。","id":"exchange-183"},{"speaker":"渡辺委員","kind":"質問","question":"１３１ページで都市防災不燃化促進事業、また、密集住宅等、その件から防災街区、要は、一番軸は特定整備路線について伺います。ただし、やはり課題なり、多くの方の深い理解があるということも承知していただきながら、区の役割を伺っていきます。この特定整備路線、現在の区間、それぞれ区分されている、たしか６か所だったと思いますが、それぞれの用地取得率の最新の情報を教えてください。","respondent":"鈴木都市計画課長","answer":"事業期間ですが、延伸がなされておりまして、現在の事業期間が令和８年３月３１日というような状況です。","id":"exchange-184"},{"speaker":"渡辺委員","kind":"質問","question":"それだけいろいろな意味で、人の感情とともに注目しつつあり、大事な道路政策だと思っています。東京都が進めています。でも、品川区は、協力はしていくけれども、私の見解でいえば、やはり区民が頼りにするのは品川区だと思うのです。そういう意味で、品川区の役割と立ち位置の感じを教えてください。そして、先ほど言いました地域の声、懸念、そういったことをどのように把握しているか教えてください。","respondent":"大石木密整備推進課長","answer":"道路建設予定地ですので、その利用については一定程度の制約がありますが、区としては、地域の声をしっかりと受け止めながら、１つずつ東京都に働きかけていく、そういうことです。","id":"exchange-185"},{"speaker":"渡辺委員","kind":"質問・要望","question":"ここだけは単に道路ではなくて、にぎわいの維持のために大きな大きな力を貸していただきたいと思っています。それは恐らく小さければ、ちょっとした案内板や情報発信のスペース、あるいはモニュメントだとか、にぎわいを少しでも少しでも維持できるような知恵があると思いますので、２点、商店街を軸にしたにぎわいの維持と、そして、残地の活用を積極的に、この２点でぜひ抱負、決意を伺いたいと思います。","respondent":"大石木密整備推進課長","answer":"もう１つ、残地の活用ですが、こちらにつきましては、まだどういった形で残地が活用されるかということも東京都からは情報を得ておりません。区としてどのような活用方法ができるのかということは、引き続き東京都の動向も注視しながら検討していきたいと思います。","id":"exchange-186"},{"speaker":"渡辺委員","kind":"質問","question":"最後に、ここまでまだまだスタートだと思っています。ただ、これまで本当にそれぞれの職員の方、丁寧に対応していただいて、そして地域がすごくそこで勇気づけられている。そして、すごくいい知恵も出てきていますので、このスタートを本当に感謝もしていますし、これからの期待を大きく持って質問を終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-187"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/491981?Template=document&Id=1164#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":132533,"voices":447}},{"id":"r05-20230307-10","meetingId":"r05-cm03","date":"2023年3月7日","dateIso":"2023-03-07","committee":"議会運営委員会","time":"午後 ６時０９分～午後 ６時１３分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件抜き出しています。","topics":[{"id":"topic-01","title":"その他","agenda":"その他","exchanges":[{"speaker":"大倉委員","kind":"質問・要望","question":"前回の議会運営委員会から、くにば議員の欠席の件について、少し状況が変わりましたので、ご報告させていただきたいと思います。本人と少しお話ししましたが、議会に出たいという気持ちはあるのですが、なかなか体調のほうで出席ができない状況であるということで、議長にもそのように説明させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/105128?Template=document&Id=5500#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":1565,"voices":13}}]);
